#[derive(Debug, Clone, Copy)]
enum AgentBootstrapStepKind {
    Template,
    Runtime,
    Workspace,
    Model,
    InitialMessage,
}

fn agent_bootstrap_step_mut(
    bootstrap: &mut AgentBootstrapRecord,
    kind: AgentBootstrapStepKind,
) -> &mut AgentBootstrapStep {
    match kind {
        AgentBootstrapStepKind::Template => &mut bootstrap.template,
        AgentBootstrapStepKind::Runtime => &mut bootstrap.runtime,
        AgentBootstrapStepKind::Workspace => &mut bootstrap.workspace,
        AgentBootstrapStepKind::Model => &mut bootstrap.model,
        AgentBootstrapStepKind::InitialMessage => &mut bootstrap.initial_message,
    }
}

fn bounded_bootstrap_error(error: &anyhow::Error) -> String {
    const MAX_CHARS: usize = 512;
    let summary = error.to_string();
    if summary.chars().count() <= MAX_CHARS {
        return summary;
    }
    summary.chars().take(MAX_CHARS).collect()
}

/// Default bootstrap initialization message for agents created without an
/// explicit `initial_message` (#2795): a runtime-owned, deterministic-id
/// instruction that makes the new agent run one initialization turn so its
/// conversation is not empty. Mirrors the `first_run_intro` contract.
fn default_agent_bootstrap_initial_message(
    bootstrap: &AgentBootstrapRecord,
) -> AgentBootstrapInitialMessage {
    AgentBootstrapInitialMessage {
        message_id: bootstrap.initial_message_id(),
        text: default_agent_bootstrap_initial_message_text().to_string(),
        authority_class: AuthorityClass::RuntimeInstruction,
        creator_agent_id: String::new(),
    }
}

fn default_agent_bootstrap_initial_message_text() -> &'static str {
    "This agent was just created without an initial message. Perform a one-time \
     initialization turn: read your AGENTS.md and template contract, note your \
     installed skills and workspaces, then briefly introduce yourself to the user — \
     your role, what you can do, and a few starter actions. Keep it friendly and \
     concise; do not invent tasks or modify files. Choose the user's most likely \
     language from trusted preferences and environment hints such as locale or \
     timezone; adapt if the user replies in another language."
}

fn named_agent_already_exists_error(agent_id: &str) -> anyhow::Error {
    anyhow::Error::from(
        ToolError::new(
            "already_exists",
            format!("public named agent {agent_id} already exists"),
        )
        .with_domain(crate::runtime_error::RuntimeErrorDomain::Conflict)
        .with_details(json!({
            "agent_id": agent_id,
            "preset": AgentProfilePreset::PublicNamed,
        }))
        .with_recovery_hint(
            "use an explicit agent invocation or enqueue operation to deliver work to an existing agent",
        ),
    )
}

fn named_agent_name_already_exists_error(agent_id: &str, name: &str) -> anyhow::Error {
    anyhow::Error::from(
        ToolError::new(
            "already_exists",
            format!("public named agent name {name:?} is already in use"),
        )
        .with_domain(crate::runtime_error::RuntimeErrorDomain::Conflict)
        .with_details(json!({
            "agent_id": agent_id,
            "name": name,
            "preset": AgentProfilePreset::PublicNamed,
        }))
        .with_recovery_hint("choose a different name for the new public named agent"),
    )
}

fn named_agent_deletion_incomplete_error(
    agent_id: &str,
    job: Option<&AgentDeletionJob>,
) -> anyhow::Error {
    let mut details = json!({
        "agent_id": agent_id,
        "preset": AgentProfilePreset::PublicNamed,
    });
    let message = match job {
        Some(job) => {
            details["deletion_id"] = json!(job.deletion_id);
            details["deletion_status"] =
                serde_json::to_value(job.status).unwrap_or(serde_json::Value::Null);
            details["deletion_phase"] =
                serde_json::to_value(job.phase).unwrap_or(serde_json::Value::Null);
            if let Some(last_error) = &job.last_error {
                details["last_error"] = json!(last_error);
            }
            format!(
                "agent {agent_id} has an incomplete deletion (status {:?}); the id cannot be reused until the deletion completes",
                job.status
            )
        }
        None => format!(
            "agent {agent_id} was deleted without a completed deletion job; the id cannot be reused"
        ),
    };
    anyhow::Error::from(
        ToolError::new("deletion_incomplete", message)
            .with_domain(crate::runtime_error::RuntimeErrorDomain::Conflict)
            .with_details(details)
            .with_recovery_hint(
                "inspect the agent delete-status, let the deletion complete or resolve its failure, then retry create",
            ),
    )
}

fn named_agent_cleanup_repair_started_error(
    agent_id: &str,
    job: &AgentDeletionJob,
) -> anyhow::Error {
    anyhow::Error::from(
        ToolError::new(
            "deletion_cleanup_repair_started",
            format!("agent {agent_id} cannot be recreated until cleanup repair completes"),
        )
        .with_domain(crate::runtime_error::RuntimeErrorDomain::Conflict)
        .with_details(json!({
            "agent_id": agent_id,
            "deletion_id": job.deletion_id,
            "deletion_status": job.status,
            "deletion_phase": job.phase,
            "deletion_mode": job.mode,
            "repair_admitted": true,
        }))
        .with_recovery_hint(
            "wait for the cleanup repair to complete, then retry creating the agent",
        )
        .with_retryable(true),
    )
}

fn named_agent_invalid_name_error(agent_id: &str, error: anyhow::Error) -> anyhow::Error {
    anyhow::Error::from(
        ToolError::new("agent_name_invalid", error.to_string())
            .with_domain(crate::runtime_error::RuntimeErrorDomain::Validation)
            .with_details(json!({
                "agent_id": agent_id,
                "preset": AgentProfilePreset::PublicNamed,
            }))
            .with_recovery_hint("choose a valid name for the new public named agent"),
    )
}

fn named_agent_create_failed_error(
    agent_id: &str,
    stage: AgentCreateStage,
    source: anyhow::Error,
) -> anyhow::Error {
    source.context(
        ToolError::new(
            "agent_create_failed",
            format!("failed to create public named agent {agent_id}"),
        )
        .with_details(json!({
            "agent_id": agent_id,
            "preset": AgentProfilePreset::PublicNamed,
            "stage": stage,
        }))
        .with_recovery_hint(
            "inspect the creation stage and retry after correcting the reported failure",
        ),
    )
}

#[derive(Debug, Clone)]
pub(crate) struct ChildTaskTerminalResult {
    pub status: TaskStatus,
    pub text: String,
    pub task_detail: Option<Value>,
}

impl crate::runtime_db::agent_message_delivery::MessageWaitOutcome {
    pub(crate) fn terminal_result(
        &self,
        storage: &AppStorage,
        boundary: i64,
    ) -> Result<ChildTaskTerminalResult> {
        use crate::runtime_db::agent_message_delivery::MessageWaitReply;
        let mut detail = json!({
            "sender_agent_id": self.target_agent_id,
            "recipient_agent_id": self.owner_agent_id,
            "message_wait_after_delivery_rowid": boundary,
            "business_completion": false,
        });
        let text = match &self.reply {
            MessageWaitReply::Explicit {
                delivery_id,
                message_id,
            } => {
                detail["message_wait_satisfied"] = json!(true);
                detail["message_id"] = json!(message_id);
                detail["response_delivery_id"] = json!(delivery_id);
                detail["reply_content_source"] = json!("original_message");
                format!("Agent reply received; see message {message_id} / delivery {delivery_id}.")
            }
            MessageWaitReply::FinalBrief {
                message_id,
                activation_id,
                turn_id,
                brief_id,
            } => {
                let message = storage
                    .read_message_by_id(message_id)?
                    .ok_or_else(|| anyhow!("final-brief reply outbox content is missing"))?;
                let MessageBody::Text { text } = message.body else {
                    return Err(anyhow!("final-brief reply outbox content is invalid"));
                };
                anyhow::ensure!(!text.trim().is_empty(), "final-brief reply outbox is empty");
                detail["message_wait_satisfied"] = json!(true);
                detail["message_id"] = json!(message_id);
                detail["reply_content_source"] = json!("runtime_derived_final_brief");
                detail["reply_source"] = json!({
                    "request_delivery_id": self.request_delivery_id,
                    "activation_id": activation_id, "turn_id": turn_id, "brief_id": brief_id,
                    "outbox_committed_at": self.committed_at,
                });
                text
            }
            MessageWaitReply::ReplyTimeout { deadline_at } => {
                detail["failure_reason"] = json!("reply_timeout");
                detail["reply_timeout"] = json!({
                    "deadline_at": deadline_at, "request_delivery_id": self.request_delivery_id,
                });
                return Ok(ChildTaskTerminalResult {
                    status: TaskStatus::Failed,
                    text: "Agent reply wait expired (reply_timeout); the target is not stopped and the request is not resent.".into(),
                    task_detail: Some(detail),
                });
            }
        };
        Ok(ChildTaskTerminalResult {
            status: TaskStatus::Completed,
            text,
            task_detail: Some(detail),
        })
    }
}

