    pub async fn create_named_agent(
        &self,
        agent_id: &str,
        template: Option<&str>,
    ) -> Result<AgentIdentityRecord> {
        let desired = AgentBootstrapDesiredState {
            template: template.map(ToString::to_string),
            catalog_agent_home: None,
            workspace: None,
            model_resolution: None,
            initial_message: None,
            default_initial_message: false,
        };
        let (identity, created) = self
            .ensure_named_agent(
                agent_id,
                None,
                NamedAgentExistingBehavior::Reuse,
                None,
                desired,
            )
            .await?;
        if created {
            self.reconcile_agent_bootstrap(agent_id).await?;
        }
        Ok(identity)
    }

    pub async fn create_public_named_agent(
        &self,
        agent_id: &str,
        template: Option<&str>,
        lineage_parent_agent_id: Option<&str>,
        catalog_agent_home: Option<&Path>,
    ) -> Result<AgentCreateResult> {
        // Test/compat wrapper: production user-initiated creations should
        // call `create_public_named_agent_with_name` and state whether the
        // default bootstrap initialization message is requested (#2795).
        self.create_public_named_agent_with_name(
            agent_id,
            template,
            lineage_parent_agent_id,
            catalog_agent_home,
            None,
            AgentBootstrapExecution::Inline,
            false,
        )
        .await
    }

    pub async fn create_public_named_agent_with_name(
        &self,
        agent_id: &str,
        template: Option<&str>,
        lineage_parent_agent_id: Option<&str>,
        catalog_agent_home: Option<&Path>,
        requested_name: Option<&str>,
        execution: AgentBootstrapExecution,
        default_initial_message: bool,
    ) -> Result<AgentCreateResult> {
        let desired = AgentBootstrapDesiredState {
            template: template.map(ToString::to_string),
            catalog_agent_home: catalog_agent_home.map(Path::to_path_buf),
            workspace: None,
            model_resolution: None,
            initial_message: None,
            default_initial_message,
        };
        self.create_public_named_agent_with_bootstrap(
            agent_id,
            lineage_parent_agent_id,
            requested_name,
            desired,
            execution,
        )
        .await
    }

    async fn create_public_named_agent_with_bootstrap(
        &self,
        agent_id: &str,
        lineage_parent_agent_id: Option<&str>,
        requested_name: Option<&str>,
        desired: AgentBootstrapDesiredState,
        execution: AgentBootstrapExecution,
    ) -> Result<AgentCreateResult> {
        // The default bootstrap initialization turn requires a usable model
        // provider, mirroring `first_run_intro`. Drop the intent when no
        // provider is ready (e.g. onboarding bootstrap mode) instead of
        // enqueueing a message the new agent cannot run.
        let desired = if desired.default_initial_message && !self.config().default_provider_ready()
        {
            AgentBootstrapDesiredState {
                default_initial_message: false,
                ..desired
            }
        } else {
            desired
        };
        let host = self.clone();
        let agent_id_owned = agent_id.to_string();
        let lineage_parent_agent_id = lineage_parent_agent_id.map(ToString::to_string);
        let requested_name = requested_name.map(ToString::to_string);
        let (identity, created) = self
            .run_owned_external_mutation(async move {
                let bootstrap_lock = host.agent_bootstrap_lock(&agent_id_owned);
                let _bootstrap_guard = bootstrap_lock.lock().await;
                let handoff = host.inner.bootstrap_handoff_lock.lock().await;
                let had_default_agent = host.configured_default_agent_id()?.is_some();
                let prepared = host.prepare_named_agent(
                    &agent_id_owned,
                    lineage_parent_agent_id.as_deref(),
                    NamedAgentExistingBehavior::Reject,
                    requested_name.as_deref(),
                    desired.clone(),
                )?;
                match prepared {
                    NamedAgentPreparation::Ready(identity, created) => {
                        if created && !had_default_agent {
                            let mut config = (*host.config()).clone();
                            config.default_agent_id = identity.agent_id.clone();
                            host.inner.registry.replace_config(config);
                        }
                        Ok((identity, created))
                    }
                    NamedAgentPreparation::Reincarnate(tombstone) => {
                        // No global handoff lock can span an owner wait.
                        drop(handoff);
                        host.reincarnate_deleted_agent(
                            tombstone,
                            lineage_parent_agent_id.as_deref(),
                            requested_name.as_deref(),
                            desired,
                        )
                        .await
                    }
                }
            })
            .await?;
        let (stage, bootstrap_summary) = match execution {
            AgentBootstrapExecution::Inline => {
                let bootstrap = self.reconcile_agent_bootstrap(agent_id).await?;
                (
                    Self::agent_create_stage(&bootstrap.summary()),
                    bootstrap.summary(),
                )
            }
            AgentBootstrapExecution::Background => match self.kick_agent_bootstrap(agent_id)? {
                AgentBootstrapKick::AlreadyComplete(bootstrap) => (
                    Self::agent_create_stage(&bootstrap.summary()),
                    bootstrap.summary(),
                ),
                AgentBootstrapKick::Started(_) => {
                    // Snapshot the durable record for the receipt; the
                    // background reconcile keeps progressing it.
                    let bootstrap = self
                        .runtime_db()
                        .agent_bootstraps()
                        .latest(agent_id)?
                        .ok_or_else(|| anyhow!("agent {agent_id} has no bootstrap state"))?;
                    (AgentCreateStage::Provisioning, bootstrap.summary())
                }
            },
        };
        Ok(AgentCreateResult {
            identity: AgentIdentityView::from_record(&identity, &self.config().default_agent_id),
            receipt: AgentCreateReceipt {
                receipt_id: ids::runtime_id("agent_create"),
                agent_id: identity.agent_id.clone(),
                name: identity.name.clone(),
                display_name: identity.display_name(),
                stage,
                lifecycle: identity.status,
                created,
                job_id: None,
                bootstrap: bootstrap_summary,
            },
        })
    }

    pub(crate) async fn append_agent_creation_audit(
        &self,
        agent_id: &str,
        identity_incarnation: u64,
        event: crate::types::AuditEvent,
    ) -> Result<()> {
        let host = self.clone();
        let agent_id = agent_id.to_owned();
        self.run_owned_external_mutation(async move {
            let mut reservations = host
                .reserve_mutation_scopes(&[(agent_id.clone(), identity_incarnation)])
                .await?;
            anyhow::ensure!(
                host.active_agent_identity(&agent_id)?.incarnation == identity_incarnation,
                "creation Audit identity incarnation differs"
            );
            // Select the original Runtime while deletion/activation is fenced.
            if let Some(runtime) = host.try_get_loaded_runtime(&agent_id).await {
                drop(reservations);
                return runtime.append_original_audit_event(event).await;
            }
            let prior = Arc::new(
                host.external_identity_facts(&reservations)?
                    .pop()
                    .context("creation Audit prior identity missing")?,
            );
            let scope = crate::runtime::resident_input_evidence::InputEvidenceScope {
                agent_id: agent_id.clone(),
                identity_incarnation,
            };
            crate::runtime::append_unloaded_audit_event(
                &host.agent_storage(&agent_id)?,
                host.runtime_db(),
                &scope,
                &prior,
                &host.inner.input_evidence_budget,
                &mut reservations[0],
                event,
            )
        })
        .await
    }

    async fn create_agent(
        &self,
        parent_runtime: RuntimeHandle,
        request: CreateAgentRequest,
    ) -> Result<AgentCreateResult> {
        if let Some(identity) = self.agent_identity_record(&request.agent_id)? {
            if identity.status == AgentRegistryStatus::Deleting {
                let job = self
                    .runtime_db()
                    .agent_deletions()
                    .latest_for_agent(&request.agent_id)?;
                return Err(named_agent_deletion_incomplete_error(
                    &request.agent_id,
                    job.as_ref(),
                ));
            }
            if identity.status != AgentRegistryStatus::Deleted {
                anyhow::ensure!(
                    identity.kind == AgentKind::Named
                        && identity.visibility == AgentVisibility::Public
                        && identity.ownership() == AgentOwnership::SelfOwned,
                    "agent {} already exists with an incompatible identity or lifecycle",
                    request.agent_id
                );
            } else {
                // A fully deleted id is creatable again. Fall through to
                // the creation path: it routes through the reincarnation
                // transaction when the deletion job completed and returns
                // a typed `deletion_incomplete` error otherwise.
                let job = self
                    .runtime_db()
                    .agent_deletions()
                    .latest_for_agent(&request.agent_id)?;
                if !matches!(job.as_ref(), Some(job) if job.status == AgentDeletionStatus::Completed)
                {
                    return Err(named_agent_deletion_incomplete_error(
                        &request.agent_id,
                        job.as_ref(),
                    ));
                }
            }
            if identity.status == AgentRegistryStatus::Active {
                let bootstrap = self.reconcile_agent_bootstrap(&request.agent_id).await?;
                let bootstrap_summary = bootstrap.summary();
                return Ok(AgentCreateResult {
                    identity: AgentIdentityView::from_record(
                        &identity,
                        &self.config().default_agent_id,
                    ),
                    receipt: AgentCreateReceipt {
                        receipt_id: ids::runtime_id("agent_create"),
                        agent_id: identity.agent_id.clone(),
                        name: identity.name.clone(),
                        display_name: identity.display_name(),
                        stage: Self::agent_create_stage(&bootstrap_summary),
                        lifecycle: identity.status,
                        created: false,
                        job_id: None,
                        bootstrap: bootstrap_summary,
                    },
                });
            }
        }

        let parent_state = parent_runtime.agent_state().await?;
        let catalog_agent_home = request
            .inherit_parent_runtime
            .then(|| self.agent_data_dir(&parent_state.id));
        let workspace = request
            .inherit_parent_runtime
            .then(|| AgentBootstrapWorkspaceState {
                attached_workspaces:
                    crate::runtime::workspace::inherited_attached_workspaces_for_agent(
                        &parent_state,
                        &request.agent_id,
                    ),
                execution_profile: parent_state.execution_profile.clone(),
                inherited_model_override: parent_state.model_override.clone(),
                inherited_model_override_service_tier: parent_state.model_override_service_tier,
                inherited_model_override_reasoning_effort: parent_state
                    .model_override_reasoning_effort
                    .clone(),
            });
        let initial_message = request
            .initial_message
            .map(|text| AgentBootstrapInitialMessage {
                message_id: format!("agent_bootstrap_message:{}", request.agent_id),
                text,
                authority_class: request.authority_class,
                creator_agent_id: parent_state.id,
            });
        // #2795: creations without an explicit initial message still request
        // the default bootstrap initialization turn; the bootstrap funnel
        // drops the intent when no model provider is ready yet.
        let default_initial_message = initial_message.is_none();
        let desired = AgentBootstrapDesiredState {
            template: request.template,
            catalog_agent_home,
            workspace,
            model_resolution: request.model_resolution,
            initial_message,
            default_initial_message,
        };
        self.create_public_named_agent_with_bootstrap(
            &request.agent_id,
            request.lineage_parent_agent_id.as_deref(),
            request.name.as_deref(),
            desired,
            AgentBootstrapExecution::Inline,
        )
        .await
    }

    async fn ensure_named_agent(
        &self,
        agent_id: &str,
        lineage_parent_agent_id: Option<&str>,
        existing_behavior: NamedAgentExistingBehavior,
        requested_name: Option<&str>,
        desired: AgentBootstrapDesiredState,
    ) -> Result<(AgentIdentityRecord, bool)> {
        match self.prepare_named_agent(
            agent_id,
            lineage_parent_agent_id,
            existing_behavior,
            requested_name,
            desired.clone(),
        )? {
            NamedAgentPreparation::Ready(identity, created) => Ok((identity, created)),
            NamedAgentPreparation::Reincarnate(tombstone) => {
                self.reincarnate_deleted_agent(
                    tombstone,
                    lineage_parent_agent_id,
                    requested_name,
                    desired,
                )
                .await
            }
        }
    }

    fn prepare_named_agent(
        &self,
        agent_id: &str,
        lineage_parent_agent_id: Option<&str>,
        existing_behavior: NamedAgentExistingBehavior,
        requested_name: Option<&str>,
        desired: AgentBootstrapDesiredState,
    ) -> Result<NamedAgentPreparation> {
        self.validate_agent_id(agent_id)?;
        if agent_id == self.config().default_agent_id
            && self.agent_identity_record(agent_id)?.is_some()
        {
            if existing_behavior == NamedAgentExistingBehavior::Reject {
                return Err(named_agent_already_exists_error(agent_id));
            }
            if desired.template.is_some() {
                return Err(anyhow!(
                    "default agent does not support template initialization through create_named_agent"
                ));
            }
            return self
                .ensure_default_agent_identity()
                .map(|record| NamedAgentPreparation::Ready(record, false));
        }
        if Self::is_temporary_agent_id(agent_id) {
            return Err(anyhow!(
                "agent id {} uses reserved temporary prefix {}",
                agent_id,
                TEMP_AGENT_PREFIX
            ));
        }
        let existing = self.agent_identity_record(agent_id)?;
        if let Some(existing) = existing {
            if existing_behavior == NamedAgentExistingBehavior::Reject {
                if existing.status == AgentRegistryStatus::Deleted {
                    // A fully deleted id is creatable again: route through
                    // the reincarnation transaction when the deletion job
                    // completed, or fail closed with a typed error.
                    return Ok(NamedAgentPreparation::Reincarnate(existing));
                }
                if existing.status == AgentRegistryStatus::Deleting {
                    let job = self
                        .runtime_db()
                        .agent_deletions()
                        .latest_for_agent(agent_id)?;
                    return Err(named_agent_deletion_incomplete_error(
                        agent_id,
                        job.as_ref(),
                    ));
                }
                return Err(named_agent_already_exists_error(agent_id));
            }
            if existing.status != AgentRegistryStatus::Active {
                return Err(anyhow!(self
                    .active_agent_identity(agent_id)
                    .expect_err("non-active identity must be fenced")));
            }
            if existing.kind != AgentKind::Named
                || existing.visibility != AgentVisibility::Public
                || existing.ownership() != AgentOwnership::SelfOwned
                || existing.profile_preset() != AgentProfilePreset::PublicNamed
            {
                return Err(anyhow!(
                    "agent {} already exists with a different identity type; expected a public self-owned named agent",
                    agent_id
                ));
            }
            if desired.template.is_some() {
                return Err(anyhow!(
                    "agent {} already exists; template initialization only applies when creating a new agent",
                    agent_id
                ));
            }
            return Ok(NamedAgentPreparation::Ready(existing, false));
        }
        let normalized_name = requested_name
            .map(|name| {
                normalize_agent_name(name)
                    .map_err(|error| named_agent_invalid_name_error(agent_id, error))
            })
            .transpose()?;
        ensure_agent_home_layout(&self.agent_data_dir(agent_id)).map_err(|error| {
            named_agent_create_failed_error(agent_id, AgentCreateStage::Profiled, error)
        })?;
        let mut record = AgentIdentityRecord::new(
            agent_id,
            AgentKind::Named,
            AgentVisibility::Public,
            AgentOwnership::SelfOwned,
            AgentProfilePreset::PublicNamed,
            None,
            None,
        )
        .with_lineage_parent_agent_id(lineage_parent_agent_id.map(ToString::to_string));
        record.name = normalized_name;
        let bootstrap = AgentBootstrapRecord::new(agent_id, desired);
        let relations = independent_creation_records(
            &record,
            lineage_parent_agent_id,
            AgentCanonicalDurability::Persistent,
        );
        self.runtime_db()
            .agent_identities()
            .create_with_bootstrap_and_relations(&record, &bootstrap, &relations)
            .map_err(|error| {
                if error.to_string().contains("agent_identity_conflict") {
                    return named_agent_already_exists_error(agent_id);
                }
                if let Some(name) = record.name.as_deref() {
                    if error
                        .to_string()
                        .contains("UNIQUE constraint failed: agent_identities.name_key")
                    {
                        return named_agent_name_already_exists_error(agent_id, name);
                    }
                }
                named_agent_create_failed_error(agent_id, AgentCreateStage::Reserved, error)
            })?;
        self.inner.registry.cache_agent_identity(&record)?;
        Ok(NamedAgentPreparation::Ready(record, true))
    }

    /// Creates a new incarnation of a fully deleted agent id. The latest
    /// deletion job must be `Completed`; anything else (in-flight, failed,
    /// or missing) fails closed with a typed `deletion_incomplete` error.
    /// The new incarnation is a fresh agent: new AgentHome bootstrap, no
    /// inherited WorkItems, tasks, waits, timers, triggers, or lineage
    /// beyond the explicitly requested parent.
    async fn reincarnate_deleted_agent(
        &self,
        tombstone: AgentIdentityRecord,
        lineage_parent_agent_id: Option<&str>,
        requested_name: Option<&str>,
        desired: AgentBootstrapDesiredState,
    ) -> Result<(AgentIdentityRecord, bool)> {
        let agent_id = tombstone.agent_id.clone();
        let mut reservations = self
            .reserve_mutation_scopes(&[
                (agent_id.clone(), tombstone.incarnation),
                (agent_id.clone(), tombstone.incarnation.saturating_add(1)),
            ])
            .await?;
        let current = self
            .runtime_db()
            .agent_identities()
            .latest(&agent_id)?
            .context("agent tombstone disappeared while reserving reincarnation")?;
        anyhow::ensure!(
            current.incarnation == tombstone.incarnation
                && current.status == AgentRegistryStatus::Deleted,
            "agent_reincarnation_rejected: tombstone changed while reserving owners"
        );
        let job = self
            .runtime_db()
            .agent_deletions()
            .latest_for_agent(&agent_id)?;
        let completed = matches!(
            job.as_ref(),
            Some(job) if job.status == AgentDeletionStatus::Completed
        );
        if !completed {
            return Err(named_agent_deletion_incomplete_error(
                &agent_id,
                job.as_ref(),
            ));
        }
        if !crate::runtime_db::agent_deletion_cleanup::private_history_purge_proof_is_current(
            self.runtime_db(),
            &agent_id,
            tombstone.incarnation,
        ) {
            let (_, repair_job, created) = self.runtime_db().agent_deletions().begin(
                &agent_id,
                tombstone.revision,
                "agent_create_cleanup_repair",
                false,
            )?;
            if created {
                self.notify_deletion_coordinator();
            }
            return Err(named_agent_cleanup_repair_started_error(
                &agent_id,
                &repair_job,
            ));
        }
        let normalized_name = requested_name
            .map(|name| {
                normalize_agent_name(name)
                    .map_err(|error| named_agent_invalid_name_error(&agent_id, error))
            })
            .transpose()?;
        ensure_agent_home_layout(&self.agent_data_dir(&agent_id)).map_err(|error| {
            named_agent_create_failed_error(&agent_id, AgentCreateStage::Profiled, error)
        })?;
        let scope_count = reservations.len();
        let mut acknowledged = None;
        let committed = self
            .commit_external_metadata(&mut reservations, ids::audit_event_id(), || {
                let identity = self
                    .runtime_db()
                    .agent_identities()
                    .reincarnate_with_bootstrap_and_relations(
                        &agent_id,
                        "agent_create",
                        |tombstone| {
                            let mut record = AgentIdentityRecord::new(
                                &agent_id,
                                AgentKind::Named,
                                AgentVisibility::Public,
                                AgentOwnership::SelfOwned,
                                AgentProfilePreset::PublicNamed,
                                None,
                                None,
                            )
                            .with_lineage_parent_agent_id(
                                lineage_parent_agent_id.map(ToString::to_string),
                            );
                            let now = std::cmp::max(
                                chrono::Utc::now(),
                                tombstone.updated_at + chrono::Duration::nanoseconds(1),
                            );
                            record.name = normalized_name.clone();
                            record.incarnation = tombstone.incarnation.saturating_add(1);
                            record.revision = tombstone.revision.saturating_add(1);
                            record.created_at = now;
                            record.updated_at = now;
                            let bootstrap = AgentBootstrapRecord::new(&agent_id, desired.clone());
                            let relations = independent_creation_records(
                                &record,
                                lineage_parent_agent_id,
                                AgentCanonicalDurability::Persistent,
                            );
                            (record, bootstrap, relations)
                        },
                    )?;
                let facts = (0..scope_count)
                    .map(|_| IdentityMutationFacts {
                        identity: Some(Arc::new(identity.clone())),
                        state: None,
                    })
                    .collect();
                acknowledged = Some(identity.clone());
                Ok((identity, facts))
            })
            .await;
        let identity = match committed {
            Ok(identity) => Ok(identity),
            Err(error) => match acknowledged {
                Some(identity) => self
                    .reconcile_external_mutations(&mut reservations)
                    .await
                    .map(|()| identity),
                None => Err(error),
            },
        }
        .map_err(|error| {
            let message = error.to_string();
            if message.contains("agent_reincarnation_rejected") {
                // The tombstone or deletion job changed concurrently;
                // re-read the job so the typed error carries fresh state.
                let job = self
                    .runtime_db()
                    .agent_deletions()
                    .latest_for_agent(&agent_id)
                    .ok()
                    .flatten();
                return named_agent_deletion_incomplete_error(&agent_id, job.as_ref());
            }
            if let Some(name) = normalized_name.as_deref() {
                if message.contains("UNIQUE constraint failed: agent_identities.name_key") {
                    return named_agent_name_already_exists_error(&agent_id, name);
                }
            }
            named_agent_create_failed_error(&agent_id, AgentCreateStage::Reserved, error)
        })?;
        drop(reservations);
        self.drain_retired_runtime(&agent_id, tombstone.incarnation)
            .await?;
        Ok((identity, true))
    }

    pub(crate) fn agent_bootstrap_lock(&self, agent_id: &str) -> Arc<AsyncMutex<()>> {
        self.inner
            .bootstrap_locks
            .lock()
            .expect("agent bootstrap locks poisoned")
            .entry(agent_id.to_string())
            .or_insert_with(|| Arc::new(AsyncMutex::new(())))
            .clone()
    }

    /// Kick (or attach to) the background bootstrap reconcile for an agent.
    ///
    /// The durable `agent_bootstraps` record stays the source of truth; the
    /// returned receiver resolves once the background reconcile finishes, so
    /// HTTP job projections can follow it without owning the lifecycle.
    pub(crate) fn kick_agent_bootstrap(&self, agent_id: &str) -> Result<AgentBootstrapKick> {
        let bootstrap = self
            .runtime_db()
            .agent_bootstraps()
            .latest(agent_id)?
            .ok_or_else(|| anyhow!("agent {agent_id} has no bootstrap state"))?;
        if bootstrap.summary().status == AgentBootstrapStatus::Ready {
            return Ok(AgentBootstrapKick::AlreadyComplete(bootstrap));
        }
        let (tx, rx) = tokio::sync::oneshot::channel();
        let should_spawn = {
            let mut waiters = self.inner.bootstrap_reconcile_waiters.lock().unwrap();
            let entry = waiters.entry(agent_id.to_string()).or_default();
            let should_spawn = entry.is_empty();
            entry.push(tx);
            should_spawn
        };
        if should_spawn {
            let host = self.clone();
            let owned_agent_id = agent_id.to_string();
            let spawn_result = self.start_runtime_operation(async move {
                let result = host.reconcile_agent_bootstrap(&owned_agent_id).await;
                if let Err(error) = result.as_ref() {
                    tracing::warn!(
                        agent_id = %owned_agent_id,
                        error = %error,
                        "background agent bootstrap reconcile failed"
                    );
                }
                let outcome = match result {
                    Ok(record) => Ok(record),
                    Err(error) => Err(error.to_string()),
                };
                host.finish_background_bootstrap_reconcile(&owned_agent_id, &outcome);
                Ok(())
            });
            if let Err(error) = spawn_result {
                // Admission closed: fail the waiters now. The durable record
                // keeps the pending state for the startup sweep or a later
                // kick to resume.
                self.finish_background_bootstrap_reconcile(agent_id, &Err(error.to_string()));
            }
        }
        Ok(AgentBootstrapKick::Started(rx))
    }

    fn finish_background_bootstrap_reconcile(
        &self,
        agent_id: &str,
        result: &std::result::Result<AgentBootstrapRecord, String>,
    ) {
        let waiters = self
            .inner
            .bootstrap_reconcile_waiters
            .lock()
            .unwrap()
            .remove(agent_id);
        let payload = match result {
            Ok(record) => Ok(record.clone()),
            Err(error) => Err(error.to_string()),
        };
        if let Some(waiters) = waiters {
            for waiter in waiters {
                let _ = waiter.send(payload.clone());
            }
        }
    }

    /// Resume bootstrap reconciles whose frontier step never recorded a
    /// result (interrupted by a request cancellation or a process restart).
    /// Returns how many background reconciles were kicked.
    pub fn sweep_pending_agent_bootstraps(&self) -> Result<usize> {
        let candidates = self.runtime_db().agent_bootstraps().pending_frontier()?;
        let mut kicked = 0usize;
        for bootstrap in candidates {
            let active = self
                .agent_identity_record(&bootstrap.agent_id)?
                .is_some_and(|identity| identity.status == AgentRegistryStatus::Active);
            if !active {
                tracing::debug!(
                    agent_id = %bootstrap.agent_id,
                    "skipping pending bootstrap sweep for inactive agent"
                );
                continue;
            }
            match self.kick_agent_bootstrap(&bootstrap.agent_id) {
                Ok(AgentBootstrapKick::Started(_)) => kicked += 1,
                Ok(AgentBootstrapKick::AlreadyComplete(_)) => {}
                Err(error) => {
                    tracing::warn!(
                        agent_id = %bootstrap.agent_id,
                        error = %error,
                        "pending bootstrap sweep kick failed"
                    );
                }
            }
        }
        Ok(kicked)
    }

    fn agent_create_stage(summary: &AgentBootstrapSummary) -> AgentCreateStage {
        if summary.status == AgentBootstrapStatus::Ready {
            AgentCreateStage::Bootstrapped
        } else {
            AgentCreateStage::Degraded
        }
    }

    async fn reconcile_agent_bootstrap(&self, agent_id: &str) -> Result<AgentBootstrapRecord> {
        let lock = self.agent_bootstrap_lock(agent_id);
        let _guard = lock.lock().await;
        let identity = self
            .agent_identity_record(agent_id)?
            .ok_or_else(|| anyhow!("agent {agent_id} not found"))?;
        anyhow::ensure!(
            identity.status == AgentRegistryStatus::Active,
            "agent {agent_id} cannot be repaired while it is {:?}",
            identity.status
        );
        let mut bootstrap = self
            .runtime_db()
            .agent_bootstraps()
            .latest(agent_id)?
            .ok_or_else(|| anyhow!("agent {agent_id} has no bootstrap state to repair"))?;
        anyhow::ensure!(
            match bootstrap.incarnation {
                Some(value) => value == identity.incarnation,
                None =>
                    identity.incarnation == 1
                        || bootstrap.summary().status == AgentBootstrapStatus::Ready,
            },
            "agent_bootstrap_stale_identity"
        );

        if bootstrap.template.status != AgentBootstrapStepStatus::Succeeded {
            let result = self.apply_agent_template_bootstrap(&bootstrap).await;
            self.record_agent_bootstrap_result(
                &mut bootstrap,
                AgentBootstrapStepKind::Template,
                result,
            )?;
        }
        if bootstrap.template.status != AgentBootstrapStepStatus::Succeeded {
            return Ok(bootstrap);
        }
        if bootstrap.runtime.status != AgentBootstrapStepStatus::Succeeded {
            // Legacy installations may explicitly recreate the configured
            // default agent while provider setup is still in progress. The
            // runtime task cannot finish bootstrap until the host releases
            // its bootstrap provider, so waiting here would deadlock the
            // setup request itself. Leave runtime bootstrap pending and let
            // the normal activation/repair path resume after setup.
            if self.bootstrap_mode_active() && agent_id == self.config().default_agent_id {
                return Ok(bootstrap);
            }
            let result = async {
                let runtime = self
                    .activate_agent(agent_id, RuntimeActivationReason::AgentLifecycle)
                    .await?;
                runtime.wait_for_bootstrap().await
            }
            .await;
            self.record_agent_bootstrap_result(
                &mut bootstrap,
                AgentBootstrapStepKind::Runtime,
                result,
            )?;
        }
        if bootstrap.runtime.status != AgentBootstrapStepStatus::Succeeded {
            return Ok(bootstrap);
        }
        if bootstrap.workspace.status != AgentBootstrapStepStatus::Succeeded {
            let result = self.apply_agent_workspace_bootstrap(&bootstrap).await;
            self.record_agent_bootstrap_result(
                &mut bootstrap,
                AgentBootstrapStepKind::Workspace,
                result,
            )?;
        }
        if bootstrap.workspace.status != AgentBootstrapStepStatus::Succeeded {
            return Ok(bootstrap);
        }
        if bootstrap.model.status != AgentBootstrapStepStatus::Succeeded {
            let result = self.apply_agent_model_bootstrap(&bootstrap).await;
            self.record_agent_bootstrap_result(
                &mut bootstrap,
                AgentBootstrapStepKind::Model,
                result,
            )?;
        }
        if bootstrap.model.status != AgentBootstrapStepStatus::Succeeded {
            return Ok(bootstrap);
        }
        if bootstrap.initial_message.status != AgentBootstrapStepStatus::Succeeded {
            let result = self.apply_agent_initial_message_bootstrap(&bootstrap).await;
            self.record_agent_bootstrap_result(
                &mut bootstrap,
                AgentBootstrapStepKind::InitialMessage,
                result,
            )?;
        }
        Ok(bootstrap)
    }

    fn record_agent_bootstrap_result(
        &self,
        bootstrap: &mut AgentBootstrapRecord,
        kind: AgentBootstrapStepKind,
        result: Result<()>,
    ) -> Result<()> {
        let expected_revision = bootstrap.revision;
        let expected_incarnation = self.active_agent_identity(&bootstrap.agent_id)?.incarnation;
        anyhow::ensure!(
            bootstrap
                .incarnation
                .is_none_or(|value| value == expected_incarnation),
            "agent_bootstrap_stale_identity"
        );
        let now = Utc::now();
        let succeeded = result.is_ok();
        {
            let step = agent_bootstrap_step_mut(bootstrap, kind);
            step.attempts = step.attempts.saturating_add(1);
            step.updated_at = now;
            match result {
                Ok(()) => {
                    step.status = AgentBootstrapStepStatus::Succeeded;
                    step.last_error = None;
                }
                Err(error) => {
                    step.status = AgentBootstrapStepStatus::Failed;
                    step.last_error = Some(bounded_bootstrap_error(&error));
                }
            }
        }
        if succeeded && matches!(kind, AgentBootstrapStepKind::InitialMessage) {
            bootstrap.desired.initial_message = None;
        }
        bootstrap.revision = bootstrap.revision.saturating_add(1);
        bootstrap.updated_at = now;
        self.runtime_db().agent_bootstraps().update_if_current(
            bootstrap,
            expected_revision,
            expected_incarnation,
        )
    }

    async fn apply_agent_template_bootstrap(&self, bootstrap: &AgentBootstrapRecord) -> Result<()> {
        let agent_home = self.agent_data_dir(&bootstrap.agent_id);
        let agents_md = agent_home.join("AGENTS.md");
        let expected_selector = bootstrap
            .desired
            .template
            .as_deref()
            .unwrap_or(DEFAULT_AGENT_TEMPLATE_ID);
        let provenance_path = template_provenance_path(&agent_home);
        if provenance_path.is_file() {
            let content = fs::read_to_string(&provenance_path)?;
            let provenance: TemplateProvenanceRecord = serde_json::from_str(&content)?;
            anyhow::ensure!(
                provenance.selector == expected_selector,
                "agent {} template conflict: expected {:?}, found {:?}",
                bootstrap.agent_id,
                expected_selector,
                provenance.selector
            );
            anyhow::ensure!(
                agents_md.is_file(),
                "agent {} template marker exists but AGENTS.md is missing",
                bootstrap.agent_id
            );
            return Ok(());
        }
        if agents_md.exists() {
            // Distinguish a runtime half-materialized template (crash or
            // cancelled request mid-install) from genuine user content using
            // the runtime-owned staging record.
            let recovered =
                crate::agent_template::recover_template_staging(&agent_home, expected_selector)
                    .map_err(|error| {
                        anyhow!(
                            "agent {} template staging recovery failed: {error}",
                            bootstrap.agent_id
                        )
                    })?;
            anyhow::ensure!(
                recovered,
                "agent {} AGENTS.md already exists without a runtime template marker; repair refuses to overwrite user content",
                bootstrap.agent_id
            );
        }
        let config = self.config();
        let template_home = config
            .user_home_dir
            .as_deref()
            .unwrap_or(config.home_dir.as_path());
        if let Some(template) = bootstrap.desired.template.as_deref() {
            if let Some(catalog_agent_home) = bootstrap.desired.catalog_agent_home.as_deref() {
                ensure_agent_home_agents_md_from_template_with_catalog(
                    &agent_home,
                    template_home,
                    catalog_agent_home,
                    template,
                )
                .await?;
            } else {
                ensure_agent_home_agents_md_from_template_with_home(
                    &agent_home,
                    template_home,
                    template,
                )
                .await?;
            }
        } else {
            ensure_agent_home_agents_md_without_template_with_home(&agent_home, template_home)
                .await?;
        }
        Ok(())
    }

    async fn apply_agent_workspace_bootstrap(
        &self,
        bootstrap: &AgentBootstrapRecord,
    ) -> Result<()> {
        let Some(desired) = bootstrap.desired.workspace.as_ref() else {
            return Ok(());
        };
        let runtime = self.get_or_create_agent(&bootstrap.agent_id).await?;
        let current = runtime.agent_state().await?;
        if current.attached_workspaces == desired.attached_workspaces
            && current.execution_profile == desired.execution_profile
            && current.model_override == desired.inherited_model_override
            && current.model_override_reasoning_effort
                == desired.inherited_model_override_reasoning_effort
            && current.model_override_service_tier == desired.inherited_model_override_service_tier
        {
            return Ok(());
        }
        let default_state = AgentState::new(bootstrap.agent_id.clone());
        let initial_workspaces = vec![crate::types::agent_home_workspace_id(&bootstrap.agent_id)];
        anyhow::ensure!(
            (current.attached_workspaces == default_state.attached_workspaces
                || current.attached_workspaces == initial_workspaces)
                && current.execution_profile == default_state.execution_profile
                && current.model_override == default_state.model_override
                && current.model_override_reasoning_effort
                    == default_state.model_override_reasoning_effort
                && current.model_override_service_tier == default_state.model_override_service_tier,
            "agent {} workspace/profile changed after creation; repair refuses to overwrite user state",
            bootstrap.agent_id
        );
        runtime
            .apply_bootstrap_workspace_state(
                desired.attached_workspaces.clone(),
                desired.execution_profile.clone(),
                desired.inherited_model_override.clone(),
                desired.inherited_model_override_reasoning_effort.clone(),
                desired.inherited_model_override_service_tier,
            )
            .await
    }

    async fn apply_agent_model_bootstrap(&self, bootstrap: &AgentBootstrapRecord) -> Result<()> {
        let Some(resolution) = bootstrap.desired.model_resolution.as_ref() else {
            return Ok(());
        };
        let runtime = self.get_or_create_agent(&bootstrap.agent_id).await?;
        let current = runtime.agent_state().await?;
        if resolution.resolution_status == AgentModelResolutionStatus::Inherited {
            return Ok(());
        }
        let provider = crate::config::ProviderId::parse(&resolution.resolved_provider)?;
        let expected = crate::config::ModelRouteRef::from_legacy_model_ref(
            &crate::config::ModelRef::new(provider, resolution.resolved_model.clone()),
        );
        let expected_reasoning_effort = resolution
            .resolved_parameters
            .as_ref()
            .and_then(|parameters| parameters.get("reasoning_effort"))
            .and_then(Value::as_str)
            .map(ToString::to_string);
        if current.model_override.as_ref() == Some(&expected)
            && current.model_override_reasoning_effort == expected_reasoning_effort
        {
            return Ok(());
        }
        let inherited_model = bootstrap
            .desired
            .workspace
            .as_ref()
            .and_then(|workspace| workspace.inherited_model_override.as_ref());
        let inherited_effort = bootstrap
            .desired
            .workspace
            .as_ref()
            .and_then(|workspace| workspace.inherited_model_override_reasoning_effort.as_ref());
        let inherited_tier = bootstrap
            .desired
            .workspace
            .as_ref()
            .and_then(|workspace| workspace.inherited_model_override_service_tier);
        anyhow::ensure!(
            current.model_override_service_tier == inherited_tier
                && current.model_override.as_ref() == inherited_model
                && current.model_override_reasoning_effort.as_ref() == inherited_effort,
            "agent {} model changed after creation; repair refuses to overwrite user state",
            bootstrap.agent_id
        );
        apply_spawn_model_resolution(&runtime, resolution).await
    }

    async fn apply_agent_initial_message_bootstrap(
        &self,
        bootstrap: &AgentBootstrapRecord,
    ) -> Result<()> {
        let synthesized_default = bootstrap.desired.initial_message.is_none();
        let initial = match bootstrap.desired.initial_message.clone() {
            Some(initial) => initial,
            None if bootstrap.desired.default_initial_message => {
                default_agent_bootstrap_initial_message(bootstrap)
            }
            None => return Ok(()),
        };
        let runtime = self.get_or_create_agent(&bootstrap.agent_id).await?;
        anyhow::ensure!(
            match bootstrap.incarnation {
                Some(incarnation) => runtime.instance_incarnation() == incarnation,
                None => runtime.instance_incarnation() == 1,
            },
            "agent_bootstrap_stale_identity"
        );
        let mut message = MessageEnvelope::new(
            bootstrap.agent_id.clone(),
            MessageKind::InternalFollowup,
            MessageOrigin::System {
                subsystem: "spawn_agent".into(),
            },
            initial.authority_class,
            Priority::Normal,
            MessageBody::Text {
                text: initial.text.clone(),
            },
        )
        .with_admission(
            MessageDeliverySurface::RuntimeSystem,
            AdmissionContext::RuntimeOwned,
        );
        message.id = initial.message_id.clone();
        let mut metadata = json!({
            "spawn_preset": AgentProfilePreset::PublicNamed,
            "creator_agent_id": initial.creator_agent_id,
            "spawned_agent_id": bootstrap.agent_id,
            "bootstrap": true,
        });
        if synthesized_default {
            metadata["bootstrap_default"] = json!(true);
        }
        message.metadata = Some(metadata);
        runtime.enqueue(message).await?;
        Ok(())
    }

    pub async fn repair_public_agent(
        &self,
        agent_id: &str,
    ) -> std::result::Result<AgentDetail, PublicAgentError> {
        let identity = self.public_agent_identity(agent_id)?;
        match identity.status {
            AgentRegistryStatus::Active => {}
            AgentRegistryStatus::Deleting => {
                return Err(PublicAgentError::Deleting {
                    agent_id: agent_id.to_string(),
                });
            }
            AgentRegistryStatus::Deleted => {
                return Err(PublicAgentError::Deleted {
                    agent_id: agent_id.to_string(),
                });
            }
        }
        self.reconcile_agent_bootstrap(agent_id)
            .await
            .map_err(PublicAgentError::Runtime)?;
        self.public_agent_detail(agent_id)
    }

    /// Kick a background bootstrap reconcile for a public agent and return
    /// the current detail snapshot. The optional receiver resolves when the
    /// background reconcile finishes; `None` means bootstrap was already
    /// complete and nothing was started.
    pub async fn repair_public_agent_background(
        &self,
        agent_id: &str,
    ) -> std::result::Result<
        (
            AgentDetail,
            Option<tokio::sync::oneshot::Receiver<Result<AgentBootstrapRecord, String>>>,
        ),
        PublicAgentError,
    > {
        let identity = self.public_agent_identity(agent_id)?;
        match identity.status {
            AgentRegistryStatus::Active => {}
            AgentRegistryStatus::Deleting => {
                return Err(PublicAgentError::Deleting {
                    agent_id: agent_id.to_string(),
                });
            }
            AgentRegistryStatus::Deleted => {
                return Err(PublicAgentError::Deleted {
                    agent_id: agent_id.to_string(),
                });
            }
        }
        let kick = self
            .kick_agent_bootstrap(agent_id)
            .map_err(PublicAgentError::Runtime)?;
        let detail = self.public_agent_detail(agent_id)?;
        let receiver = match kick {
            AgentBootstrapKick::AlreadyComplete(_) => None,
            AgentBootstrapKick::Started(receiver) => Some(receiver),
        };
        Ok((detail, receiver))
    }

    pub fn get_or_create_agent<'a>(
        &'a self,
        agent_id: &'a str,
    ) -> Pin<Box<dyn Future<Output = Result<RuntimeHandle>> + Send + 'a>> {
        self.activate_agent(agent_id, RuntimeActivationReason::AgentLifecycle)
    }

    pub(crate) fn activate_agent<'a>(
        &'a self,
        agent_id: &'a str,
        reason: RuntimeActivationReason,
    ) -> Pin<Box<dyn Future<Output = Result<RuntimeHandle>> + Send + 'a>> {
        self.activate_agent_observed(agent_id, reason, None)
    }

    fn activate_agent_observed<'a>(
        &'a self,
        agent_id: &'a str,
        reason: RuntimeActivationReason,
        observation: Option<crate::startup::StartupObservation>,
    ) -> Pin<Box<dyn Future<Output = Result<RuntimeHandle>> + Send + 'a>> {
        self.activate_agent_observed_for_incarnation(agent_id, reason, observation, None)
    }

    fn activate_agent_observed_for_incarnation<'a>(
        &'a self,
        agent_id: &'a str,
        reason: RuntimeActivationReason,
        observation: Option<crate::startup::StartupObservation>,
        expected_incarnation: Option<u64>,
    ) -> Pin<Box<dyn Future<Output = Result<RuntimeHandle>> + Send + 'a>> {
        Box::pin(async move {
            if self.inner.runtime_operations_token.is_cancelled() {
                return Err(anyhow::Error::new(RuntimeAdmissionClosed));
            }
            self.ensure_runtime_recovery_coordinator();
            self.validate_agent_id(agent_id)?;
            let default_identity_missing = if agent_id == self.config().default_agent_id {
                let host = self.clone();
                let agent_id = agent_id.to_string();
                spawn_blocking(move || host.agent_identity_record(&agent_id))
                    .await??
                    .is_none()
            } else {
                false
            };
            if default_identity_missing {
                match reason {
                    RuntimeActivationReason::StartupRecovery
                    | RuntimeActivationReason::SchedulerDispatch
                    | RuntimeActivationReason::Wake
                    | RuntimeActivationReason::ExternalIngress
                    | RuntimeActivationReason::ChildSupervision => {
                        return Err(anyhow!(
                            "default agent {} has not been created yet",
                            agent_id
                        ));
                    }
                    RuntimeActivationReason::OperatorControl
                    | RuntimeActivationReason::AgentLifecycle => {
                        self.ensure_default_agent_identity()?;
                    }
                }
            }
            let identity = self.active_agent_identity_async(agent_id).await?;
            if expected_incarnation.is_some_and(|expected| expected != identity.incarnation) {
                return Err(RuntimeError::policy(
                    "agent_incarnation_mismatch",
                    "invocation target incarnation changed before activation",
                )
                .into());
            }
            {
                let registry = self.inner.runtimes.read().await;
                if registry.phase != HostRuntimePhase::Open {
                    return Err(anyhow::Error::new(RuntimeAdmissionClosed));
                }
                if let Some(entry) = registry.agents.get(agent_id) {
                    if entry.accepts_host_access() {
                        if expected_incarnation.is_some_and(|expected| {
                            expected != entry.runtime.instance_incarnation()
                        }) {
                            return Err(RuntimeError::policy(
                                "agent_incarnation_mismatch",
                                "invocation target instance changed before activation",
                            )
                            .into());
                        }
                        return Ok(entry.runtime.clone());
                    }
                }
            }
            // A host task retains the guards through storage writes and registration,
            // even if the requesting future is cancelled during construction.
            let host = self.clone();
            let agent_id = agent_id.to_string();
            let request_cancelled = CancellationToken::new();
            let _cancel_on_drop = request_cancelled.clone().drop_guard();
            self.start_runtime_operation(async move {
                host.activate_cold_agent(
                    &agent_id,
                    reason,
                    observation,
                    &request_cancelled,
                    expected_incarnation,
                )
                .await
            })?
            .await?
        })
    }

    async fn activate_cold_agent(
        &self,
        agent_id: &str,
        reason: RuntimeActivationReason,
        observation: Option<crate::startup::StartupObservation>,
        request_cancelled: &CancellationToken,
        expected_incarnation: Option<u64>,
    ) -> Result<RuntimeHandle> {
        if agent_id != self.config().default_agent_id && self.bootstrap_mode_active() {
            self.wait_for_runtime_operation(request_cancelled, self.wait_for_bootstrap_ready())
                .await??;
        }
        {
            let _bootstrap_handoff_guard = self
                .wait_for_runtime_operation(
                    request_cancelled,
                    self.inner.bootstrap_handoff_lock.lock(),
                )
                .await?;
            let identity = self.active_agent_identity_async(agent_id).await?;
            if expected_incarnation.is_some_and(|expected| expected != identity.incarnation) {
                return Err(RuntimeError::policy(
                    "agent_incarnation_mismatch",
                    "invocation target incarnation changed before activation",
                )
                .into());
            }
            if agent_id == self.config().default_agent_id {
                self.ensure_default_agent_home_initialized().await?;
            }
        }
        loop {
            let identity = self.active_agent_identity_async(agent_id).await?;
            let owner = self
                .inner
                .mutation_owners
                .current_owner(agent_id, identity.incarnation)?;
            // Owner waits never retain the registry or bootstrap handoff.
            match self
                .wait_for_runtime_operation(
                    request_cancelled,
                    MutationOwner::reserve_all(vec![owner]),
                )
                .await?
            {
                Ok(mut reservations) => {
                    self.reconcile_external_mutations(&mut reservations).await?;
                }
                Err(MutationOwnerError::Replaced) => continue,
                Err(error) => return Err(error.into()),
            }
            let bootstrap_handoff_guard = self
                .wait_for_runtime_operation(
                    request_cancelled,
                    self.inner.bootstrap_handoff_lock.lock(),
                )
                .await?;
            let mut failed_runtime_phase = None;
            let mut registry = self
                .wait_for_runtime_operation(request_cancelled, self.inner.runtimes.write())
                .await?;
            if registry.phase != HostRuntimePhase::Open {
                return Err(anyhow::Error::new(RuntimeAdmissionClosed));
            }
            let identity = self.active_agent_identity_async(agent_id).await?;
            if expected_incarnation.is_some_and(|expected| expected != identity.incarnation) {
                return Err(RuntimeError::policy(
                    "agent_incarnation_mismatch",
                    "invocation target incarnation changed before activation",
                )
                .into());
            }
            if let Some(entry) = registry.agents.get(agent_id) {
                if entry.accepts_host_access() {
                    return Ok(entry.runtime.clone());
                }
                if !entry.task.is_finished()
                    && (*entry.phase.borrow() == AgentRuntimePhase::FailedCleaning
                        || !entry.runtime.accepts_execution_admission())
                {
                    failed_runtime_phase = Some(entry.phase.clone());
                }
            }
            if let Some(mut phase) = failed_runtime_phase {
                drop(registry);
                drop(bootstrap_handoff_guard);
                while *phase.borrow_and_update() != AgentRuntimePhase::Terminated {
                    if self
                        .wait_for_runtime_operation(request_cancelled, phase.changed())
                        .await?
                        .is_err()
                    {
                        break;
                    }
                }
                continue;
            }
            registry.validate_retiring_process_instance_budget(
                agent_id,
                identity.incarnation,
                &self.inner.input_evidence_budget,
            )?;
            registry.ever_activated = true;
            let generation = registry.next_generation;
            let (runtime, runtime_task, phase) = match self
                .spawn_runtime(agent_id, Some(generation), observation.clone())
                .await
            {
                Ok(spawned) => spawned,
                Err(error)
                    if error
                        .downcast_ref::<MutationOwnerError>()
                        .is_some_and(|error| {
                            matches!(
                                error,
                                MutationOwnerError::Busy
                                    | MutationOwnerError::Replaced
                                    | MutationOwnerError::NeedsReconcile(_)
                            )
                        }) =>
                {
                    drop(registry);
                    drop(bootstrap_handoff_guard);
                    continue;
                }
                Err(error) => return Err(error),
            };
            registry.next_generation = registry.next_generation.saturating_add(1);
            let stale_entry = registry.agents.remove(agent_id);
            if let Some(entry) = &stale_entry {
                entry.runtime.close_execution_admission();
                registry.retain_unproved_original_processes(entry);
            }
            tracing::debug!(
                agent_id,
                activation_reason = reason.as_str(),
                "activating agent runtime"
            );
            registry.agents.insert(
                agent_id.to_string(),
                AgentEntry {
                    runtime: runtime.clone(),
                    task: runtime_task,
                    phase,
                    generation,
                    idle_observation: None,
                },
            );
            drop(registry);
            drop(bootstrap_handoff_guard);
            if let Some(entry) = stale_entry {
                let _ = entry.task.await;
            }
            return Ok(runtime);
        }
    }

    pub(crate) async fn spawn_temporary_runtime(
        &self,
        category: &str,
    ) -> Result<(String, RuntimeHandle, JoinHandle<()>)> {
        let host = self.clone();
        let category = category.to_string();
        let request_cancelled = CancellationToken::new();
        let _cancel_on_drop = request_cancelled.clone().drop_guard();
        let pending = self
            .start_runtime_operation(async move {
                host.spawn_temporary_runtime_owned(&category, &request_cancelled)
                    .await
            })?
            .await??;
        let spawned = {
            let operations = self.inner.runtime_operations.lock().unwrap();
            if operations.closing {
                return Err(anyhow::Error::new(RuntimeAdmissionClosed));
            }
            pending
                .spawned
                .lock()
                .unwrap()
                .take()
                .ok_or_else(|| anyhow::Error::new(RuntimeAdmissionClosed))?
        };
        Ok(spawned)
    }

    async fn spawn_temporary_runtime_owned(
        &self,
        category: &str,
        request_cancelled: &CancellationToken,
    ) -> Result<PendingTemporaryRuntime> {
        let bootstrap_handoff_guard = self
            .wait_for_runtime_operation(request_cancelled, self.inner.bootstrap_handoff_lock.lock())
            .await?;
        let mut registry = self
            .wait_for_runtime_operation(request_cancelled, self.inner.runtimes.write())
            .await?;
        if registry.phase != HostRuntimePhase::Open {
            return Err(anyhow::Error::new(RuntimeAdmissionClosed));
        }
        let agent_id = match category {
            "run" => ids::runtime_id(TEMP_RUN_AGENT_PREFIX.trim_end_matches('_')),
            other => ids::runtime_id(&format!("{TEMP_AGENT_PREFIX}{other}")),
        };
        self.validate_agent_id(&agent_id)?;
        let mut identity = AgentIdentityRecord::new(
            agent_id.clone(),
            AgentKind::Named,
            AgentVisibility::Private,
            AgentOwnership::SelfOwned,
            AgentProfilePreset::PublicNamed,
            None,
            None,
        );
        identity.durability = Some(AgentDurability::Ephemeral);
        let relations =
            independent_creation_records(&identity, None, AgentCanonicalDurability::Ephemeral);
        self.runtime_db()
            .agent_identities()
            .create_with_relations(&identity, &relations)?;
        self.cache_agent_identity(&identity)?;
        registry.ever_activated = true;
        let (runtime, runtime_task, phase) = match self.spawn_runtime(&agent_id, None, None).await {
            Ok(spawned) => spawned,
            Err(error) => {
                drop(registry);
                drop(bootstrap_handoff_guard);
                if let Err(cleanup_error) = self
                    .archive_temporary_runtime_identity_owned(&agent_id)
                    .await
                {
                    tracing::warn!(agent_id, error = %cleanup_error, "temporary bootstrap identity retirement failed");
                }
                return Err(error);
            }
        };
        registry.temporary_runtimes.insert(
            agent_id.clone(),
            TemporaryRuntimeEntry {
                runtime: runtime.clone(),
                abort: runtime_task.abort_handle(),
                phase,
            },
        );
        let spawned = Arc::new(Mutex::new(Some((agent_id, runtime, runtime_task))));
        let (handoff, handed_off) = tokio::sync::oneshot::channel();
        let cleanup_spawned = spawned.clone();
        let host = self.clone();
        // This is a continuation of the admitted construction, so it must be
        // registered even if shutdown has closed admission in the meantime.
        self.inner
            .runtime_operations
            .lock()
            .unwrap()
            .tasks
            .spawn(async move {
                tokio::select! {
                    _ = handed_off => {}
                    _ = host.inner.runtime_operations_token.cancelled() => {}
                }
                let unclaimed = cleanup_spawned.lock().unwrap().take();
                let Some((agent_id, runtime, task)) = unclaimed else {
                    return;
                };
                runtime.retire_instance_locally("cancelled_temporary_runtime_handoff").await;
                task.abort();
                let _ = task.await;
                if let Err(error) = runtime.join_retiring_resources().await {
                    tracing::warn!(agent_id, error = %error, "cancelled temporary runtime drain failed");
                    return;
                }
                if let Err(error) = host.archive_temporary_runtime_identity_owned(&agent_id).await {
                    tracing::warn!(agent_id, error = %error, "cancelled temporary runtime cleanup failed");
                } else {
                    host.inner.runtimes.write().await.temporary_runtimes.remove(&agent_id);
                }
            });
        Ok(PendingTemporaryRuntime {
            spawned,
            _handoff: handoff,
        })
    }

    async fn archive_temporary_runtime_identity_owned(&self, agent_id: &str) -> Result<()> {
        if !Self::is_temporary_agent_id(agent_id) {
            bail!("agent {agent_id} is not a temporary runtime");
        }
        let bootstrap_lock = self.agent_bootstrap_lock(agent_id);
        let _bootstrap_guard = bootstrap_lock.lock().await;
        let mut reservations = self
            .reserve_agent_mutations(&[agent_id.to_string()])
            .await?;
        let identity = self
            .runtime_db()
            .agent_identities()
            .latest(agent_id)?
            .with_context(|| {
                format!("temporary runtime {agent_id} is missing its host identity")
            })?;
        if identity.status != AgentRegistryStatus::Deleted {
            let mut facts = self.external_identity_facts(&reservations)?;
            let mut acknowledged = false;
            let committed = self
                .commit_external_metadata(&mut reservations, ids::audit_event_id(), || {
                    let identity = self
                        .runtime_db()
                        .agent_identities()
                        .tombstone_with_closed_supervision(agent_id)?;
                    for fact in &mut facts {
                        fact.identity = Some(Arc::new(identity.clone()));
                    }
                    acknowledged = true;
                    Ok(((), facts))
                })
                .await;
            if let Err(error) = committed {
                if !acknowledged {
                    return Err(error);
                }
                self.reconcile_external_mutations(&mut reservations).await?;
            }
        }
        Ok(())
    }

    pub(crate) async fn cleanup_temporary_runtime(
        &self,
        agent_id: String,
        runtime: RuntimeHandle,
        runtime_task: JoinHandle<()>,
    ) -> Result<()> {
        let host = self.clone();
        self.run_owned_external_mutation(async move {
            let _ = runtime.control(crate::types::ControlAction::Stop).await;
            // The Host also retains this instance until successful cleanup, so
            // Closing can take over if this cleanup is not admitted in time.
            let _ = runtime.request_service_shutdown().await;
            runtime_task.abort();
            let _ = runtime_task.await;
            let producer_exit = runtime.join_retiring_resources_with_process_exit().await?;
            host.archive_temporary_runtime_identity_owned(&agent_id)
                .await?;
            let data_dir = host.agent_data_dir(&agent_id);
            if data_dir.exists() {
                fs::remove_dir_all(&data_dir)?;
            }
            if producer_exit.is_some() {
                host.inner
                    .runtimes
                    .write()
                    .await
                    .temporary_runtimes
                    .remove(&agent_id);
            }
            Ok(())
        })
        .await
    }

