    pub async fn list_agents(&self) -> Result<Vec<crate::runtime::OwnedAgentSummaryRead>> {
        let mut summaries = Vec::new();
        let identities = self.inner.registry.agent_identity_reads(
            &self.inner.input_evidence_budget,
            |record| {
                record.status == AgentRegistryStatus::Active
                    && record.visibility == AgentVisibility::Public
            },
        )?;
        for (identity, inventory) in identities {
            let summary = self
                .local_agent_summary(&identity.agent_id)
                .await
                .map_err(anyhow::Error::from)?
                .with_fleet_inventory(&inventory)?;
            inventory.read(|| {
                crate::runtime_db::repositories::reserve_source_vec_slot(&mut summaries)?;
                summaries.push(summary);
                Ok(())
            })?;
        }
        // Identity selection is already sorted by the canonical Agent ID.
        Ok(summaries)
    }

    /// Run inside a registered blocking worker; no hidden async SQL task.
    #[cfg(test)]
    pub(crate) fn list_agent_entries_for_parent_scoped(
        &self,
        parent_agent_id: Option<&str>,
        db: &RuntimeDb,
    ) -> Result<OwnedAgentListRead> {
        db.check_read_scope()?;
        let acquisition = self.observer_inventory_material()?;
        acquisition.read(|| {
            let identities = self.agent_list_identities(parent_agent_id)?;
            let agent_ids = identities
                .iter()
                .map(|record| record.agent_id.clone())
                .collect::<Vec<_>>();
            let rows = db.agent_list_posture_rows(&agent_ids)?;
            let entries = self.agent_list_entries_from_rows(identities, rows, db)?;
            OwnedAgentListRead::from_observer_entries(entries, acquisition.clone())
        })
    }

    #[cfg(test)]
    fn agent_list_identities(
        &self,
        parent_agent_id: Option<&str>,
    ) -> Result<Vec<AgentIdentityRecord>> {
        Ok(self
            .agent_identity_records()?
            .into_iter()
            .filter(|record| {
                record.status == AgentRegistryStatus::Active
                    && record.visibility == AgentVisibility::Public
                    && parent_agent_id.map_or(true, |parent| {
                        record
                            .lineage_parent_agent_id
                            .as_deref()
                            .or(record.parent_agent_id.as_deref())
                            == Some(parent)
                    })
            })
            .collect())
    }

    #[cfg(test)]
    fn agent_list_entries_from_rows(
        &self,
        identities: Vec<AgentIdentityRecord>,
        rows: crate::runtime_db::agent_list::AgentListPostureRows,
        db: &RuntimeDb,
    ) -> Result<Vec<AgentListEntry>> {
        let mut rows_by_agent = rows
            .rows
            .into_iter()
            .map(|row| (row.agent_id.clone(), row))
            .collect::<HashMap<_, _>>();
        let catalog = RuntimeModelCatalog::from_config(&self.config());
        let mut entries = Vec::new();
        for identity in identities {
            db.check_read_cancellation()?;
            let row = rows_by_agent.remove(&identity.agent_id);
            entries.push(self.agent_list_entry_from_projection_row(&identity, row, &catalog));
        }
        entries.sort_by(|left, right| left.identity.agent_id.cmp(&right.identity.agent_id));
        db.check_read_scope()?;
        Ok(entries)
    }

    /// Maps one roster member's committed batch rows to its list entry.
    /// Resident runtimes are intentionally served from the same committed
    /// view as unloaded members: `/agents/list` never starts a runtime and
    /// never mixes per-agent read views. Unreadable payloads degrade this
    /// one member to placeholder facts, matching the previous per-agent
    /// read-error behavior.
    #[cfg(test)]
    fn agent_list_entry_from_projection_row(
        &self,
        identity: &AgentIdentityRecord,
        row: Option<AgentListPostureRow>,
        catalog: &RuntimeModelCatalog,
    ) -> AgentListEntry {
        let agent = match row.as_ref().and_then(|row| row.agent_state_json.as_deref()) {
            Some(payload) => match serde_json::from_str::<AgentState>(payload) {
                Ok(agent) => agent,
                Err(error) => {
                    warn!(
                        agent_id = %identity.agent_id,
                        error = %error,
                        "failed to read agent state for /agents/list; using stopped placeholder"
                    );
                    stopped_unloaded_agent(&identity.agent_id)
                }
            },
            None => stopped_unloaded_agent(&identity.agent_id),
        };
        let model = crate::runtime::agent_model_state_for_catalog(
            catalog,
            &self.runtime_context_config(),
            &agent,
        );
        let scheduling_posture = match row {
            Some(row) => match row.facts {
                Ok(mut facts) => {
                    facts.current_work_item_id = agent.current_work_item_id.clone();
                    facts.has_queued_input = row.has_queued_input;
                    crate::storage::read_models::agent_posture_from_facts(&agent, &facts)
                }
                Err(error) => {
                    warn!(
                        agent_id = %identity.agent_id,
                        error = %error,
                        "failed to read agent posture for /agents/list; using unknown placeholder"
                    );
                    crate::types::AgentPostureProjection::default()
                }
            },
            None => crate::types::AgentPostureProjection::default(),
        };
        let waiting_reason = crate::runtime::lightweight_agent_list_waiting_reason(&agent);
        AgentListEntry {
            identity: AgentIdentityView::from_record(identity, &self.config().default_agent_id),
            lifecycle: AgentLifecycleHint::from_status(&agent.id, agent.status.clone()),
            status: agent.status,
            scheduling_posture,
            pending: agent.pending,
            current_run_id: agent.current_run_id,
            waiting_reason,
            model: (&model).into(),
            active_workspace_entry: agent
                .active_workspace_entry
                .map(crate::types::ActiveWorkspaceEntry::without_projection_metadata),
        }
    }

    pub async fn operator_agent_tree(&self) -> Result<OwnedAgentTreeRead> {
        self.read_agent_tree().await
    }

    fn agent_list_entry_from_storage(
        &self,
        identity: &AgentIdentityRecord,
    ) -> Result<AgentListEntry> {
        let storage = self.agent_storage(&identity.agent_id)?;
        let agent = match storage.read_agent() {
            Ok(Some(agent)) => agent,
            Ok(None) => try_stopped_unloaded_agent(&identity.agent_id)?,
            Err(error) => {
                warn!(
                    agent_id = %identity.agent_id,
                    error = %error,
                    "failed to read agent state for /agents/list; using stopped placeholder"
                );
                try_stopped_unloaded_agent(&identity.agent_id)?
            }
        };
        let model = crate::runtime::try_agent_model_list_summary_for_catalog(
            self.inner.registry.model_catalog().as_ref(),
            &agent,
        )?;
        let read_models = crate::storage::RuntimeReadModels::borrowed_for_agent(
            self.runtime_db(),
            &identity.agent_id,
        )?;
        let scheduling_posture = match read_models.agent_posture_for_snapshot(&agent) {
            Ok(posture) => posture,
            Err(error) => {
                warn!(
                    agent_id = %identity.agent_id,
                    error = %error,
                    "failed to read agent posture for /agents/list; using unknown placeholder"
                );
                crate::types::AgentPostureProjection::default()
            }
        };
        let waiting_reason = crate::runtime::lightweight_agent_list_waiting_reason(&agent);
        crate::diagnostics::resource_io::admit_cloned_value(identity)?;
        Ok(AgentListEntry {
            identity: AgentIdentityView::from_record(identity, &self.config().default_agent_id),
            lifecycle: AgentLifecycleHint::try_from_status(&agent.id, agent.status.clone())?,
            status: agent.status,
            scheduling_posture,
            pending: agent.pending,
            current_run_id: agent.current_run_id,
            waiting_reason,
            model,
            active_workspace_entry: agent
                .active_workspace_entry
                .map(crate::types::ActiveWorkspaceEntry::without_projection_metadata),
        })
    }

    /// Authoritative roster snapshot data (S4): membership, per-Agent
    /// committed event windows, and latest canonical Brief anchors from one
    /// committed database read view. All-or-nothing: any per-Agent assembly
    /// failure fails the whole snapshot, and entries reflect committed
    /// canonical state instead of in-memory runtime watchers.
    #[cfg(test)]
    pub(crate) fn agent_roster_snapshot(&self) -> Result<AgentRosterSnapshotData> {
        let acquisition = self.observer_inventory_material()?;
        acquisition.read(|| self.agent_roster_snapshot_in(&acquisition))
    }

    pub(crate) fn agent_roster_snapshot_scoped(
        &self,
        db: &RuntimeDb,
    ) -> Result<AgentRosterSnapshotData> {
        db.check_read_scope()?;
        let acquisition = self.observer_inventory_material()?;
        acquisition.read(|| self.agent_roster_snapshot_in_scoped(&acquisition, db))
    }

    #[cfg(test)]
    fn agent_roster_snapshot_in(
        &self,
        acquisition: &crate::diagnostics::resource_io::ResourceReadMaterial,
    ) -> Result<AgentRosterSnapshotData> {
        self.agent_roster_snapshot_in_scoped(acquisition, self.runtime_db())
    }

    fn agent_roster_snapshot_in_scoped(
        &self,
        acquisition: &crate::diagnostics::resource_io::ResourceReadMaterial,
        db: &RuntimeDb,
    ) -> Result<AgentRosterSnapshotData> {
        let rows = db.agent_roster_snapshot_rows()?;
        let config = self.config();
        let catalog = crate::config::ModelListCatalog::from_config(&config);
        let mut agents = Vec::new();
        crate::diagnostics::resource_io::charge_owned_metadata(
            (rows.rows.len() * std::mem::size_of::<AgentRosterEntryData>()) as u64,
            rows.rows.len(),
        )?;
        agents.try_reserve_exact(rows.rows.len())?;
        for row in rows.rows {
            db.check_read_cancellation()?;
            crate::diagnostics::resource_io::admit_json_payload(&row.identity_json)?;
            let identity: AgentIdentityRecord =
                serde_json::from_str(&row.identity_json).map_err(|error| {
                    anyhow!(
                        "unreadable roster identity payload for {}: {error}",
                        row.agent_id
                    )
                })?;
            let agent_state = row
                .agent_state_json
                .as_deref()
                .map(|payload| {
                    crate::diagnostics::resource_io::admit_json_payload(payload)?;
                    serde_json::from_str::<AgentState>(payload).map_err(|error| {
                        anyhow!(
                            "unreadable roster agent state payload for {}: {error}",
                            row.agent_id
                        )
                    })
                })
                .transpose()?;
            let latest_brief = row
                .latest_brief
                .map(|brief| -> Result<AgentRosterLatestBriefData> {
                    Ok(AgentRosterLatestBriefData {
                        brief_id: brief.brief_id,
                        created_event_seq: brief
                            .created_event_seq
                            .map(|seq| {
                                u64::try_from(seq).map_err(|_| {
                                    anyhow!("negative latest brief linkage for {}", row.agent_id)
                                })
                            })
                            .transpose()?,
                        created_at: chrono::DateTime::parse_from_rfc3339(&brief.created_at)
                            .map(|parsed| parsed.with_timezone(&Utc))
                            .map_err(|error| {
                                anyhow!(
                                    "unreadable latest brief timestamp for {}: {error}",
                                    row.agent_id
                                )
                            })?,
                        preview: brief_preview(brief.preview),
                    })
                })
                .transpose()?;
            let agent =
                self.agent_list_entry_from_committed_state_in(identity, agent_state, catalog, db)?;
            agents.push(AgentRosterEntryData {
                agent,
                event_head_seq: row.event_head_seq,
                oldest_retained_seq: row.oldest_retained_seq,
                latest_brief,
            });
        }
        db.check_read_scope()?;
        Ok(AgentRosterSnapshotData {
            runtime_id: rows.runtime_id,
            event_log_epoch: rows.event_log_epoch,
            visibility_policy_generation: rows.visibility_policy_generation,
            agents,
            _material: rows._material,
            acquisition: acquisition.clone(),
        })
    }

    /// Per-Agent canonical projection snapshot data (S5) assembled from one
    /// committed read view. Returns `None` when the Agent is not an active
    /// public member, so unknown, private, and deleted identities stay
    /// indistinguishable. Assembly is all-or-nothing: an unreadable anchor
    /// fails the whole request instead of substituting placeholder facts.
    #[cfg(test)]
    pub(crate) fn agent_projection_snapshot(
        &self,
        agent_id: &str,
    ) -> Result<Option<AgentProjectionSnapshotData>> {
        let acquisition = self.observer_inventory_material()?;
        acquisition.read(|| self.agent_projection_snapshot_in(agent_id, &acquisition))
    }

    pub(crate) fn agent_projection_snapshot_scoped(
        &self,
        agent_id: &str,
        db: &RuntimeDb,
    ) -> Result<Option<AgentProjectionSnapshotData>> {
        db.check_read_scope()?;
        let acquisition = self.observer_inventory_material()?;
        acquisition.read(|| self.agent_projection_snapshot_in_scoped(agent_id, &acquisition, db))
    }

    #[cfg(test)]
    fn agent_projection_snapshot_in(
        &self,
        agent_id: &str,
        acquisition: &crate::diagnostics::resource_io::ResourceReadMaterial,
    ) -> Result<Option<AgentProjectionSnapshotData>> {
        self.agent_projection_snapshot_in_scoped(agent_id, acquisition, self.runtime_db())
    }

    fn agent_projection_snapshot_in_scoped(
        &self,
        agent_id: &str,
        acquisition: &crate::diagnostics::resource_io::ResourceReadMaterial,
        db: &RuntimeDb,
    ) -> Result<Option<AgentProjectionSnapshotData>> {
        let rows = db.agent_projection_snapshot_rows(agent_id)?;
        db.check_read_scope()?;
        let row = match rows.row {
            Some(row) => row,
            None => return Ok(None),
        };
        crate::diagnostics::resource_io::admit_json_payload(&row.identity_json)?;
        let identity: AgentIdentityRecord =
            serde_json::from_str(&row.identity_json).map_err(|error| {
                anyhow!(
                    "unreadable projection identity payload for {}: {error}",
                    row.agent_id
                )
            })?;
        let agent_state = row
            .agent_state_json
            .as_deref()
            .map(|payload| {
                crate::diagnostics::resource_io::admit_json_payload(payload)?;
                serde_json::from_str::<AgentState>(payload).map_err(|error| {
                    anyhow!(
                        "unreadable projection agent state payload for {}: {error}",
                        row.agent_id
                    )
                })
            })
            .transpose()?;
        let config = self.config();
        let catalog = crate::config::ModelListCatalog::from_config(&config);
        let agent =
            self.agent_list_entry_from_committed_state_in(identity, agent_state, catalog, db)?;
        let current_work_item = row
            .current_work_item
            .map(|work_item| -> Result<AgentWorkItemAnchorData> {
                Ok(AgentWorkItemAnchorData {
                    work_item_id: work_item.work_item_id,
                    state: crate::runtime_db::observer_sync::parse_work_item_state(
                        &work_item.state,
                    )?,
                    // A stored NULL is the pre-plan state; the wire anchor
                    // is non-optional and maps it to the draft baseline.
                    plan_status: work_item
                        .plan_status
                        .as_deref()
                        .map(crate::runtime_db::observer_sync::parse_work_item_plan_status)
                        .transpose()?
                        .unwrap_or(crate::types::WorkItemPlanStatus::Draft),
                    revision: u64::try_from(work_item.revision)
                        .map_err(|_| anyhow!("negative work item revision for {}", row.agent_id))?,
                    updated_at: chrono::DateTime::parse_from_rfc3339(&work_item.updated_at)
                        .map(|parsed| parsed.with_timezone(&Utc))
                        .map_err(|error| {
                            anyhow!(
                                "unreadable work item timestamp for {}: {error}",
                                row.agent_id
                            )
                        })?,
                })
            })
            .transpose()?;
        let latest_brief = row
            .latest_brief
            .map(|brief| -> Result<AgentRosterLatestBriefData> {
                Ok(AgentRosterLatestBriefData {
                    brief_id: brief.brief_id,
                    created_event_seq: brief
                        .created_event_seq
                        .map(|seq| {
                            u64::try_from(seq).map_err(|_| {
                                anyhow!("negative latest brief linkage for {}", row.agent_id)
                            })
                        })
                        .transpose()?,
                    created_at: chrono::DateTime::parse_from_rfc3339(&brief.created_at)
                        .map(|parsed| parsed.with_timezone(&Utc))
                        .map_err(|error| {
                            anyhow!(
                                "unreadable latest brief timestamp for {}: {error}",
                                row.agent_id
                            )
                        })?,
                    preview: brief_preview(brief.preview),
                })
            })
            .transpose()?;
        // Hydration references mirror the anchors the projection itself
        // names; each id resolves through the per-family batch record API.
        let hydration_references = projection_hydration_references(
            row.latest_message_id.as_deref(),
            row.latest_transcript_entry_id.as_deref(),
            latest_brief.as_ref().map(|brief| brief.brief_id.as_str()),
        )?;
        db.check_read_scope()?;
        Ok(Some(AgentProjectionSnapshotData {
            runtime_id: rows.runtime_id,
            event_log_epoch: rows.event_log_epoch,
            visibility_policy_generation: rows.visibility_policy_generation,
            agent_id: row.agent_id,
            snapshot_through_seq: row.event_head_seq,
            event_head_seq: row.event_head_seq,
            oldest_retained_seq: row.oldest_retained_seq,
            agent,
            canonical_relations: row.canonical_relations,
            current_work_item,
            conversation: ConversationRevisionAnchorsData {
                latest_message_id: row.latest_message_id,
                latest_transcript_entry_id: row.latest_transcript_entry_id,
            },
            latest_brief,
            hydration_references,
            _material: rows._material,
            acquisition: acquisition.clone(),
        }))
    }

    /// Builds one roster `AgentListEntry` from the committed identity and
    /// AgentState captured by the snapshot read view. Unlike
    /// `agent_list_entry_from_storage`, read failures propagate: the roster
    /// is all-or-nothing and never substitutes placeholder facts. A member
    /// with no committed state yet keeps the stopped placeholder semantics
    /// it would also get from `/agents/list`.
    #[cfg(test)]
    fn agent_list_entry_from_committed_state<'a>(
        &self,
        identity: AgentIdentityRecord,
        agent_state: Option<AgentState>,
        catalog: impl Into<crate::config::ModelListCatalog<'a>>,
    ) -> Result<AgentListEntry> {
        self.agent_list_entry_from_committed_state_in(
            identity,
            agent_state,
            catalog,
            self.runtime_db(),
        )
    }

    fn agent_list_entry_from_committed_state_in<'a>(
        &self,
        identity: AgentIdentityRecord,
        agent_state: Option<AgentState>,
        catalog: impl Into<crate::config::ModelListCatalog<'a>>,
        db: &RuntimeDb,
    ) -> Result<AgentListEntry> {
        let read_models =
            crate::storage::RuntimeReadModels::borrowed_for_agent(db, &identity.agent_id)?;
        let agent = match agent_state {
            Some(agent) => agent,
            None => try_stopped_unloaded_agent(&identity.agent_id)?,
        };
        let model = crate::runtime::try_agent_model_list_summary_for_catalog(catalog, &agent)?;
        let scheduling_posture = read_models.agent_posture_for_snapshot(&agent)?;
        let waiting_reason = crate::runtime::lightweight_agent_list_waiting_reason(&agent);
        Ok(AgentListEntry {
            identity: AgentIdentityView::from_owned_record(
                identity,
                &self.config().default_agent_id,
            ),
            lifecycle: AgentLifecycleHint::try_from_status(&agent.id, agent.status.clone())?,
            status: agent.status,
            scheduling_posture,
            pending: agent.pending,
            current_run_id: agent.current_run_id,
            waiting_reason,
            model,
            active_workspace_entry: agent
                .active_workspace_entry
                .map(crate::types::ActiveWorkspaceEntry::without_projection_metadata),
        })
    }

    pub async fn public_agent_activity_snapshots(
        &self,
    ) -> Result<Vec<PublicAgentActivitySnapshot>> {
        let mut snapshots = Vec::new();
        for identity in self.agent_identity_records()?.into_iter().filter(|record| {
            record.status == AgentRegistryStatus::Active
                && record.visibility == AgentVisibility::Public
        }) {
            if let Some(runtime) = self.try_get_loaded_runtime(&identity.agent_id).await {
                let state = runtime.agent_state().await?;
                let active_task_count = runtime.active_tasks(usize::MAX).await?.len();
                snapshots.push(PublicAgentActivitySnapshot {
                    agent_id: identity.agent_id,
                    status: state.status.clone(),
                    active_task_count,
                    last_runtime_failure: state.last_runtime_failure,
                });
                continue;
            }
            let storage = self.agent_storage(&identity.agent_id)?;
            let state = storage
                .read_agent()?
                .unwrap_or_else(|| AgentState::new(identity.agent_id.clone()));
            let active_task_count = storage.active_task_count_for_agent(&identity.agent_id)?;
            snapshots.push(PublicAgentActivitySnapshot {
                agent_id: identity.agent_id,
                status: state.status.clone(),
                active_task_count,
                last_runtime_failure: state.last_runtime_failure,
            });
        }
        snapshots.sort_by(|left, right| left.agent_id.cmp(&right.agent_id));
        Ok(snapshots)
    }

    pub async fn preview_public_agent_prompt(
        &self,
        agent_id: &str,
        text: String,
        authority_class: AuthorityClass,
        budget_override: Option<usize>,
    ) -> std::result::Result<EffectivePrompt, PublicAgentError> {
        let identity = self.public_agent_identity(agent_id)?;
        self.preview_agent_prompt_from_storage(&identity, text, authority_class, budget_override)
            .await
            .map_err(PublicAgentError::Runtime)
    }

    pub async fn preview_agent_prompt(
        &self,
        agent_id: &str,
        text: String,
        authority_class: AuthorityClass,
    ) -> Result<EffectivePrompt> {
        self.validate_agent_id(agent_id)?;
        let identity = if agent_id == self.config().default_agent_id {
            self.agent_identity_record(agent_id)?
                .ok_or_else(|| anyhow!("default agent {} has not been created yet", agent_id))?
        } else {
            self.agent_identity_record(agent_id)?.ok_or_else(|| {
                anyhow!(
                    "agent {} not found; create it first with 'holon agent create {}'",
                    agent_id,
                    agent_id
                )
            })?
        };
        self.active_agent_identity(agent_id)
            .map_err(anyhow::Error::new)?;
        self.preview_agent_prompt_from_storage(&identity, text, authority_class, None)
            .await
    }

    pub async fn preview_agent_prompt_with_budget(
        &self,
        agent_id: &str,
        text: String,
        authority_class: AuthorityClass,
        budget: usize,
    ) -> Result<EffectivePrompt> {
        self.validate_agent_id(agent_id)?;
        let identity = self.agent_identity_record(agent_id)?.ok_or_else(|| {
            anyhow!(
                "agent {agent_id} not found; create it first with 'holon agent create {agent_id}'"
            )
        })?;
        self.active_agent_identity(agent_id)
            .map_err(anyhow::Error::new)?;
        self.preview_agent_prompt_from_storage(&identity, text, authority_class, Some(budget))
            .await
    }

    pub fn public_agent_boundary_metadata(
        &self,
        agent_id: &str,
    ) -> std::result::Result<Value, PublicAgentError> {
        let identity = self.public_agent_identity(agent_id)?;
        self.agent_boundary_metadata_from_storage(&identity)
            .map_err(PublicAgentError::Runtime)
    }

    async fn preview_agent_prompt_from_storage(
        &self,
        identity: &AgentIdentityRecord,
        text: String,
        authority_class: AuthorityClass,
        budget_override: Option<usize>,
    ) -> Result<EffectivePrompt> {
        let storage = self.agent_storage_read_only(&identity.agent_id)?;
        let state = storage
            .read_agent()?
            .unwrap_or_else(|| AgentState::new(identity.agent_id.clone()));
        let identity_view =
            AgentIdentityView::from_record(identity, &self.config().default_agent_id);
        let message = MessageEnvelope::new(
            identity.agent_id.clone(),
            MessageKind::OperatorPrompt,
            MessageOrigin::Operator {
                actor_id: Some("debug_prompt".into()),
                actor_display_name: None,
            },
            authority_class,
            Priority::Normal,
            MessageBody::Text { text },
        )
        .with_admission(
            MessageDeliverySurface::CliPrompt,
            AdmissionContext::LocalProcess,
        );
        let workspace = crate::runtime::workspace::workspace_view_from_state(
            &state,
            storage.data_dir().to_path_buf(),
        )?;
        let execution = crate::runtime::workspace::build_effective_execution(
            &storage,
            ExecutionScopeKind::AgentTurn,
            state.execution_profile.clone(),
            workspace,
            &state.attached_workspaces,
        )
        .snapshot();
        let agent_home = self.agent_data_dir(&identity.agent_id);
        let config = self.config();
        let loaded_agents_md = load_agents_md(
            config.user_home_dir.as_deref(),
            agent_home.as_path(),
            crate::runtime::workspace::workspace_anchor_for_state_ref(&state),
        )?;
        let loaded_agent_memory = load_agent_memory(agent_home.as_path())?;
        let skill_visibility = skill_visibility(&identity_view);
        let workspace_skill_root = state
            .active_workspace_entry
            .as_ref()
            .map(|entry| entry.execution_root.as_path());
        let skill_roots = effective_skill_root_registrations(
            skill_visibility,
            config.user_home_dir.as_deref(),
            &state.id,
            agent_home.as_path(),
            workspace_skill_root,
        );
        let mut skill_registry = self.inner.skills_registry.write().await;
        skill_registry.sync_effective_roots(skill_roots.clone())?;
        let mut skills = skills_runtime_view_from_catalog(
            skill_registry.catalog_for_roots(&skill_roots, None),
            &skill_roots,
            &state.active_skills,
        )?;
        skills.agent_templates_catalog =
            discover_agent_templates_catalog(config.user_home_dir.as_deref(), agent_home.as_path());
        let model_catalog = RuntimeModelCatalog::from_config(&config);
        let model_ref = model_catalog
            .provider_chain(state.model_override.as_ref())
            .into_iter()
            .next()
            .unwrap_or_else(|| {
                crate::runtime::agent_model_state_for_catalog(
                    &model_catalog,
                    &self.runtime_context_config(),
                    &state,
                )
                .effective_model
            });
        let static_provider = self
            .inner
            .static_provider
            .lock()
            .expect("static provider lock poisoned")
            .clone();
        let provider = static_provider
            .map(Ok)
            .unwrap_or_else(|| build_provider_from_config(&config))?;
        let apply_patch_surface = ApplyPatchSurface::for_model_route_ref(&model_ref.as_string());
        let registry = ToolRegistry::new(execution.execution_root.clone());
        let capability_policy = self
            .runtime_db()
            .agent_canonical_relations()
            .latest(&identity.agent_id)?
            .and_then(|relations| relations.capability_policy);
        let available_tools = registry
            .tool_specs_with_families_for_apply_patch_surface(apply_patch_surface)?
            .into_iter()
            .filter(|(family, _)| {
                capability_policy
                    .as_ref()
                    .is_none_or(|policy| policy.allows(*family))
            })
            .map(|(_, tool)| tool)
            .collect::<Vec<_>>();
        let prompt_tools = provider.prompt_tool_specs(&available_tools);
        let mut context_config = self.runtime_context_config();
        if let Some(budget) = budget_override {
            context_config.prompt_budget_estimated_tokens = budget;
        }
        build_effective_prompt_with_apply_patch_surface(
            &storage,
            &state,
            &execution,
            &message,
            &context_config,
            &execution.execution_root,
            agent_home.as_path(),
            &identity_view,
            loaded_agents_md,
            loaded_agent_memory,
            &skills,
            &prompt_tools,
            apply_patch_surface,
            None,
        )
    }

    fn agent_boundary_metadata_from_storage(
        &self,
        identity: &AgentIdentityRecord,
    ) -> Result<Value> {
        let storage = self.agent_storage_read_only(&identity.agent_id)?;
        let state = storage
            .read_agent()?
            .unwrap_or_else(|| AgentState::new(identity.agent_id.clone()));
        let workspace = crate::runtime::workspace::workspace_view_from_state(
            &state,
            storage.data_dir().to_path_buf(),
        )?;
        let execution = crate::runtime::workspace::build_effective_execution(
            &storage,
            ExecutionScopeKind::AgentTurn,
            state.execution_profile.clone(),
            workspace,
            &state.attached_workspaces,
        );
        Ok(HostLocalBoundary::from_snapshot(&execution.snapshot()).audit_metadata())
    }

    pub async fn child_agent_summaries(
        &self,
        parent_agent_id: &str,
    ) -> Result<Vec<ChildAgentSummary>> {
        let mut children = Vec::new();
        for (identity, material) in self
            .inner
            .registry
            .child_identity_reads(parent_agent_id, &self.inner.input_evidence_budget)?
        {
            if let Some(runtime) = self.try_get_loaded_runtime(&identity.agent_id).await {
                let mut read = runtime.child_agent_summary_observation().await?;
                read.observability._source_material = Some(material.guard()?);
                read.acquisition.read(|| {
                    crate::diagnostics::resource_io::admit_cloned_value(
                        &read.state.current_run_id,
                    )?;
                    crate::runtime_db::repositories::reserve_source_vec_slot(&mut children)?;
                    children.push(ChildAgentSummary {
                        identity: AgentIdentityView::from_owned_record(
                            identity,
                            &self.config().default_agent_id,
                        ),
                        status: read.state.status.clone(),
                        current_run_id: read.state.current_run_id.clone(),
                        pending: read.state.pending,
                        active_task_count: read.active_task_count,
                        observability: read.observability,
                    });
                    Ok(())
                })?;
                continue;
            }
            let cold = self.acquire_cold_summary(&identity).await?;
            let active_task_count = cold.projection().active_tasks.len();
            let mut observability = cold.observability()?;
            observability._source_material = Some(material.guard()?);
            cold.acquisition.read(|| {
                crate::runtime_db::repositories::reserve_source_vec_slot(&mut children)?;
                children.push(ChildAgentSummary {
                    identity: AgentIdentityView::from_owned_record(
                        cold.identity,
                        &self.config().default_agent_id,
                    ),
                    status: cold.state.status,
                    current_run_id: cold.state.current_run_id,
                    pending: cold.state.pending,
                    active_task_count,
                    observability,
                });
                Ok(())
            })?;
        }
        children.sort_by(|left, right| left.identity.agent_id.cmp(&right.identity.agent_id));
        Ok(children)
    }

    pub(crate) async fn deliver_external_callback(
        &self,
        agent_id: &str,
        descriptor_id: &str,
        payload: crate::types::CallbackDeliveryPayload,
    ) -> Result<crate::types::CallbackDeliveryResult> {
        for _ in 0..3 {
            let identity = self
                .active_agent_identity(agent_id)
                .map_err(anyhow::Error::new)?;
            let runtime = if identity.visibility == AgentVisibility::Public {
                self.get_public_agent_for_external_ingress(agent_id)
                    .await
                    .map_err(anyhow::Error::new)?
            } else {
                self.get_or_create_agent(agent_id).await?
            };
            match runtime
                .deliver_callback(descriptor_id, payload.clone())
                .await
            {
                Ok(result) => return Ok(result),
                Err(error)
                    if describe_runtime_error(&error).code == "runtime_instance_retiring" =>
                {
                    continue;
                }
                Err(error) => return Err(error),
            }
        }
        Err(crate::runtime::execution_admission::closed_error())
    }

    fn callback_discovery_request(
        &self,
    ) -> Result<crate::runtime_db::scheduling_snapshot::SchedulingDomainLoadRequest> {
        let limits = self.inner.input_evidence_budget.limits();
        Ok(
            crate::runtime_db::scheduling_snapshot::SchedulingDomainLoadRequest {
                capture: crate::runtime::resident_scheduling::SchedulingCaptureRequest::current(),
                byte_limit: usize::try_from(
                    limits
                        .history_per_agent_bytes
                        .checked_add(limits.pending_per_agent_bytes)
                        .context("callback discovery byte limit overflow")?,
                )?,
                record_limit: usize::try_from(limits.record_limit)?,
            },
        )
    }

    pub(crate) fn resolve_external_trigger_locator(
        &self,
        callback_token: &str,
    ) -> Result<Option<crate::runtime_db::scheduling_snapshot::ExternalTriggerTokenLocator>> {
        let token_hash = hash_callback_token(callback_token);
        let request = self.callback_discovery_request()?;
        self.runtime_db().transaction(|tx| {
            crate::runtime_db::scheduling_snapshot::discover_external_trigger_token_tx(
                tx,
                &token_hash,
                &request,
                &self.inner.input_evidence_budget,
            )
        })
    }

    fn read_external_trigger_token_compatibility(
        &self,
        callback_token: &str,
    ) -> Result<Option<crate::runtime_db::scheduling_snapshot::ExternalTriggerTokenRecordRead>>
    {
        let token_hash = hash_callback_token(callback_token);
        let request = self.callback_discovery_request()?;
        self.runtime_db().transaction(|tx| {
            crate::runtime_db::scheduling_snapshot::read_external_trigger_token_compatibility_tx(
                tx,
                &token_hash,
                &request,
                &self.inner.input_evidence_budget,
            )
        })
    }

    pub async fn resolve_external_trigger(
        &self,
        callback_token: &str,
    ) -> Result<Option<(RuntimeHandle, ExternalTriggerRecord)>> {
        let Some(read) = self.read_external_trigger_token_compatibility(callback_token)? else {
            return Ok(None);
        };
        // This legacy adapter retains all decoded material across activation.
        let runtime = self
            .get_or_create_agent(&read.record().target_agent_id)
            .await?;
        Ok(Some((runtime, read.into_record())))
    }

    pub async fn resolve_external_trigger_record(
        &self,
        callback_token: &str,
    ) -> Result<Option<(String, ExternalTriggerRecord)>> {
        let Some(read) = self.read_external_trigger_token_compatibility(callback_token)? else {
            return Ok(None);
        };
        let agent_id = read.record().target_agent_id.clone();
        Ok(Some((agent_id, read.into_record())))
    }

    pub(crate) fn ensure_default_agent_identity(&self) -> Result<AgentIdentityRecord> {
        self.inner.registry.ensure_default_agent_identity()
    }

    fn ensure_legacy_public_agent_bootstraps(&self) -> Result<()> {
        // Non-Active identities must not regain legacy bootstrap rows:
        // deletion purges `agent_bootstraps` as private history, and
        // restoring a row for a Deleting/Deleted identity recreates residue.
        for identity in self
            .inner
            .registry
            .agent_identity_records()?
            .into_iter()
            .filter(|record| record.status == AgentRegistryStatus::Active)
        {
            if identity.kind != AgentKind::Named
                || identity.visibility != AgentVisibility::Public
                || identity.ownership() != AgentOwnership::SelfOwned
                || self
                    .runtime_db()
                    .agent_bootstraps()
                    .latest(&identity.agent_id)?
                    .is_some()
            {
                continue;
            }
            self.runtime_db()
                .agent_bootstraps()
                .upsert(&AgentBootstrapRecord::legacy_ready(&identity.agent_id))?;
        }
        Ok(())
    }

    async fn ensure_default_agent_home_initialized(&self) -> Result<()> {
        let config = self.config();
        let agent_home = self.agent_data_dir(&config.default_agent_id);
        let template_home = config
            .user_home_dir
            .as_deref()
            .unwrap_or(config.home_dir.as_path());
        let _ = ensure_agent_home_agents_md_without_template_with_home(&agent_home, template_home)
            .await?;
        Ok(())
    }

    async fn create_child_identity(
        &self,
        parent_agent_id: &str,
        task: &TaskRecord,
        template: Option<&str>,
        catalog_agent_home: &Path,
    ) -> Result<AgentIdentityRecord> {
        let child_agent_id = ids::runtime_id(TEMP_CHILD_AGENT_PREFIX.trim_end_matches('_'));
        self.validate_agent_id(&child_agent_id)?;
        let config = self.config();
        let template_home = config
            .user_home_dir
            .as_deref()
            .unwrap_or(config.home_dir.as_path());
        if let Some(template) = template {
            initialize_agent_home_from_template_with_catalog(
                &self.agent_data_dir(&child_agent_id),
                template_home,
                catalog_agent_home,
                template,
            )
            .await?;
        } else {
            initialize_agent_home_without_template_with_home(
                &self.agent_data_dir(&child_agent_id),
                template_home,
            )
            .await?;
        }
        let mut record = AgentIdentityRecord::new(
            child_agent_id,
            AgentKind::Child,
            AgentVisibility::Private,
            AgentOwnership::ParentSupervised,
            AgentProfilePreset::PrivateChild,
            Some(parent_agent_id.to_string()),
            Some(task.id.clone()),
        )
        .with_lineage_parent_agent_id(Some(parent_agent_id.to_string()));
        record.durability = Some(AgentDurability::Ephemeral);
        let relations = supervised_creation_records(
            &record,
            parent_agent_id,
            &task.id,
            task.effective_work_item_id(),
        );
        self.runtime_db()
            .agent_identities()
            .create_with_relations(&record, &relations)?;
        self.inner.registry.cache_agent_identity(&record)?;
        Ok(record)
    }

