    pub(crate) async fn deliver_child_followup(
        &self,
        parent_agent_id: &str,
        task_id: &str,
        child_agent_id: &str,
        input: &str,
        authority_class: AuthorityClass,
    ) -> Result<bool> {
        if !self.reusable_agent_exists(child_agent_id).await? {
            return Ok(false);
        }
        let runtime = match self.host()?.get_or_create_agent(child_agent_id).await {
            Ok(runtime) => runtime,
            Err(error) => {
                if !self.reusable_agent_exists(child_agent_id).await? {
                    return Ok(false);
                }
                return Err(error);
            }
        };
        let mut message = crate::types::MessageEnvelope::new(
            child_agent_id.to_string(),
            crate::types::MessageKind::InternalFollowup,
            crate::types::MessageOrigin::Task {
                task_id: task_id.to_string(),
            },
            authority_class.clone(),
            crate::types::Priority::Normal,
            crate::types::MessageBody::Text {
                text: input.to_string(),
            },
        )
        .with_admission(
            crate::types::MessageDeliverySurface::RuntimeSystem,
            crate::types::AdmissionContext::RuntimeOwned,
        );
        message.metadata = Some(json!({
            "delegated_task_id": task_id,
            "parent_agent_id": parent_agent_id,
            "child_agent_id": child_agent_id,
            "followup_via": "task_input",
            "delegated_authority_class": authority_class,
        }));
        self.enqueue_child_followup(runtime, message).await
    }

    async fn enqueue_child_followup(
        &self,
        mut runtime: RuntimeHandle,
        message: MessageEnvelope,
    ) -> Result<bool> {
        for _ in 0..3 {
            match runtime.enqueue(message.clone()).await {
                Ok(_) => return Ok(true),
                Err(error)
                    if describe_runtime_error(&error).code == "runtime_instance_retiring" =>
                {
                    runtime = match self.host()?.get_or_create_agent(&message.agent_id).await {
                        Ok(runtime) => runtime,
                        Err(error) => {
                            if !self.reusable_agent_exists(&message.agent_id).await? {
                                return Ok(false);
                            }
                            return Err(error);
                        }
                    };
                }
                Err(error) => return Err(error),
            }
        }
        Err(crate::runtime::execution_admission::closed_error())
    }

