    fn append_public_identity(host: &RuntimeHost, agent_id: &str) -> AgentIdentityRecord {
        let identity = AgentIdentityRecord::new(
            agent_id,
            AgentKind::Named,
            AgentVisibility::Public,
            AgentOwnership::SelfOwned,
            AgentProfilePreset::PublicNamed,
            None,
            None,
        );
        host.append_agent_identity(&identity).unwrap();
        host.runtime_db()
            .agent_identities()
            .upsert(&identity)
            .unwrap();
        identity
    }

    #[tokio::test]
    async fn scoped_host_snapshots_and_list_match_ordinary_reads_and_reject_cancelled_empty_reads()
    {
        let (_home, host) = test_host();
        append_public_identity(&host, "scoped-snapshot-agent");
        host.runtime_db()
            .agent_states()
            .upsert_for_fixture(&AgentState::new("scoped-snapshot-agent"))
            .unwrap();
        let scope = crate::runtime_db::RuntimeDbReadScope::new(
            std::time::Instant::now() + Duration::from_secs(30),
        );
        let scoped = host.runtime_db().with_read_scope(scope.clone());
        assert_eq!(
            host.agent_roster_snapshot().unwrap(),
            host.agent_roster_snapshot_scoped(&scoped).unwrap()
        );
        assert_eq!(
            host.agent_projection_snapshot("scoped-snapshot-agent")
                .unwrap(),
            host.agent_projection_snapshot_scoped("scoped-snapshot-agent", &scoped)
                .unwrap()
        );
        assert_eq!(
            host.list_agent_entries().await.unwrap(),
            host.list_agent_entries_for_parent_scoped(None, &scoped)
                .unwrap()
        );
        assert!(host
            .agent_projection_snapshot_scoped("missing-agent", &scoped)
            .unwrap()
            .is_none());
        assert!(host
            .list_agent_entries_for_parent_scoped(Some("missing-parent"), &scoped)
            .unwrap()
            .is_empty());
        scope.cancel();
        for error in [
            host.agent_roster_snapshot_scoped(&scoped).unwrap_err(),
            host.agent_projection_snapshot_scoped("missing-agent", &scoped)
                .unwrap_err(),
            host.list_agent_entries_for_parent_scoped(Some("missing-parent"), &scoped)
                .unwrap_err(),
        ] {
            assert!(
                error.is::<crate::runtime_db::RuntimeDbRetryableError>(),
                "{error:#}"
            );
        }
        assert!(host.agent_roster_snapshot().is_ok());
    }

    #[tokio::test(flavor = "current_thread")]
    async fn scoped_loaded_lookup_times_out_without_falling_back_to_unloaded() {
        let (_home, host) = test_host();
        let agent_id = host.config().default_agent_id.clone();
        let _runtime = host.get_or_create_agent(&agent_id).await.unwrap();
        let held = host.inner.runtimes.write().await;
        let scoped = host
            .runtime_db()
            .with_read_scope(crate::runtime_db::RuntimeDbReadScope::new(
                std::time::Instant::now() + Duration::from_millis(50),
            ));
        let error = tokio::time::timeout(
            Duration::from_secs(5),
            host.try_get_loaded_runtime_scoped(&agent_id, &scoped),
        )
        .await
        .unwrap()
        .err()
        .expect("lock timeout must be an error, not unloaded None");
        assert!(
            error.is::<crate::runtime_db::RuntimeDbRetryableError>(),
            "{error:#}"
        );
        drop(held);
        let healthy =
            host.runtime_db()
                .with_read_scope(crate::runtime_db::RuntimeDbReadScope::new(
                    std::time::Instant::now() + Duration::from_secs(30),
                ));
        assert!(host
            .try_get_loaded_runtime_scoped(&agent_id, &healthy)
            .await
            .unwrap()
            .is_some());
        assert!(host
            .try_get_loaded_runtime_scoped("missing-agent", &healthy)
            .await
            .unwrap()
            .is_none());
    }

    #[cfg(target_os = "linux")]
    #[tokio::test]
    async fn scoped_host_empty_reads_preserve_protection_failure_over_cancellation() {
        let (_home, host) = test_host();
        let scope = crate::runtime_db::RuntimeDbReadScope::new(
            std::time::Instant::now() + Duration::from_secs(30),
        );
        let scoped = host.runtime_db().with_read_scope(scope.clone());
        let mut wal = scoped.path().as_os_str().to_os_string();
        wal.push("-wal");
        std::fs::remove_file(std::path::PathBuf::from(wal)).unwrap();
        scope.cancel();
        let lookup_error = host
            .try_get_loaded_runtime_scoped("missing-agent", &scoped)
            .await
            .err()
            .expect("protection failure must not become unloaded None");
        for error in [
            host.agent_roster_snapshot_scoped(&scoped).unwrap_err(),
            host.agent_projection_snapshot_scoped("missing-agent", &scoped)
                .unwrap_err(),
            host.list_agent_entries_for_parent_scoped(Some("missing-parent"), &scoped)
                .unwrap_err(),
            lookup_error,
        ] {
            assert!(
                error.is::<crate::runtime_db::RuntimeDbProtectionError>(),
                "{error:#}"
            );
        }
    }

    #[tokio::test]
    async fn list_agent_entries_serves_committed_postures_per_agent() {
        let (_home, host) = test_host();
        for agent_id in [
            "stopped-agent",
            "active-agent",
            "queued-agent",
            "waiting-agent",
        ] {
            append_public_identity(&host, agent_id);
        }
        let now = Utc::now();

        let mut stopped = AgentState::new("stopped-agent");
        stopped.status = AgentStatus::Stopped;
        host.runtime_db()
            .agent_states()
            .upsert_for_fixture(&stopped)
            .unwrap();

        let mut active = AgentState::new("active-agent");
        active.current_run_id = Some("run-1".into());
        host.runtime_db()
            .agent_states()
            .upsert_for_fixture(&active)
            .unwrap();

        host.runtime_db()
            .agent_states()
            .upsert_for_fixture(&AgentState::new("queued-agent"))
            .unwrap();
        host.runtime_db()
            .queue_entries()
            .upsert(&QueueEntryRecord {
                message_id: "message-1".into(),
                agent_id: "queued-agent".into(),
                priority: Priority::Normal,
                status: QueueEntryStatus::Queued,
                created_at: now,
                updated_at: now,
            })
            .unwrap();

        let wait_item = WorkItemRecord::new("waiting-agent", "waiting item", WorkItemState::Open);
        host.runtime_db()
            .work_items()
            .insert_new(&wait_item)
            .unwrap();
        let mut waiting = AgentState::new("waiting-agent");
        waiting.current_work_item_id = Some(wait_item.id.clone());
        host.runtime_db()
            .agent_states()
            .upsert_for_fixture(&waiting)
            .unwrap();
        host.runtime_db()
            .wait_conditions()
            .upsert(&WaitConditionRecord {
                id: "wait-1".into(),
                agent_id: "waiting-agent".into(),
                work_item_id: Some(wait_item.id.clone()),
                status: WaitConditionStatus::Active,
                kind: WaitConditionKind::Task,
                source: Some("task".into()),
                subject_ref: Some("task-7".into()),
                waiting_for: "task result".into(),
                wake_sources: Vec::new(),
                continuation: None,
                created_at: now,
                updated_at: now,
                expires_at: None,
                resolved_at: None,
                cancelled_at: None,
                turn_id: None,
                trigger_message_id: None,
                triggered_at: None,
            })
            .unwrap();

        let entries = host.list_agent_entries().await.unwrap();
        let by_id = entries
            .into_iter()
            .map(|entry| (entry.identity.agent_id.clone(), entry))
            .collect::<std::collections::HashMap<_, _>>();

        assert_eq!(
            by_id["stopped-agent"].scheduling_posture.posture,
            crate::types::AgentSchedulingPosture::Stopped
        );
        assert_eq!(
            by_id["active-agent"].scheduling_posture.posture,
            crate::types::AgentSchedulingPosture::ActiveTurn
        );
        assert_eq!(
            by_id["active-agent"].current_run_id.as_deref(),
            Some("run-1")
        );
        assert_eq!(
            by_id["queued-agent"].scheduling_posture.posture,
            crate::types::AgentSchedulingPosture::HasQueuedInput
        );
        let waiting_entry = &by_id["waiting-agent"];
        assert_eq!(
            waiting_entry.scheduling_posture.posture,
            crate::types::AgentSchedulingPosture::WaitingForTask
        );
        assert_eq!(
            waiting_entry.scheduling_posture.work_item_id.as_deref(),
            Some(wait_item.id.as_str())
        );
        assert_eq!(
            waiting_entry.scheduling_posture.task_id.as_deref(),
            Some("task-7")
        );
    }

    #[tokio::test]
    async fn list_agent_entries_matches_per_agent_storage_projection() {
        let (_home, host) = test_host();
        let now = Utc::now();
        let mut identities = Vec::new();
        for agent_id in [
            "stopped-agent",
            "queued-agent",
            "waiting-agent",
            "fresh-agent",
        ] {
            identities.push(append_public_identity(&host, agent_id));
        }

        let mut stopped = AgentState::new("stopped-agent");
        stopped.status = AgentStatus::Stopped;
        host.runtime_db()
            .agent_states()
            .upsert_for_fixture(&stopped)
            .unwrap();
        host.runtime_db()
            .agent_states()
            .upsert_for_fixture(&AgentState::new("queued-agent"))
            .unwrap();
        host.runtime_db()
            .queue_entries()
            .upsert(&QueueEntryRecord {
                message_id: "message-2".into(),
                agent_id: "queued-agent".into(),
                priority: Priority::Normal,
                status: QueueEntryStatus::Queued,
                created_at: now,
                updated_at: now,
            })
            .unwrap();
        let wait_item = WorkItemRecord::new("waiting-agent", "waiting item", WorkItemState::Open);
        host.runtime_db()
            .work_items()
            .insert_new(&wait_item)
            .unwrap();
        let mut waiting = AgentState::new("waiting-agent");
        waiting.current_work_item_id = Some(wait_item.id.clone());
        host.runtime_db()
            .agent_states()
            .upsert_for_fixture(&waiting)
            .unwrap();

        drop(identities);
        let entries = host.list_agent_entries().await.unwrap();
        let mut reference = Vec::new();
        for identity in host.agent_identity_records().unwrap() {
            if identity.status == AgentRegistryStatus::Active
                && identity.visibility == AgentVisibility::Public
            {
                reference.push(host.agent_list_entry_from_storage(&identity).unwrap());
            }
        }
        reference.sort_by(|left, right| left.identity.agent_id.cmp(&right.identity.agent_id));
        assert_eq!(entries, reference);
    }

