    #[tokio::test]
    async fn private_child_archive_failure_preserves_recovery_and_failed_task_artifact() {
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let url = format!(
            "http://archive-user:archive-password@{}/api/callbacks/wake/callback-secret?token=query-secret#fragment-secret",
            listener.local_addr().unwrap()
        );
        drop(listener);
        let connection_error = reqwest::Client::builder()
            .no_proxy()
            .timeout(Duration::from_secs(2))
            .build()
            .unwrap()
            .get(url)
            .send()
            .await
            .unwrap_err();
        assert!(connection_error.is_connect());

        for (source, retryable) in [
            (anyhow::Error::new(connection_error), true),
            (
                anyhow::Error::new(std::io::Error::new(
                    std::io::ErrorKind::PermissionDenied,
                    "temporary archive file access denied",
                )),
                false,
            ),
            (anyhow::anyhow!("archive path validation failed"), false),
            (
                anyhow::anyhow!(
                    "Authorization: Bearer do-not-publish\nAuthorization: Bearer private second line"
                ),
                false,
            ),
        ] {
            let (_home, host) = test_host();
            let parent = host.default_runtime().await.unwrap();
            let identities_before = host.agent_identity_records().unwrap().len();
            let failed =
                crate::skills::RemoteSkillArchiveFetchFailed::new("owner/repo@skill", &source);
            let cause = failed.cause.clone();
            let hint = failed.recovery_hint();
            *host.inner.spawn_child_error.lock().unwrap() = Some(
                source
                    .context(failed)
                    .context("template skill setup failed")
                    .context("upstream context: Authorization: Bearer outer-secret"),
            );

            let error = invoke_new_subagent(
                &parent,
                "review the implementation".into(),
                AuthorityClass::OperatorInstruction,
                None,
                None,
            )
            .await
            .expect_err("archive admission failure must not return a successful TaskHandle");
            let tool_error = crate::tool::ToolError::from_anyhow(&error);
            assert_eq!(tool_error.kind, "agent_invocation_failed");
            assert_eq!(
                tool_error.domain,
                Some(crate::runtime_error::RuntimeErrorDomain::Task)
            );
            assert_eq!(tool_error.retryable, retryable);
            assert_eq!(tool_error.recovery_hint.as_deref(), Some(hint));
            assert!(tool_error.message.contains("owner/repo@skill"));
            assert!(tool_error.message.contains(&cause));
            assert!(
                error
                    .downcast_ref::<crate::skills::RemoteSkillArchiveFetchFailed>()
                    .is_some()
            );
            let rendered = tool_error.render_for_model(Some("InvokeAgent"));
            assert!(rendered.contains("owner/repo@skill"));
            assert!(rendered.contains(&cause));
            assert!(!rendered.contains("do-not-publish"));
            assert!(!rendered.contains("private second line"));
            assert!(!rendered.contains("before process exit"));

            let task_id = tool_error
                .details
                .as_ref()
                .and_then(|details| details.get("task_id"))
                .and_then(Value::as_str)
                .expect("failed admission must identify its persisted task");
            let task = parent
                .storage()
                .latest_task_record(task_id)
                .unwrap()
                .unwrap();
            assert_eq!(task.status, TaskStatus::Failed);
            let detail = task.detail.as_ref().unwrap();
            let persisted_cause = detail["error"].as_str().unwrap();
            assert!(persisted_cause.contains("owner/repo@skill"));
            assert!(persisted_cause.contains(&cause));
            assert!(!persisted_cause.contains("do-not-publish"));
            assert!(
                detail
                    .get("child_agent_id")
                    .and_then(Value::as_str)
                    .is_none()
            );
            let output = parent.task_output(task_id, false, 0).await.unwrap();
            let failure = output
                .task
                .failure_artifact
                .expect("failed admission must expose a failure artifact");
            assert_eq!(failure.task_id.as_deref(), Some(task_id));
            assert!(
                failure
                    .source_chain
                    .iter()
                    .any(|entry| entry.contains("owner/repo@skill") && entry.contains(&cause))
            );
            assert!(
                !serde_json::to_string(&failure)
                    .unwrap()
                    .contains("do-not-publish")
            );
            for serialized in [
                rendered,
                serde_json::to_string(&tool_error).unwrap(),
                serde_json::to_string(&task).unwrap(),
                serde_json::to_string(&failure).unwrap(),
                serde_json::to_string(&crate::runtime_error::describe_runtime_error(&error))
                    .unwrap(),
            ] {
                for secret in [
                    "archive-user",
                    "archive-password",
                    "callback-secret",
                    "query-secret",
                    "fragment-secret",
                    "do-not-publish",
                    "private second line",
                    "outer-secret",
                ] {
                    assert!(!serialized.contains(secret), "{secret}: {serialized}");
                }
            }
            assert_eq!(
                host.agent_identity_records().unwrap().len(),
                identities_before
            );
        }
    }

    #[tokio::test]
    async fn private_child_spawn_failure_preserves_safe_cause_in_tool_and_task_diagnostics() {
        let (_home, host) = test_host();
        let parent = host.default_runtime().await.unwrap();

        let error = invoke_new_subagent(
            &parent,
            "review the implementation".into(),
            AuthorityClass::OperatorInstruction,
            Some("user_global:reviewer%official".into()),
            None,
        )
        .await
        .expect_err("invalid template selector should fail after task creation");
        let tool_error = crate::tool::ToolError::from_anyhow(&error);

        assert_eq!(tool_error.kind, "agent_invocation_failed");
        assert_eq!(
            tool_error.domain,
            Some(crate::runtime_error::RuntimeErrorDomain::Task)
        );
        assert!(tool_error
            .message
            .contains("template install_id contains unsupported characters"));
        assert!(tool_error
            .source_chain
            .iter()
            .any(|cause| cause.contains("template install_id contains unsupported characters")));
        let task_id = tool_error
            .details
            .as_ref()
            .and_then(|details| details.get("task_id"))
            .and_then(Value::as_str)
            .expect("tool error should identify the failed supervision task");
        let rendered = tool_error.render_for_model(Some("InvokeAgent"));
        assert!(rendered.contains("template install_id contains unsupported characters"));

        let task = parent
            .storage()
            .latest_task_record(task_id)
            .unwrap()
            .expect("failed supervision task should remain persisted");
        assert_eq!(task.status, TaskStatus::Failed);
        assert_eq!(
            task.detail.as_ref().unwrap()["error"],
            "template install_id contains unsupported characters"
        );

        let output = parent.task_output(task_id, false, 0).await.unwrap();
        let failure = output
            .task
            .failure_artifact
            .expect("failed supervision task should expose a failure artifact");
        assert!(failure
            .source_chain
            .iter()
            .any(|cause| cause.contains("template install_id contains unsupported characters")));
    }

    #[tokio::test]
    async fn legacy_child_spawn_failure_after_identity_creation_requests_deletion() {
        let home = tempdir().unwrap();
        write_test_model_config(home.path());
        let mut config = AppConfig::load_with_home(Some(home.path().to_path_buf())).unwrap();
        config.user_home_dir = Some(home.path().to_path_buf());
        config.workspace_dir = home.path().join("non-git-workspace");
        fs::create_dir_all(&config.workspace_dir).unwrap();
        let host =
            RuntimeHost::new_with_provider(config, Arc::new(StubProvider::new("done"))).unwrap();
        let parent = host.default_runtime().await.unwrap();
        let workspace = host
            .ensure_workspace_entry(host.config().workspace_dir.clone())
            .unwrap();
        parent.attach_workspace(&workspace).await.unwrap();
        parent
            .enter_workspace(
                &workspace,
                WorkspaceProjectionKind::CanonicalRoot,
                WorkspaceAccessMode::SharedRead,
                Some(host.config().workspace_dir.clone()),
                None,
            )
            .await
            .unwrap();

        let task = parent
            .schedule_child_agent_task(
                "fail after child creation".into(),
                "this prompt should never be delivered".into(),
                AuthorityClass::OperatorInstruction,
                ChildAgentWorkspaceMode::Worktree,
            )
            .await
            .unwrap();
        let terminal = wait_for_terminal_task(&parent, &task.id).await;
        assert_eq!(terminal.status, TaskStatus::Failed);
        let output = parent.task_output(&task.id, false, 0).await.unwrap();
        let child_agent_id = terminal
            .detail
            .as_ref()
            .and_then(|detail| detail.get("child_agent_id"))
            .and_then(Value::as_str)
            .unwrap_or_else(|| {
                panic!(
                    "failed spawn should persist the created child identity: detail={:?}, output={}",
                    terminal.detail, output.task.output_preview
                )
            });

        let deletion_job = host
            .runtime_db()
            .agent_deletions()
            .latest_for_agent(child_agent_id)
            .unwrap()
            .expect("failed spawn should create a canonical deletion job");
        assert_eq!(deletion_job.mode, AgentDeletionMode::Delete);
        assert_eq!(deletion_job.requested_by, "parent_task_spawn_failed");
        assert!(matches!(
            host.agent_identity_record(child_agent_id)
                .unwrap()
                .expect("child identity should remain represented")
                .status,
            AgentRegistryStatus::Deleting | AgentRegistryStatus::Deleted
        ));
    }

