    #[tokio::test]
    async fn parent_summary_shows_private_children_but_public_listing_hides_them() {
        let (_home, host) = test_host();
        let default_runtime = host.default_runtime().await.unwrap();

        let child = AgentIdentityRecord::new(
            "child_test",
            AgentKind::Child,
            AgentVisibility::Private,
            AgentOwnership::ParentSupervised,
            AgentProfilePreset::PrivateChild,
            Some(host.config().default_agent_id.clone()),
            Some("task-1".into()),
        );
        host.append_agent_identity(&child).unwrap();
        host.runtime_db().agent_identities().upsert(&child).unwrap();

        let child_storage = host.agent_storage("child_test").unwrap();
        let mut child_state = AgentState::new("child_test");
        child_state.status = AgentStatus::AwakeRunning;
        child_state.pending = 1;
        child_state.current_run_id = Some("run-1".into());
        child_storage.write_agent_for_fixture(&child_state).unwrap();
        child_storage
            .append_task(&TaskRecord {
                id: "task-1".into(),
                agent_id: "child_test".into(),
                kind: crate::types::TaskKind::CommandTask,
                status: TaskStatus::Running,
                created_at: chrono::Utc::now(),
                updated_at: chrono::Utc::now(),
                parent_message_id: None,
                work_item_id: None,
                summary: Some("child task".into()),
                detail: Some(serde_json::json!({ "wait_policy": "background" })),
                recovery: None,
            })
            .unwrap();

        let summary = default_runtime.agent_summary().await.unwrap();
        assert_eq!(summary.identity.kind, AgentKind::Default);
        assert_eq!(summary.active_children.len(), 1);
        assert_eq!(summary.active_children[0].identity.agent_id, "child_test");
        assert_eq!(summary.active_children[0].identity.kind, AgentKind::Child);
        assert_eq!(
            summary.active_children[0].identity.visibility,
            AgentVisibility::Private
        );
        assert_eq!(
            summary.active_children[0].observability.phase,
            crate::types::ChildAgentPhase::Running
        );
        {
            let registry = host.inner.runtimes.read().await;
            assert!(
                !registry.agents.contains_key("child_test"),
                "child summary inspection should not start the child runtime"
            );
        }

        let listed = host
            .list_agents()
            .await
            .unwrap()
            .into_iter()
            .map(|summary| summary.identity.agent_id.clone())
            .collect::<Vec<_>>();
        assert!(listed.contains(&host.config().default_agent_id));
        assert!(!listed.contains(&"child_test".to_string()));
    }

    #[tokio::test]
    async fn host_bootstrap_keeps_interrupted_supervised_child_active() {
        let (_home, host) = test_host();
        let config = host.config().as_ref().clone();
        let parent_agent_id = config.default_agent_id.clone();
        let original_parent = host.default_runtime().await.unwrap();
        crate::runtime::tests::support::persist_task_transition(
            &original_parent,
            &TaskRecord {
                id: "task-1".into(),
                agent_id: parent_agent_id.clone(),
                kind: crate::types::TaskKind::SubagentTask,
                status: TaskStatus::Interrupted,
                created_at: chrono::Utc::now(),
                updated_at: chrono::Utc::now(),
                parent_message_id: None,
                work_item_id: None,
                summary: Some("delegated child".into()),
                detail: Some(serde_json::json!({
                    "child_agent_id": "child_test",
                    "task_status": "interrupted",
                })),
                recovery: None,
            },
            "interrupted_child_original_task_fixture",
        )
        .await
        .unwrap();

        let child = AgentIdentityRecord::new(
            "child_test",
            AgentKind::Child,
            AgentVisibility::Private,
            AgentOwnership::ParentSupervised,
            AgentProfilePreset::PrivateChild,
            Some(parent_agent_id.clone()),
            Some("task-1".into()),
        );
        host.append_agent_identity(&child).unwrap();
        host.runtime_db().agent_identities().upsert(&child).unwrap();

        let child_storage = host.agent_storage("child_test").unwrap();
        let mut child_state = AgentState::new("child_test");
        child_state.status = AgentStatus::AwaitingTask;
        child_storage.write_agent_for_fixture(&child_state).unwrap();
        child_storage
            .append_task(&TaskRecord {
                id: "child-task-1".into(),
                agent_id: "child_test".into(),
                kind: crate::types::TaskKind::CommandTask,
                status: TaskStatus::Running,
                created_at: chrono::Utc::now(),
                updated_at: chrono::Utc::now(),
                parent_message_id: None,
                work_item_id: None,
                summary: Some("child task".into()),
                detail: Some(serde_json::json!({ "wait_policy": "blocking" })),
                recovery: None,
            })
            .unwrap();

        assert!(
            !host
                .inner
                .runtimes
                .read()
                .await
                .agents
                .contains_key("child_test"),
            "the original child remains a cold inspection fixture"
        );
        drop(original_parent);
        host.shutdown().await.unwrap();
        drop(host);

        let restarted =
            RuntimeHost::new_with_provider(config, Arc::new(StubProvider::new("done"))).unwrap();
        let runtime = restarted.default_runtime().await.unwrap();
        let identity = restarted
            .agent_identity_record("child_test")
            .unwrap()
            .expect("child identity should remain present");
        assert_eq!(identity.status, AgentRegistryStatus::Active);
        assert!(restarted.agent_data_dir("child_test").exists());
        let snapshot = runtime.task_status_snapshot("task-1").await.unwrap();
        assert_eq!(snapshot.status, TaskStatus::Interrupted);
        assert_eq!(snapshot.child_agent_id.as_deref(), Some("child_test"));
        assert!(snapshot.child_observability.is_some());
        let summary = runtime.agent_summary().await.unwrap();
        assert_eq!(summary.active_children.len(), 1);
        assert_eq!(summary.active_children[0].identity.agent_id, "child_test");
    }

    fn seed_supervised_child_terminal(host: &RuntimeHost, task_id: &str, child_id: &str) {
        use crate::domain::execution_protocol::*;
        let identity = host.agent_identity_record(child_id).unwrap().unwrap();
        let relations = crate::runtime_db::agent_relations::supervised_creation_records(
            &identity,
            identity.parent_agent_id.as_deref().unwrap(),
            task_id,
            None,
        );
        host.runtime_db()
            .transaction(|tx| {
                crate::runtime_db::agent_relations::upsert_canonical_record_set_tx(tx, &relations)
            })
            .unwrap();
        let storage = host.agent_storage(child_id).unwrap();
        let state = storage.read_agent().unwrap().unwrap();
        let terminal = state.last_turn_terminal.as_ref().unwrap();
        let mut source = crate::types::MessageEnvelope::new(
            child_id,
            crate::types::MessageKind::InternalFollowup,
            crate::types::MessageOrigin::Task {
                task_id: task_id.into(),
            },
            AuthorityClass::OperatorInstruction,
            crate::types::Priority::Normal,
            crate::types::MessageBody::Text {
                text: "original delegated input".into(),
            },
        );
        source.turn_id = Some(terminal.turn_id.clone());
        source.metadata = Some(json!({
            "parent_agent_id": identity.parent_agent_id,
            "supervision_task_id": task_id,
            "child_agent_id": child_id,
            "parent_supervised": true,
        }));
        storage.append_message(&source).unwrap();
        let mut turn =
            crate::types::TurnRecord::new(child_id, &terminal.turn_id, terminal.turn_index);
        let mut summary = crate::types::TurnTerminalSummary::from_terminal(terminal);
        summary.reason = terminal.last_assistant_message.clone();
        turn.terminal = Some(summary);
        turn.input_message_ids = vec![source.id.clone()];
        host.runtime_db().turn_records().upsert(&turn).unwrap();
        let attempt_id = format!("activation:message:{}", source.id);
        let outcome_id = format!("outcome:{attempt_id}");
        let authority = host
            .runtime_db()
            .transitions()
            .load_execution_authority_fences(child_id)
            .unwrap();
        let attempt = ExecutionAttempt {
            input_projection: None,
            attempt_id: attempt_id.clone(),
            agent_id: child_id.into(),
            source_message_id: Some(source.id.clone()),
            source: ExecutionSource {
                identity: ExecutionSourceIdentity::InternalFollowup {
                    message_id: source.id,
                },
                generation: 1,
            },
            binding: ExecutionBinding::Conversation {
                interaction_id: terminal.turn_id.clone(),
            },
            provenance: ExecutionProvenance {
                origin: ExecutionOrigin::Task,
                trust: ExecutionTrust::OperatorInstruction,
                priority: ExecutionPriority::Normal,
                correlation_id: None,
                causation_id: None,
            },
            admitted_fences: AdmittedFences {
                source_revision: 1,
                work_item_source_revision: None,
                work_item_generation: None,
                rejoin: None,
                agent_control_revision: authority.agent_control_revision,
                host_registry_revision: authority.host_registry_revision,
            },
            state: ExecutionAttemptState::Settled,
            run_id: None,
            turn_id: Some(terminal.turn_id.clone()),
            recovery_of_attempt_id: None,
            terminal_outcome_id: Some(outcome_id.clone()),
            admitted_at: Utc::now().to_rfc3339(),
            terminal_at: Some(Utc::now().to_rfc3339()),
        };
        let mut execution = ExecutionProtocolState::empty(child_id);
        execution.attempts.insert(attempt_id.clone(), attempt);
        execution.outcomes.insert(
            outcome_id.clone(),
            ExecutionOutcomeRecord {
                outcome_id,
                attempt_id,
                outcome: ExecutionOutcome::Conversation(ConversationOutcome::Replied),
                created_at: Utc::now().to_rfc3339(),
            },
        );
        host.runtime_db()
            .transaction(|tx| crate::runtime_db::transitions::persist_state_tx(tx, &execution))
            .unwrap();
    }

