    #[tokio::test]
    async fn supervised_invocation_terminal_observability_excludes_later_activity() {
        let (_home, host, task) = source_bound_invocation_fixture();
        let child_id = "source-bound-child";
        let storage = host.agent_storage(child_id).unwrap();
        for (turn_id, kind, text) in [
            (
                "original-source-turn",
                crate::types::BriefKind::Ack,
                "original progress",
            ),
            ("later-turn", crate::types::BriefKind::Ack, "later progress"),
            (
                "later-turn",
                crate::types::BriefKind::Result,
                "later result",
            ),
        ] {
            let mut brief = crate::types::BriefRecord::new(child_id, kind, text, None, None);
            brief.turn_id = Some(turn_id.into());
            storage.append_brief(&brief).unwrap();
        }
        let mut state = storage.read_agent().unwrap().unwrap();
        state.turn_index = 2;
        state.last_turn_terminal.as_mut().unwrap().turn_id = "later-turn".into();
        state
            .last_turn_terminal
            .as_mut()
            .unwrap()
            .last_assistant_message = Some("later result".into());
        state
            .working_memory
            .current_working_memory
            .current_work_item_id = Some("later-work-item".into());
        state.working_memory.current_working_memory.work_summary = Some("later work".into());
        storage.write_agent_for_fixture(&state).unwrap();

        assert!(host.try_get_loaded_runtime(child_id).await.is_none());
        let ChildInvocationResolution::Ready(result) = host
            .resolve_supervised_invocation(&task, child_id, false)
            .await
            .unwrap()
        else {
            panic!("original invocation should be terminal");
        };
        let snapshot: crate::types::ChildAgentObservabilitySnapshot =
            serde_json::from_value(result.task_detail.unwrap()["child_observability"].clone())
                .unwrap();
        assert_eq!(snapshot.phase, crate::types::ChildAgentPhase::Terminal);
        assert_eq!(snapshot.current_work_item_id, None);
        assert_eq!(snapshot.work_summary, None);
        assert_eq!(
            snapshot.last_progress_brief.as_deref(),
            Some("original progress")
        );
        assert_eq!(
            snapshot.last_result_brief.as_deref(),
            Some("original-source-result")
        );
        assert!(host.try_get_loaded_runtime(child_id).await.is_none());
    }

    struct SaturatedRuntimeReaders {
        release: Vec<std::sync::mpsc::Sender<()>>,
        workers: Vec<std::thread::JoinHandle<()>>,
    }

    impl Drop for SaturatedRuntimeReaders {
        fn drop(&mut self) {
            for release in self.release.drain(..) {
                let _ = release.send(());
            }
            for worker in self.workers.drain(..) {
                let _ = worker.join();
            }
        }
    }

    fn saturate_runtime_readers(host: &RuntimeHost) -> SaturatedRuntimeReaders {
        let mut held = SaturatedRuntimeReaders {
            release: Vec::new(),
            workers: Vec::new(),
        };
        let (ready, acquired) = std::sync::mpsc::channel();
        for _ in 0..4 {
            let db = host.runtime_db().clone();
            let ready = ready.clone();
            let (release, released) = std::sync::mpsc::channel();
            held.release.push(release);
            held.workers.push(std::thread::spawn(move || {
                db.with_read(|_| {
                    ready.send(()).unwrap();
                    let _ = released.recv();
                    Ok(())
                })
                .unwrap();
            }));
        }
        for _ in 0..4 {
            acquired.recv_timeout(Duration::from_secs(5)).unwrap();
        }
        held
    }

    #[tokio::test]
    async fn runtime_constructor_cancellation_retains_activation_guards() {
        let (_home, host, _task) = source_bound_invocation_fixture();
        let (started, constructed) = tokio::sync::oneshot::channel();
        let (release, released) = std::sync::mpsc::channel();
        *host.inner.runtime_constructor_gate.lock().unwrap() = Some((started, released));
        let activation_host = host.clone();
        let activation = tokio::spawn(async move {
            activation_host
                .get_or_create_agent("source-bound-child")
                .await
        });
        assert_eq!(
            tokio::time::timeout(Duration::from_secs(3), constructed)
                .await
                .unwrap()
                .unwrap(),
            "source-bound-child"
        );
        activation.abort();
        assert!(activation.await.err().unwrap().is_cancelled());
        assert!(host.inner.bootstrap_handoff_lock.try_lock().is_err());
        assert!(host.inner.runtimes.try_write().is_err());
        let next_host = host.clone();
        let next =
            tokio::spawn(async move { next_host.get_or_create_agent("source-bound-child").await });
        tokio::time::sleep(Duration::from_millis(20)).await;
        assert!(!next.is_finished());
        release.send(()).unwrap();
        tokio::time::timeout(Duration::from_secs(3), next)
            .await
            .unwrap()
            .unwrap()
            .unwrap();
        {
            let registry = host.inner.runtimes.read().await;
            assert!(registry.agents.contains_key("source-bound-child"));
            assert_eq!(
                registry.next_generation, 2,
                "must not construct a second runtime"
            );
        }
        host.shutdown().await.unwrap();
    }

