    #[tokio::test]
    async fn invocation_and_message_monitors_retry_saturated_readers() {
        let (_home, host, task) = source_bound_invocation_fixture();
        let held = saturate_runtime_readers(&host);
        let read_host = host.clone();
        let invocation = tokio::spawn(async move {
            read_host
                .await_invocation_delivery_terminal_result(
                    "source-bound-child",
                    "missing-delivery",
                    &task.id,
                    false,
                )
                .await
        });
        let read_host = host.clone();
        let parent = host.config().default_agent_id.clone();
        let message = tokio::spawn(async move {
            read_host
                .await_agent_message(&parent, "unrelated-sender", 0, None, None)
                .await
        });
        tokio::time::sleep(Duration::from_millis(600)).await;
        let invocation_pending = !invocation.is_finished();
        let message_pending = !message.is_finished();
        drop(held);
        let result = tokio::time::timeout(Duration::from_secs(3), invocation)
            .await
            .unwrap()
            .unwrap()
            .unwrap();
        message.abort();
        let _ = message.await;
        assert!(invocation_pending && message_pending);
        // Only the successful ledger read, not saturation, may report missing delivery.
        assert_eq!(result.status, TaskStatus::Failed);
        assert!(result.text.contains("missing from the durable ledger"));
    }

    #[tokio::test]
    async fn supervised_invocation_resolution_is_source_bound_and_fail_closed() {
        use crate::domain::execution_protocol::*;
        let (_home, host, task) = source_bound_invocation_fixture();
        let child_id = "source-bound-child";
        let execution = host
            .runtime_db()
            .transitions()
            .load_execution_protocol_state_if_initialized(child_id)
            .unwrap()
            .unwrap();
        let root = execution.attempts.values().next().unwrap().clone();
        let outcome_id = root.terminal_outcome_id.clone().unwrap();
        let store = |execution: &ExecutionProtocolState| {
            host.runtime_db()
                .transaction(|tx| {
                    // Independent adversarial fixtures, not legal runtime rewinds.
                    for table in [
                        "execution_protocol_outcomes",
                        "execution_protocol_attempts",
                        "execution_protocol_work_items",
                    ] {
                        tx.execute(
                            &format!("DELETE FROM {table} WHERE agent_id = ?1"),
                            [child_id],
                        )?;
                    }
                    crate::runtime_db::transitions::persist_state_tx(tx, execution)
                })
                .unwrap()
        };
        // Missing legacy baseline/linkage is recoverable from unique authoritative input.
        let resolved = host
            .resolve_supervised_invocation(&task, child_id, false)
            .await
            .unwrap();
        assert!(
            matches!(&resolved, ChildInvocationResolution::Ready(result) if result.text == "original-source-result"),
            "{resolved:?}"
        );
        let mut bad = task.clone();
        bad.detail.as_mut().unwrap()["target"]["incarnation"] = json!(2);
        assert!(matches!(
            host.resolve_supervised_invocation(&bad, child_id, false)
                .await
                .unwrap(),
            ChildInvocationResolution::RecoveryBlocked(ChildInvocationReason::IdentityMismatch)
        ));
        bad = task.clone();
        bad.detail.as_mut().unwrap()["child_turn_baseline"] = json!(1);
        assert!(matches!(
            host.resolve_supervised_invocation(&bad, child_id, false)
                .await
                .unwrap(),
            ChildInvocationResolution::RecoveryBlocked(ChildInvocationReason::SourceMismatch)
        ));
        bad = task.clone();
        bad.detail.as_mut().unwrap()["source_message_id"] = json!("missing-source");
        assert!(matches!(
            host.resolve_supervised_invocation(&bad, child_id, false)
                .await
                .unwrap(),
            ChildInvocationResolution::RecoveryBlocked(
                ChildInvocationReason::MissingInvocationBinding
            )
        ));

        let mut changed = execution.clone();
        let pending = changed.attempts.get_mut(&root.attempt_id).unwrap();
        pending.state = ExecutionAttemptState::Open;
        pending.terminal_outcome_id = None;
        pending.terminal_at = None;
        changed.outcomes.clear();
        store(&changed);
        assert!(matches!(
            host.resolve_supervised_invocation(&task, child_id, false)
                .await
                .unwrap(),
            ChildInvocationResolution::Pending(ChildInvocationReason::AwaitingContinuation)
        ));
        store(&execution);
        let original_turn = host
            .runtime_db()
            .turn_records()
            .by_id(Some(child_id), root.turn_id.as_deref().unwrap())
            .unwrap()
            .unwrap();
        host.runtime_db()
            .transaction(|tx| {
                tx.execute(
                    "DELETE FROM turn_records WHERE agent_id = ?1 AND turn_id = ?2",
                    rusqlite::params![child_id, original_turn.turn_id],
                )?;
                Ok(())
            })
            .unwrap();
        assert!(matches!(
            host.resolve_supervised_invocation(&task, child_id, false)
                .await
                .unwrap(),
            ChildInvocationResolution::RecoveryBlocked(
                ChildInvocationReason::MissingCanonicalTerminal
            )
        ));
        host.runtime_db()
            .turn_records()
            .upsert(&original_turn)
            .unwrap();
        host.agent_storage(child_id).unwrap().append_event(&crate::types::AuditEvent::legacy(
            "runtime_error",
            json!({"turn_id":"unrelated-historical-turn","message":"unrelated historical failure"}),
        )).unwrap();
        assert!(matches!(
            host.resolve_supervised_invocation(&task, child_id, false).await.unwrap(),
            ChildInvocationResolution::Ready(result) if result.status == TaskStatus::Completed
                && result.text == "original-source-result"
        ));
        for (kind, expected) in [
            (
                crate::types::TurnTerminalKind::Aborted,
                Some(TaskStatus::Cancelled),
            ),
            (crate::types::TurnTerminalKind::DeferredToFallback, None),
            (
                crate::types::TurnTerminalKind::ProviderFailedNeedsRecovery,
                None,
            ),
        ] {
            let mut turn = original_turn.clone();
            turn.terminal.as_mut().unwrap().kind = kind;
            host.runtime_db()
                .transaction(|tx| {
                    tx.execute(
                        "DELETE FROM turn_records WHERE agent_id = ?1 AND turn_id = ?2",
                        rusqlite::params![child_id, turn.turn_id],
                    )?;
                    Ok(())
                })
                .unwrap();
            host.runtime_db().turn_records().upsert(&turn).unwrap();
            let resolved = host
                .resolve_supervised_invocation(&task, child_id, false)
                .await
                .unwrap();
            match expected {
                Some(expected) => assert!(matches!(
                    resolved, ChildInvocationResolution::Ready(result) if result.status == expected
                        && !result.text.contains("unrelated historical failure")
                )),
                None => assert!(matches!(resolved, ChildInvocationResolution::Pending(_))),
            }
        }
        host.runtime_db()
            .transaction(|tx| {
                tx.execute(
                    "DELETE FROM turn_records WHERE agent_id = ?1 AND turn_id = ?2",
                    rusqlite::params![child_id, original_turn.turn_id],
                )?;
                Ok(())
            })
            .unwrap();
        host.runtime_db()
            .turn_records()
            .upsert(&original_turn)
            .unwrap();
        changed = execution.clone();
        let mut duplicate = root.clone();
        duplicate.attempt_id = "duplicate-root".into();
        duplicate.terminal_outcome_id = Some("duplicate-outcome".into());
        let mut duplicate_outcome = execution.outcomes[&outcome_id].clone();
        duplicate_outcome.outcome_id = "duplicate-outcome".into();
        duplicate_outcome.attempt_id = duplicate.attempt_id.clone();
        changed
            .outcomes
            .insert(duplicate_outcome.outcome_id.clone(), duplicate_outcome);
        changed
            .attempts
            .insert(duplicate.attempt_id.clone(), duplicate);
        store(&changed);
        assert!(matches!(
            host.resolve_supervised_invocation(&task, child_id, false)
                .await
                .unwrap(),
            ChildInvocationResolution::RecoveryBlocked(
                ChildInvocationReason::AmbiguousInvocationBinding
            )
        ));

        changed = execution.clone();
        changed.attempts.get_mut(&root.attempt_id).unwrap().state =
            ExecutionAttemptState::Interrupted;
        store(&changed);
        let storage = host.agent_storage(child_id).unwrap();
        let source_id = root.source_message_id.as_deref().unwrap();
        let mut queue = crate::types::QueueEntryRecord {
            message_id: source_id.into(),
            agent_id: child_id.into(),
            priority: crate::types::Priority::Normal,
            status: QueueEntryStatus::Interrupted,
            created_at: Utc::now(),
            updated_at: Utc::now(),
        };
        storage.append_queue_entry(&queue).unwrap();
        let mut unrelated = queue.clone();
        unrelated.message_id = "other-failed-source".into();
        unrelated.status = QueueEntryStatus::Aborted;
        storage.append_queue_entry(&unrelated).unwrap();
        assert!(matches!(
            host.resolve_supervised_invocation(&task, child_id, false)
                .await
                .unwrap(),
            ChildInvocationResolution::Pending(ChildInvocationReason::AwaitingContinuation)
        ));
        let mut failure = crate::types::BriefRecord::new(
            child_id,
            crate::types::BriefKind::Failure,
            "original source failed",
            Some(source_id.into()),
            None,
        );
        failure.turn_id = root.turn_id.clone();
        storage.append_brief(&failure).unwrap();
        for status in [QueueEntryStatus::Aborted, QueueEntryStatus::Quarantined] {
            // Independent terminal fixtures, not an aborted -> quarantined transition.
            host.runtime_db()
                .transaction(|tx| {
                    tx.execute(
                        "DELETE FROM queue_entries WHERE message_id = ?1",
                        [source_id],
                    )?;
                    Ok(())
                })
                .unwrap();
            queue.status = status;
            storage.append_queue_entry(&queue).unwrap();
            assert!(matches!(
                host.resolve_supervised_invocation(&task, child_id, false).await.unwrap(),
                ChildInvocationResolution::Ready(result)
                    if result.status == TaskStatus::Failed && result.text == "original source failed"
            ));
        }
        for suffix in ["a", "b"] {
            let mut recovery = root.clone();
            recovery.attempt_id = format!("recovery-{suffix}");
            recovery.recovery_of_attempt_id = Some(root.attempt_id.clone());
            recovery.terminal_outcome_id = Some(format!("outcome-recovery-{suffix}"));
            let mut recovered_outcome = execution.outcomes[&outcome_id].clone();
            recovered_outcome.outcome_id = recovery.terminal_outcome_id.clone().unwrap();
            recovered_outcome.attempt_id = recovery.attempt_id.clone();
            changed
                .outcomes
                .insert(recovered_outcome.outcome_id.clone(), recovered_outcome);
            changed
                .attempts
                .insert(recovery.attempt_id.clone(), recovery);
            if suffix == "a" {
                store(&changed);
                assert!(matches!(
                    host.resolve_supervised_invocation(&task, child_id, false).await.unwrap(),
                    ChildInvocationResolution::Ready(result)
                    if result.text == "original-source-result"
                        && result.task_detail.as_ref().unwrap()["activation_id"] == "recovery-a"
                ));
            }
        }
        store(&changed);
        assert!(matches!(
            host.resolve_supervised_invocation(&task, child_id, false)
                .await
                .unwrap(),
            ChildInvocationResolution::RecoveryBlocked(
                ChildInvocationReason::AmbiguousContinuation
            )
        ));
        changed = execution.clone();
        changed.outcomes.get_mut(&outcome_id).unwrap().outcome =
            ExecutionOutcome::Conversation(ConversationOutcome::HandoffToWorkItemContinue {
                work_item_id: "cyclic-work".into(),
            });
        changed.work_items.insert(
            "cyclic-work".into(),
            WorkItemExecutionRecord {
                source_revision: 1,
                state: WorkItemExecutionState::Waiting {
                    generation: 1,
                    wait: WaitReference {
                        wait_id: "cycle-wait".into(),
                    },
                },
            },
        );
        store(&changed);
        assert!(matches!(
            host.resolve_supervised_invocation(&task, child_id, false)
                .await
                .unwrap(),
            ChildInvocationResolution::Pending(ChildInvocationReason::AwaitingContinuation)
        ));
        let waiting = changed.work_items["cyclic-work"].state.clone();
        for state in [
            WorkItemExecutionState::Runnable {
                generation: 2,
                recovery_ref: None,
            },
            WorkItemExecutionState::Paused {
                generation: 2,
                reason: "yielded_to:other-work".into(),
            },
        ] {
            changed.work_items.get_mut("cyclic-work").unwrap().state = state;
            store(&changed);
            assert!(matches!(
                host.resolve_supervised_invocation(&task, child_id, false)
                    .await
                    .unwrap(),
                ChildInvocationResolution::Pending(ChildInvocationReason::AwaitingContinuation)
            ));
        }
        changed.work_items.get_mut("cyclic-work").unwrap().state = waiting;
        let mut next = root.clone();
        next.attempt_id = "cycle-successor".into();
        next.binding = ExecutionBinding::WorkItem {
            work_item_id: "cyclic-work".into(),
        };
        next.source.identity = ExecutionSourceIdentity::TriggeredWait {
            wait_id: "cycle-wait".into(),
            trigger_message_id: "cycle-trigger".into(),
            ingress: None,
        };
        next.terminal_outcome_id = Some("cycle-outcome".into());
        changed.outcomes.insert(
            "cycle-outcome".into(),
            ExecutionOutcomeRecord {
                outcome_id: "cycle-outcome".into(),
                attempt_id: next.attempt_id.clone(),
                outcome: ExecutionOutcome::WorkItem(WorkItemOutcome::Continue),
                created_at: Utc::now().to_rfc3339(),
            },
        );
        changed.attempts.insert(next.attempt_id.clone(), next);
        store(&changed);
        assert!(matches!(
            host.resolve_supervised_invocation(&task, child_id, false)
                .await
                .unwrap(),
            ChildInvocationResolution::RecoveryBlocked(ChildInvocationReason::CyclicContinuation)
        ));
        changed = execution.clone();
        changed.outcomes.get_mut(&outcome_id).unwrap().outcome =
            ExecutionOutcome::Conversation(ConversationOutcome::Interrupted {
                reason: "exact-source-stop".into(),
            });
        store(&changed);
        assert!(
            matches!(host.resolve_supervised_invocation(&task, child_id, false).await.unwrap(),
            ChildInvocationResolution::Ready(result) if result.status == TaskStatus::Interrupted)
        );
        store(&execution);
        let source_id = root.source_message_id.unwrap();
        let mut source = host
            .runtime_db()
            .messages()
            .by_id(Some(child_id), &source_id)
            .unwrap()
            .unwrap();
        source.id = "another-task-origin-input".into();
        host.agent_storage(child_id)
            .unwrap()
            .append_message(&source)
            .unwrap();
        assert!(matches!(
            host.resolve_supervised_invocation(&task, child_id, false)
                .await
                .unwrap(),
            ChildInvocationResolution::RecoveryBlocked(
                ChildInvocationReason::AmbiguousInvocationBinding
            )
        ));
        bad = task.clone();
        bad.detail.as_mut().unwrap()["source_message_id"] = json!(source_id);
        assert!(matches!(
            host.resolve_supervised_invocation(&bad, child_id, false)
                .await
                .unwrap(),
            ChildInvocationResolution::Ready(_)
        ));
    }

    #[tokio::test]
    async fn supervised_invocation_inline_consumption_requires_exact_settled_delivery() {
        use crate::runtime_db::task_result_settlement::TaskResultSettlementDisposition;
        use crate::types::{IdleInputBatchItem, LiveInputBatchRecord, LiveInputSafePoint};

        for disposition in [
            TaskResultSettlementDisposition::ModelDelivered,
            TaskResultSettlementDisposition::ReplyConsumedElsewhere,
            TaskResultSettlementDisposition::OwnerClosed,
            TaskResultSettlementDisposition::OwnerMissing,
            TaskResultSettlementDisposition::InvalidOrStale,
            TaskResultSettlementDisposition::InterruptedReplaySourceFinal,
        ] {
            let (_home, host, invocation) = source_bound_invocation_fixture();
            let child_id = "source-bound-child";
            let storage = host.agent_storage(child_id).unwrap();
            let mut turn = storage
                .read_turn_by_id("original-source-turn")
                .unwrap()
                .unwrap();
            let execution = host
                .runtime_db()
                .transitions()
                .load_execution_protocol_state_if_initialized(child_id)
                .unwrap()
                .unwrap();
            let activation_id = &execution.attempts.values().next().unwrap().attempt_id;
            let message = MessageEnvelope::new(
                child_id,
                MessageKind::TaskResult,
                MessageOrigin::Task {
                    task_id: "nested-command".into(),
                },
                AuthorityClass::RuntimeInstruction,
                Priority::Normal,
                MessageBody::Text {
                    text: "nested result".into(),
                },
            );
            let nested = TaskRecord {
                id: "nested-command".into(),
                agent_id: child_id.into(),
                kind: TaskKind::CommandTask,
                status: TaskStatus::Completed,
                created_at: Utc::now(),
                updated_at: Utc::now(),
                parent_message_id: Some(message.id.clone()),
                work_item_id: None,
                summary: None,
                detail: Some(json!({
                    "parent_turn_id": turn.turn_id,
                    "rejoin_obligation_id": "nested-command",
                    "rejoin_generation": 1
                })),
                recovery: None,
            };
            storage.append_task(&nested).unwrap();
            storage.append_message(&message).unwrap();
            let settlements = host.runtime_db().task_result_settlements();
            let record = settlements
                .ensure_pending(&nested, &message, Utc::now())
                .unwrap()
                .unwrap();
            turn.live_input_batches.push(LiveInputBatchRecord {
                activation_id: activation_id.clone(),
                safe_point: LiveInputSafePoint::new(activation_id, 1),
                cutoff: Utc::now(),
                max_items: 1,
                max_bytes: 1024,
                rendered_bytes: 0,
                result_identities: vec![record.result_identity],
                ordinary_message_ids: Vec::new(),
                items: vec![IdleInputBatchItem {
                    message_id: message.id.clone(),
                    source_ref: format!("message:{}", message.id),
                    rendered: "nested result".into(),
                }],
            });
            host.runtime_db().turn_records().upsert(&turn).unwrap();
            // Both a terminal task and an attachment are insufficient until
            // the canonical delivery actually settles for this execution.
            for admitted in [false, true] {
                if admitted {
                    settlements
                        .admit_message(child_id, &message.id, activation_id, Utc::now())
                        .unwrap()
                        .unwrap();
                }
                assert!(matches!(
                    host.resolve_supervised_invocation(&invocation, child_id, false)
                        .await
                        .unwrap(),
                    ChildInvocationResolution::Pending(ChildInvocationReason::AwaitingContinuation)
                ));
            }
            assert_eq!(
                settlements
                    .settle_activation(child_id, activation_id, disposition, Utc::now())
                    .unwrap(),
                1
            );
            let resolution = host
                .resolve_supervised_invocation(&invocation, child_id, false)
                .await
                .unwrap();
            if disposition != TaskResultSettlementDisposition::ModelDelivered {
                assert!(matches!(
                    resolution,
                    ChildInvocationResolution::Pending(ChildInvocationReason::AwaitingContinuation)
                ));
                continue;
            }
            assert!(matches!(
                resolution,
                ChildInvocationResolution::Ready(result) if result.text == "original-source-result"
            ));
            let rebound_activation = "recovered-activation";
            let mut rebound_turn = turn.clone();
            rebound_turn.live_input_batches[0].activation_id = rebound_activation.into();
            for candidate_turn in [&turn, &rebound_turn] {
                assert!(
                    !host
                        .invocation_task_result_consumed_in_turn(
                            &nested,
                            Some(candidate_turn),
                            rebound_activation,
                            host.runtime_db()
                                .task_result_settlements()
                                .latest_for_message(nested.parent_message_id.as_deref().unwrap())
                                .unwrap()
                                .as_ref(),
                        )
                        .unwrap(),
                    "an old settlement cannot prove delivery for a rebound activation"
                );
            }
            for mismatch in 0..10 {
                let mut changed_turn = turn.clone();
                let mut changed_task = nested.clone();
                match mismatch {
                    0 => changed_turn.live_input_batches.clear(),
                    1 => changed_turn.live_input_batches[0].activation_id = "unrelated".into(),
                    2 => changed_turn.live_input_batches[0].result_identities.clear(),
                    3 => {
                        changed_turn.live_input_batches[0].items[0].message_id = "unrelated".into()
                    }
                    4 => changed_task.work_item_id = Some("unrelated-owner".into()),
                    5 => changed_task.detail.as_mut().unwrap()["rejoin_generation"] = json!(2),
                    6 => changed_task.parent_message_id = Some("unrelated-result".into()),
                    7 => {
                        changed_task.detail.as_mut().unwrap()["parent_turn_id"] = json!("unrelated")
                    }
                    8 => changed_task.agent_id = "unrelated-agent".into(),
                    9 => changed_task.id = "unrelated-task".into(),
                    _ => unreachable!(),
                }
                if mismatch >= 4 {
                    // Terminal task ownership/fences are immutable; exercise
                    // rejection without attempting an illegal task transition.
                    assert!(
                        !host
                            .invocation_task_result_consumed_in_turn(
                                &changed_task,
                                Some(&turn),
                                activation_id,
                                host.runtime_db()
                                    .task_result_settlements()
                                    .latest_for_message(
                                        nested.parent_message_id.as_deref().unwrap()
                                    )
                                    .unwrap()
                                    .as_ref(),
                            )
                            .unwrap(),
                        "mismatch {mismatch} must not prove consumption"
                    );
                    continue;
                }
                host.runtime_db()
                    .turn_records()
                    .upsert(&changed_turn)
                    .unwrap();
                assert!(
                    matches!(
                        host.resolve_supervised_invocation(&invocation, child_id, false)
                            .await
                            .unwrap(),
                        ChildInvocationResolution::RecoveryBlocked(
                            ChildInvocationReason::MissingTaskResultContinuation
                        )
                    ),
                    "mismatch {mismatch} must expose missing consumption as repair evidence"
                );
            }
        }
    }

    #[tokio::test]
    async fn supervised_invocation_distinguishes_original_later_and_unknown_activity() {
        let (_home, host, task) = source_bound_invocation_fixture();
        let child_id = "source-bound-child";
        let storage = host.agent_storage(child_id).unwrap();
        let mut nested = TaskRecord {
            id: "nested-command".into(),
            agent_id: child_id.into(),
            kind: TaskKind::CommandTask,
            status: TaskStatus::Running,
            created_at: Utc::now(),
            updated_at: Utc::now(),
            parent_message_id: None,
            work_item_id: None,
            summary: None,
            detail: Some(json!({"parent_turn_id": "original-source-turn"})),
            recovery: None,
        };
        storage.append_task(&nested).unwrap();
        assert!(matches!(
            host.resolve_supervised_invocation(&task, child_id, false)
                .await
                .unwrap(),
            ChildInvocationResolution::Pending(ChildInvocationReason::AwaitingContinuation)
        ));
        // Known later activity must not suppress a proven original result.
        nested.detail = Some(json!({"parent_turn_id": "later-turn"}));
        storage.append_task(&nested).unwrap();
        assert!(matches!(
            host.resolve_supervised_invocation(&task, child_id, false).await.unwrap(),
            ChildInvocationResolution::Ready(result) if result.text == "original-source-result"
        ));
        nested.detail = None;
        storage.append_task(&nested).unwrap();
        assert!(matches!(
            host.resolve_supervised_invocation(&task, child_id, false)
                .await
                .unwrap(),
            ChildInvocationResolution::RecoveryBlocked(
                ChildInvocationReason::MissingInvocationBinding
            )
        ));
        nested.status = TaskStatus::Completed;
        storage.append_task(&nested).unwrap();
        let now = Utc::now();
        let mut wait = WaitConditionRecord {
            id: "nested-wait".into(),
            agent_id: child_id.into(),
            work_item_id: None,
            status: WaitConditionStatus::Active,
            kind: WaitConditionKind::Task,
            source: None,
            subject_ref: Some(nested.id.clone()),
            waiting_for: "nested result".into(),
            wake_sources: vec![WakeSource::TaskResult { task_id: nested.id }],
            continuation: None,
            created_at: now,
            updated_at: now,
            expires_at: None,
            resolved_at: None,
            cancelled_at: None,
            turn_id: Some("original-source-turn".into()),
            trigger_message_id: None,
            triggered_at: None,
        };
        storage.append_wait_condition(&wait).unwrap();
        assert!(matches!(
            host.resolve_supervised_invocation(&task, child_id, false)
                .await
                .unwrap(),
            ChildInvocationResolution::Pending(ChildInvocationReason::AwaitingContinuation)
        ));
        wait.status = WaitConditionStatus::Cancelled;
        wait.cancelled_at = Some(Utc::now());
        storage.append_wait_condition(&wait).unwrap();
        wait.id = "later-wait".into();
        wait.status = WaitConditionStatus::Active;
        wait.cancelled_at = None;
        wait.turn_id = Some("later-turn".into());
        storage.append_wait_condition(&wait).unwrap();
        assert!(matches!(
            host.resolve_supervised_invocation(&task, child_id, false).await.unwrap(),
            ChildInvocationResolution::Ready(result) if result.text == "original-source-result"
        ));
        wait.status = WaitConditionStatus::Cancelled;
        wait.cancelled_at = Some(Utc::now());
        storage.append_wait_condition(&wait).unwrap();
        wait.id = "unknown-wait".into();
        wait.status = WaitConditionStatus::Active;
        wait.cancelled_at = None;
        wait.turn_id = None;
        storage.append_wait_condition(&wait).unwrap();
        assert!(matches!(
            host.resolve_supervised_invocation(&task, child_id, false)
                .await
                .unwrap(),
            ChildInvocationResolution::RecoveryBlocked(
                ChildInvocationReason::MissingInvocationBinding
            )
        ));
    }

    #[tokio::test]
    async fn supervised_invocation_diagnostic_retries_after_storage_recovers() {
        let (_home, host, mut task) = source_bound_invocation_fixture();
        let parent = host.default_runtime().await.unwrap();
        task.detail.as_mut().unwrap()["source_message_id"] = json!("missing-source");
        task.recovery = Some(TaskRecoverySpec::ChildAgentTask {
            summary: "reattach without replay".into(),
            prompt: "must never be replayed".into(),
            authority_class: AuthorityClass::OperatorInstruction,
            workspace_mode: ChildAgentWorkspaceMode::Inherit,
            lifecycle_disposition: crate::types::AgentLifecycleDisposition::Retain,
        });
        parent.storage().append_task(&task).unwrap();
        // Fail only diagnostic writes, not the preceding Running projection.
        host.runtime_db()
            .connection()
            .unwrap()
            .execute_batch(
                "CREATE TRIGGER reject_recovery_diagnostic BEFORE INSERT ON tasks
             WHEN NEW.task_id = 'task-source-bound'
               AND json_extract(NEW.payload_json, '$.detail.recovery_diagnostic') IS NOT NULL
             BEGIN SELECT RAISE(ABORT, 'diagnostic storage unavailable'); END;",
            )
            .unwrap();
        parent
            .recover_supervised_child_tasks(vec![task.clone()])
            .await
            .unwrap();
        tokio::time::sleep(Duration::from_millis(1200)).await;
        let blocked = parent
            .storage()
            .latest_task_record(&task.id)
            .unwrap()
            .unwrap();
        assert_eq!(blocked.status, TaskStatus::Running);
        assert!(blocked.detail.unwrap().get("recovery_diagnostic").is_none());
        host.runtime_db()
            .connection()
            .unwrap()
            .execute_batch("DROP TRIGGER reject_recovery_diagnostic;")
            .unwrap();
        let diagnostic = tokio::time::timeout(Duration::from_secs(5), async {
            loop {
                let current = parent
                    .storage()
                    .latest_task_record(&task.id)
                    .unwrap()
                    .unwrap();
                if let Some(diagnostic) = current
                    .detail
                    .as_ref()
                    .and_then(|detail| detail.get("recovery_diagnostic"))
                {
                    break diagnostic.clone();
                }
                tokio::time::sleep(Duration::from_millis(20)).await;
            }
        })
        .await
        .expect("unchanged diagnostic must retry after storage recovery");
        assert_eq!(diagnostic["reason"], "missing_invocation_binding");
        assert_eq!(diagnostic["state"], "recovery_blocked");
        // Persisted diagnostics are deduplicated across subsequent polls.
        let persisted = parent.storage().latest_task_record(&task.id).unwrap();
        tokio::time::sleep(Duration::from_millis(1200)).await;
        assert_eq!(
            parent.storage().latest_task_record(&task.id).unwrap(),
            persisted
        );
        host.shutdown().await.unwrap();
    }

    #[tokio::test]
    async fn supervised_invocation_monitor_retains_responsibility_after_commit_retry_exhaustion() {
        let (_home, host, mut task) = source_bound_invocation_fixture();
        let parent = host.default_runtime().await.unwrap();
        task.recovery = Some(TaskRecoverySpec::ChildAgentTask {
            summary: "retry original terminal publication".into(),
            prompt: "must never be replayed".into(),
            authority_class: AuthorityClass::OperatorInstruction,
            workspace_mode: ChildAgentWorkspaceMode::Inherit,
            lifecycle_disposition: crate::types::AgentLifecycleDisposition::Retain,
        });
        parent.storage().append_task(&task).unwrap();
        let resolved = host
            .resolve_supervised_invocation(&task, "source-bound-child", false)
            .await
            .unwrap();
        assert!(
            matches!(resolved, ChildInvocationResolution::Ready(_)),
            "{resolved:?}"
        );
        parent.inject_terminal_task_transition_conflicts(3);
        let (reattached, remaining) = parent
            .recover_supervised_child_tasks(vec![task.clone()])
            .await
            .unwrap();
        assert_eq!(reattached.len(), 1);
        assert!(remaining.is_empty());
        let diagnostic = tokio::time::timeout(Duration::from_secs(2), async {
            loop {
                let current = parent
                    .storage()
                    .latest_task_record(&task.id)
                    .unwrap()
                    .unwrap();
                if let Some(diagnostic) = current
                    .detail
                    .as_ref()
                    .and_then(|detail| detail.get("recovery_diagnostic"))
                    .filter(|diagnostic| diagnostic["stage"] == "commit")
                {
                    assert!(!matches!(
                        current.status,
                        TaskStatus::Completed | TaskStatus::Failed
                    ));
                    break diagnostic.clone();
                }
                tokio::time::sleep(Duration::from_millis(20)).await;
            }
        })
        .await
        .unwrap_or_else(|error| {
            panic!(
                "exhaustion diagnostic missing: {error}; task={:?}",
                parent.storage().latest_task_record(&task.id).unwrap()
            )
        });
        assert_eq!(diagnostic["reason"], "monitor_commit_failed");
        assert_eq!(diagnostic["state"], "recovery_blocked");
        assert_eq!(diagnostic["supervision_task_id"], task.id);
        assert_eq!(diagnostic["parent_agent_id"], task.agent_id);
        assert_eq!(diagnostic["child_agent_id"], "source-bound-child");
        let roots = diagnostic["canonical_observation"]["steps"]
            .as_array()
            .unwrap();
        assert_eq!(roots.len(), 1);
        assert_eq!(roots[0]["turn_id"], "original-source-turn");
        assert_eq!(roots[0]["outcome_kind"], "replied");
        assert!(!diagnostic.to_string().contains("original-source-result"));
        // A second recovery must not replace the effective monitor.
        parent
            .recover_supervised_child_tasks(vec![task.clone(), task.clone()])
            .await
            .unwrap();
        let terminal = wait_for_terminal_task(&parent, &task.id).await;
        assert_eq!(terminal.status, TaskStatus::Completed);
        assert_eq!(
            terminal.parent_message_id.as_deref(),
            Some(format!("message:child-invocation-result:{}", task.id).as_str())
        );
        assert!(terminal
            .detail
            .as_ref()
            .unwrap()
            .get("recovery_diagnostic")
            .is_none());
        let results = host.runtime_db().messages().all(Some(&task.agent_id)).unwrap().into_iter()
            .filter(|message| message.kind == crate::types::MessageKind::TaskResult
                && matches!(&message.origin, crate::types::MessageOrigin::Task { task_id } if task_id == &task.id))
            .collect::<Vec<_>>();
        assert_eq!(results.len(), 1);
        assert!(
            matches!(&results[0].body, crate::types::MessageBody::Text { text } if text == "original-source-result")
        );
        assert_eq!(
            host.agent_identity_record("source-bound-child")
                .unwrap()
                .unwrap()
                .status,
            AgentRegistryStatus::Active
        );
        host.shutdown().await.unwrap();
    }

    #[tokio::test]
    async fn recovered_runtime_reattaches_supervised_child_monitor() {
        let (_home, host) = test_host();
        let config = host.config().as_ref().clone();
        let parent_agent_id = config.default_agent_id.clone();
        let child = AgentIdentityRecord::new(
            "child_recover",
            AgentKind::Child,
            AgentVisibility::Private,
            AgentOwnership::ParentSupervised,
            AgentProfilePreset::PrivateChild,
            Some(parent_agent_id.clone()),
            Some("task-recover-child".into()),
        )
        .with_lineage_parent_agent_id(Some(parent_agent_id.clone()));
        let parent_storage = host.agent_storage(&parent_agent_id).unwrap();
        // Bootstrap the original empty domain before its real first Task ACK.
        let original_parent = host.default_runtime().await.unwrap();
        let original_task = TaskRecord {
            id: "task-recover-child".into(),
            agent_id: parent_agent_id.clone(),
            kind: crate::types::TaskKind::ChildAgentTask,
            status: TaskStatus::Running,
            created_at: chrono::Utc::now(),
            updated_at: chrono::Utc::now(),
            parent_message_id: None,
            work_item_id: None,
            summary: Some("delegated child".into()),
            detail: Some(serde_json::json!({
                "child_agent_id": "child_recover",
                "target": {
                    "kind": "child_agent",
                    "agent_id": child.agent_id,
                    "incarnation": child.incarnation,
                },
                "child_turn_baseline": 0,
                "task_status": "running",
            })),
            recovery: Some(TaskRecoverySpec::ChildAgentTask {
                summary: "delegated child".into(),
                prompt: "continue delegated child".into(),
                authority_class: AuthorityClass::OperatorInstruction,
                workspace_mode: crate::types::ChildAgentWorkspaceMode::Inherit,
                lifecycle_disposition: crate::types::AgentLifecycleDisposition::DeleteOnTerminal,
            }),
        };
        crate::runtime::tests::support::persist_task_transition(
            &original_parent,
            &original_task,
            "recovered_child_original_task_fixture",
        )
        .await
        .unwrap();
        assert!(original_parent
            .active_tasks(usize::MAX)
            .await
            .unwrap()
            .iter()
            .any(|task| task == &original_task));
        let qualified: bool = host.runtime_db().connection().unwrap().query_row(
            "SELECT EXISTS(SELECT 1 FROM task_domain_records WHERE agent_id=?1 AND identity_incarnation=?2 AND family='task' AND record_id=?3 AND availability='present')",
            rusqlite::params![parent_agent_id, original_parent.instance_incarnation(), original_task.id],
            |row| row.get(0),
        ).unwrap();
        assert!(qualified, "original Task must be admitted before restart");

        host.append_agent_identity(&child).unwrap();
        host.runtime_db().agent_identities().upsert(&child).unwrap();

        let child_storage = host.agent_storage("child_recover").unwrap();
        let mut child_state = AgentState::new("child_recover");
        child_state.turn_index = 1;
        child_state.status = AgentStatus::AwakeIdle;
        child_state.last_turn_terminal = Some(crate::types::TurnTerminalRecord {
            turn_index: 1,
            turn_id: "test".into(),
            kind: crate::types::TurnTerminalKind::Completed,
            reason: None,
            last_assistant_message: Some("child finished after restart".into()),
            no_brief_reason: None,
            checkpoint: None,
            completed_at: chrono::Utc::now(),
            duration_ms: 1,
        });
        child_storage.write_agent_for_fixture(&child_state).unwrap();

        seed_supervised_child_terminal(&host, "task-recover-child", "child_recover");

        // Retire only the old instance; the canonical running Task survives.
        drop(original_parent);
        host.shutdown().await.unwrap();
        assert_eq!(
            parent_storage
                .latest_task_record(&original_task.id)
                .unwrap(),
            Some(original_task),
        );
        assert_eq!(
            host.agent_identity_record("child_recover")
                .unwrap()
                .unwrap()
                .status,
            AgentRegistryStatus::Active,
        );
        assert_eq!(child_storage.read_agent().unwrap(), Some(child_state));
        drop(host);

        let restarted =
            RuntimeHost::new_with_provider(config, Arc::new(StubProvider::new("done"))).unwrap();
        restarted.spawn_daemon_deletion_coordinator();
        let runtime = restarted.default_runtime().await.unwrap();
        let runtime_task = tokio::spawn(runtime.clone().run());

        let deadline = tokio::time::Instant::now() + Duration::from_secs(5);
        loop {
            let task = runtime
                .storage()
                .latest_task_record("task-recover-child")
                .unwrap()
                .expect("recovered task should remain recorded");
            if task.status == TaskStatus::Completed {
                break;
            }
            assert!(
                tokio::time::Instant::now() < deadline,
                "timed out waiting for recovered child monitor to converge: task={task:?}, \
                 parent_events={:?}, parent_state={:?}, child_state={:?}, child_identity={:?}, \
                 runtime_finished={}, original_source={}",
                runtime.storage().read_recent_events(100),
                restarted
                    .runtime_db()
                    .agent_states()
                    .latest(&parent_agent_id),
                restarted
                    .runtime_db()
                    .agent_states()
                    .latest("child_recover"),
                restarted.agent_identity_record("child_recover"),
                runtime_task.is_finished(),
                runtime.recovered_child_monitor_diagnostics_for_test("task-recover-child"),
            );
            tokio::time::sleep(Duration::from_millis(50)).await;
        }

        let task = runtime
            .storage()
            .latest_task_record("task-recover-child")
            .unwrap()
            .expect("completed task should remain recorded");
        assert_eq!(task.status, TaskStatus::Completed);
        let output = runtime
            .task_output("task-recover-child", false, 0)
            .await
            .unwrap();
        assert!(output
            .task
            .output_preview
            .contains("child finished after restart"));
        let events = runtime.storage().read_recent_events(100).unwrap();
        assert!(events.iter().any(|event| {
            event.kind == "supervised_child_task_monitor_reattached"
                && event
                    .data
                    .get("task_ids")
                    .and_then(|value| value.as_array())
                    .is_some_and(|ids| ids.iter().any(|value| value == "task-recover-child"))
        }));
        assert!(!events.iter().any(|event| {
            event.kind == "task_interrupted_on_restart"
                && event.data.get("id").and_then(|value| value.as_str())
                    == Some("task-recover-child")
        }));
        let deadline = tokio::time::Instant::now() + Duration::from_secs(5);
        let deletion_job = loop {
            let child_identity = restarted
                .agent_identity_record("child_recover")
                .unwrap()
                .expect("child identity should remain recorded");
            let deletion_job = restarted
                .runtime_db()
                .agent_deletions()
                .latest_for_agent("child_recover")
                .unwrap()
                .unwrap_or_else(|| {
                    let receipts: anyhow::Result<Vec<(String, String)>> = (|| {
                        let connection = restarted.runtime_db().connection()?;
                        let mut statement = connection.prepare(
                            "SELECT command_nonce,outcome_json FROM input_mutation_receipts
                             WHERE family='task'
                               AND json_extract(outcome_json,'$.result.kind')='child_task_terminal'
                               AND json_extract(outcome_json,'$.result.ack.original.admitted.key.id')=?1
                             ORDER BY committed_at DESC LIMIT 8",
                        )?;
                        let rows = statement.query_map(["task-recover-child"], |row| {
                            Ok((row.get(0)?, row.get(1)?))
                        })?;
                        Ok(rows.collect::<rusqlite::Result<Vec<_>>>()?)
                    })();
                    panic!(
                        "terminal child cleanup should use a canonical deletion job: \
                         task={task:?}, child_identity={child_identity:?}, canonical_relations={:?}, \
                         terminal_receipts={receipts:?}, parent_events={events:?}, original_source={}",
                        restarted.runtime_db().agent_canonical_relations().latest("child_recover"),
                        runtime.recovered_child_monitor_diagnostics_for_test("task-recover-child"),
                    );
                });
            if child_identity.status == AgentRegistryStatus::Deleted
                && deletion_job.status == crate::types::AgentDeletionStatus::Completed
            {
                break deletion_job;
            }
            assert!(
                tokio::time::Instant::now() < deadline,
                "timed out waiting for canonical terminal child deletion to complete: {deletion_job:?}"
            );
            tokio::time::sleep(Duration::from_millis(50)).await;
        };
        assert_eq!(
            deletion_job.status,
            crate::types::AgentDeletionStatus::Completed
        );
        assert_eq!(deletion_job.mode, crate::types::AgentDeletionMode::Delete);
        assert_eq!(
            runtime
                .task_output("task-recover-child", false, 0)
                .await
                .unwrap()
                .task
                .output_preview,
            output.task.output_preview
        );

        runtime_task.abort();
        restarted.shutdown_daemon_deletion_coordinator().await;
    }

    #[tokio::test]
    async fn recovered_child_monitor_waits_for_active_child_tasks() {
        let (_home, host) = test_host();
        let config = host.config().as_ref().clone();
        let parent_agent_id = config.default_agent_id.clone();
        let parent_storage = host.agent_storage(&parent_agent_id).unwrap();
        parent_storage
            .append_task(&TaskRecord {
                id: "task-recover-active-child-task".into(),
                agent_id: parent_agent_id.clone(),
                kind: crate::types::TaskKind::ChildAgentTask,
                status: TaskStatus::Running,
                created_at: chrono::Utc::now(),
                updated_at: chrono::Utc::now(),
                parent_message_id: None,
                work_item_id: None,
                summary: Some("delegated child".into()),
                detail: Some(serde_json::json!({
                    "child_agent_id": "child_recover_active_task",
                    "child_turn_baseline": 0,
                    "task_status": "running",
                })),
                recovery: Some(TaskRecoverySpec::ChildAgentTask {
                    summary: "delegated child".into(),
                    prompt: "continue delegated child".into(),
                    authority_class: AuthorityClass::OperatorInstruction,
                    workspace_mode: crate::types::ChildAgentWorkspaceMode::Inherit,
                    lifecycle_disposition:
                        crate::types::AgentLifecycleDisposition::DeleteOnTerminal,
                }),
            })
            .unwrap();

        let child = AgentIdentityRecord::new(
            "child_recover_active_task",
            AgentKind::Child,
            AgentVisibility::Private,
            AgentOwnership::ParentSupervised,
            AgentProfilePreset::PrivateChild,
            Some(parent_agent_id.clone()),
            Some("task-recover-active-child-task".into()),
        )
        .with_lineage_parent_agent_id(Some(parent_agent_id.clone()));
        host.append_agent_identity(&child).unwrap();
        host.runtime_db().agent_identities().upsert(&child).unwrap();

        let child_storage = host.agent_storage("child_recover_active_task").unwrap();
        let mut child_state = AgentState::new("child_recover_active_task");
        child_state.turn_index = 1;
        child_state.status = AgentStatus::AwakeIdle;
        child_state.last_turn_terminal = Some(crate::types::TurnTerminalRecord {
            turn_index: 1,
            turn_id: "test".into(),
            kind: crate::types::TurnTerminalKind::Completed,
            reason: None,
            last_assistant_message: Some("child says done before command finished".into()),
            no_brief_reason: None,
            checkpoint: None,
            completed_at: chrono::Utc::now(),
            duration_ms: 1,
        });
        child_storage.write_agent_for_fixture(&child_state).unwrap();
        child_storage
            .append_task(&TaskRecord {
                id: "child-command-still-running".into(),
                agent_id: "child_recover_active_task".into(),
                kind: crate::types::TaskKind::CommandTask,
                status: TaskStatus::Running,
                created_at: chrono::Utc::now(),
                updated_at: chrono::Utc::now(),
                parent_message_id: None,
                work_item_id: None,
                summary: Some("verification".into()),
                detail: Some(json!({"parent_turn_id": "test"})),
                recovery: None,
            })
            .unwrap();

        // Also add an active Task wait condition so the lifecycle blocker
        // persists through recovery. The orphaned command task above is
        // interrupted by the child's own bootstrap_recovery, but a wait
        // condition survives restart, keeping the parent monitor running
        // deterministically rather than racing with task cleanup.
        let now = chrono::Utc::now();
        child_storage
            .append_wait_condition(&crate::types::WaitConditionRecord {
                id: "wait-child-command".into(),
                agent_id: "child_recover_active_task".into(),
                work_item_id: None,
                status: crate::types::WaitConditionStatus::Active,
                kind: crate::types::WaitConditionKind::Task,
                source: None,
                subject_ref: Some("child-command-still-running".into()),
                waiting_for: "command result".into(),
                wake_sources: vec![crate::types::WakeSource::TaskResult {
                    task_id: "child-command-still-running".into(),
                }],
                continuation: None,
                created_at: now,
                updated_at: now,
                expires_at: None,
                resolved_at: None,
                cancelled_at: None,
                turn_id: Some("test".into()),
                trigger_message_id: None,
                triggered_at: None,
            })
            .unwrap();

        seed_supervised_child_terminal(
            &host,
            "task-recover-active-child-task",
            "child_recover_active_task",
        );

        drop(host);

        let restarted =
            RuntimeHost::new_with_provider(config, Arc::new(StubProvider::new("done"))).unwrap();
        let runtime = restarted.default_runtime().await.unwrap();
        let runtime_task = tokio::spawn(runtime.clone().run());
        tokio::time::sleep(Duration::from_millis(250)).await;

        let task = runtime
            .storage()
            .latest_task_record("task-recover-active-child-task")
            .unwrap()
            .expect("recovered task should remain recorded");
        assert_eq!(task.status, TaskStatus::Running);
        let child_identity = restarted
            .agent_identity_record("child_recover_active_task")
            .unwrap()
            .expect("child identity should remain recorded");
        assert_eq!(child_identity.status, AgentRegistryStatus::Active);

        runtime_task.abort();
    }

