    #[tokio::test]
    async fn orphan_trash_sweep_rechecks_ownership_after_enumeration() {
        let (_home, host) = test_host();
        let parent = host.default_runtime().await.unwrap();
        let parent_id = host.config().default_agent_id.clone();
        for legacy in [false, true] {
            let fence = host.inner.agent_home_cleanup_lock.lock().await;
            let child =
                retained_cleanup_fixture(&host, &format!("sweep-late-owner-{legacy}.child"));
            let home = host.agent_data_dir(&child.agent_id);
            let trash = if legacy {
                home.with_extension("deleting_trash")
            } else {
                home.with_file_name(format!("{}.deleting_trash", child.agent_id))
            };
            fs::create_dir_all(&home).unwrap();
            fs::create_dir_all(&trash).unwrap();
            let candidate = fs::read_dir(home.parent().unwrap())
                .unwrap()
                .map(|entry| entry.unwrap().path())
                .find(|path| path == &trash)
                .unwrap();
            let (started_tx, started_rx) = tokio::sync::oneshot::channel();
            let sweep_host = host.clone();
            let sweep = tokio::spawn(async move {
                started_tx.send(()).unwrap();
                sweep_host.remove_orphan_agent_home_trash(&candidate).await
            });
            started_rx.await.unwrap();
            assert!(!sweep.is_finished());
            // Commit admission and a failed Home attempt while the stale
            // enumerated candidate is waiting for the shared ownership fence.
            let (deleting, mut job, _) = host
                .runtime_db()
                .agent_deletions()
                .begin_parent_cleanup(
                    &child.agent_id,
                    &parent_id,
                    child.incarnation,
                    parent.instance_incarnation(),
                )
                .unwrap();
            host.cache_agent_identity(&deleting).unwrap();
            job.phase = AgentDeletionPhase::Home;
            host.runtime_db().agent_deletions().update(&job).unwrap();
            fs::remove_dir(&trash).unwrap();
            fs::rename(&home, &trash).unwrap();
            fs::create_dir_all(trash.join("work")).unwrap();
            fs::write(trash.join("work/report.md"), "protected result").unwrap();
            drop(fence);
            assert!(!sweep.await.unwrap().unwrap());
            let error = host.execute_deletion_job(job).await.unwrap_err();
            assert!(
                error.to_string().contains("unregistered_home_artifact"),
                "{error:#}"
            );
            assert_eq!(host.sweep_orphan_agent_home_trash().await.unwrap(), 0);
            assert_eq!(
                fs::read_to_string(trash.join("work/report.md")).unwrap(),
                "protected result"
            );
        }
        host.shutdown().await.unwrap();
    }

    #[tokio::test]
    async fn deletion_phase_home_refuses_live_home_colliding_with_trash_name() {
        let (_home, host) = test_host();
        let agents_root = host.config().data_dir.join("agents");
        // Legacy live agent whose id equals the trash name of "customer".
        let colliding = AgentIdentityRecord::new(
            "customer.deleting_trash",
            AgentKind::Default,
            AgentVisibility::Public,
            AgentOwnership::SelfOwned,
            AgentProfilePreset::PublicNamed,
            None,
            None,
        );
        host.append_agent_identity(&colliding).unwrap();
        host.runtime_db()
            .agent_identities()
            .upsert(&colliding)
            .unwrap();
        let colliding_home = agents_root.join("customer.deleting_trash");
        std::fs::create_dir_all(colliding_home.join("nested")).unwrap();
        std::fs::write(colliding_home.join("nested/file.txt"), "live").unwrap();

        let customer = AgentIdentityRecord::new(
            "customer",
            AgentKind::Default,
            AgentVisibility::Public,
            AgentOwnership::SelfOwned,
            AgentProfilePreset::PublicNamed,
            None,
            None,
        );
        host.append_agent_identity(&customer).unwrap();
        host.runtime_db()
            .agent_identities()
            .upsert(&customer)
            .unwrap();
        std::fs::create_dir_all(agents_root.join("customer")).unwrap();

        let (_identity, job, _created) = host
            .begin_public_agent_deletion("customer", false, "operator")
            .await
            .unwrap();
        let result = host.execute_deletion_job(job.clone()).await;

        // The job must fail rather than remove the colliding live home.
        assert!(result.is_err());
        assert!(colliding_home.join("nested/file.txt").exists());
        // A missing home does not relinquish the registered identity's claim.
        std::fs::remove_dir_all(&colliding_home).unwrap();
        let retry = host
            .runtime_db()
            .agent_deletions()
            .latest_for_agent(&job.agent_id)
            .unwrap()
            .unwrap();
        let wait_for = (retry.next_attempt_at.unwrap() - Utc::now())
            .to_std()
            .unwrap_or_default()
            + Duration::from_millis(100);
        tokio::time::sleep(wait_for).await;
        let error = host.execute_deletion_job(retry).await.unwrap_err();
        assert!(error.to_string().contains("live home"));
        assert!(agents_root.join("customer").exists());
    }

    #[tokio::test]
    async fn daemon_deletion_coordinator_is_singleton_and_admission_wakes_it() {
        let (_home, host) = test_host();
        host.spawn_daemon_deletion_coordinator();
        let first_handle_id = host
            .inner
            .daemon_deletion_handle
            .lock()
            .unwrap()
            .as_ref()
            .expect("coordinator handle")
            .id();
        host.spawn_daemon_deletion_coordinator();
        let second_handle_id = host
            .inner
            .daemon_deletion_handle
            .lock()
            .unwrap()
            .as_ref()
            .expect("same coordinator handle")
            .id();
        assert_eq!(first_handle_id, second_handle_id);

        let agent = AgentIdentityRecord::new(
            "delete-daemon-wake",
            AgentKind::Default,
            AgentVisibility::Public,
            AgentOwnership::SelfOwned,
            AgentProfilePreset::PublicNamed,
            None,
            None,
        );
        host.append_agent_identity(&agent).unwrap();
        host.runtime_db().agent_identities().upsert(&agent).unwrap();
        let (_, job, created) = host
            .begin_public_agent_deletion("delete-daemon-wake", false, "operator")
            .await
            .unwrap();
        assert!(created);
        assert_eq!(job.status, AgentDeletionStatus::Pending);

        tokio::time::timeout(Duration::from_secs(5), async {
            loop {
                let job = host
                    .runtime_db()
                    .agent_deletions()
                    .latest_for_agent("delete-daemon-wake")
                    .unwrap()
                    .expect("deletion job");
                if job.status == AgentDeletionStatus::Completed {
                    break;
                }
                tokio::time::sleep(Duration::from_millis(10)).await;
            }
        })
        .await
        .expect("coalesced admission wake should complete deletion");

        host.shutdown_daemon_deletion_coordinator().await;
        assert!(host.inner.daemon_deletion_handle.lock().unwrap().is_none());
    }

    #[tokio::test]
    async fn deletion_retry_deadline_bounds_real_index_lock_retries() {
        let (_home, host) = test_host();
        let default_storage = host.agent_storage(&host.config().default_agent_id).unwrap();
        crate::memory::rebuild_memory_index(&default_storage, None).unwrap();
        let index_path = crate::memory::index::memory_index_path(&default_storage);
        let blocker = rusqlite::Connection::open(index_path).unwrap();
        blocker.execute_batch("BEGIN IMMEDIATE").unwrap();

        let agent = AgentIdentityRecord::new(
            "delete-locked",
            AgentKind::Default,
            AgentVisibility::Public,
            AgentOwnership::SelfOwned,
            AgentProfilePreset::PublicNamed,
            None,
            None,
        );
        host.append_agent_identity(&agent).unwrap();
        host.runtime_db().agent_identities().upsert(&agent).unwrap();
        let (_, job, created) = host
            .begin_public_agent_deletion("delete-locked", false, "operator")
            .await
            .unwrap();
        assert!(created);

        let error = host
            .execute_deletion_job(job)
            .await
            .expect_err("index lock should schedule a retry");
        assert!(
            error.to_string().contains("exhausted retry deadline"),
            "unexpected deletion error: {error:#}"
        );
        let mut failed = host
            .runtime_db()
            .agent_deletions()
            .latest_for_agent("delete-locked")
            .unwrap()
            .expect("failed job should exist");
        assert_eq!(failed.status, AgentDeletionStatus::RetryableFailed);
        assert_eq!(failed.phase, AgentDeletionPhase::Index);
        assert_eq!(failed.attempts, 1);
        assert!(failed
            .next_attempt_at
            .is_some_and(|at| at > failed.updated_at));

        let read_started = std::time::Instant::now();
        assert!(host
            .runtime_db()
            .agent_deletions()
            .latest_for_agent("delete-locked")
            .unwrap()
            .is_some());
        assert!(read_started.elapsed() < Duration::from_secs(1));

        // Keep the not-due checks independent of wall-clock progress under load.
        failed.next_attempt_at = Some(Utc::now() + chrono::Duration::days(1));
        host.runtime_db().agent_deletions().update(&failed).unwrap();
        for _ in 0..32 {
            host.notify_deletion_coordinator();
            host.execute_deletion_job(failed.clone()).await.unwrap();
        }
        let mut still_waiting = host
            .runtime_db()
            .agent_deletions()
            .latest_for_agent("delete-locked")
            .unwrap()
            .expect("retry job should remain");
        assert_eq!(still_waiting.attempts, 1);
        assert_eq!(still_waiting.next_attempt_at, failed.next_attempt_at);

        blocker.execute_batch("ROLLBACK").unwrap();
        drop(blocker);
        still_waiting.next_attempt_at = Some(Utc::now() - chrono::Duration::days(1));
        host.runtime_db()
            .agent_deletions()
            .update(&still_waiting)
            .unwrap();
        host.execute_deletion_job(still_waiting).await.unwrap();
        let completed = host
            .runtime_db()
            .agent_deletions()
            .latest_for_agent("delete-locked")
            .unwrap()
            .expect("completed job should exist");
        assert_eq!(completed.status, AgentDeletionStatus::Completed);
        assert_eq!(completed.attempts, 2);
    }

    fn retained_cleanup_fixture(host: &RuntimeHost, child_id: &str) -> AgentIdentityRecord {
        let parent_id = host.config().default_agent_id.clone();
        let task_id = format!("task-{child_id}");
        let child = AgentIdentityRecord::new(
            child_id,
            AgentKind::Child,
            AgentVisibility::Private,
            AgentOwnership::ParentSupervised,
            AgentProfilePreset::PrivateChild,
            Some(parent_id.clone()),
            Some(task_id.clone()),
        );
        let relations = supervised_creation_records(&child, &parent_id, &task_id, None);
        host.runtime_db()
            .agent_identities()
            .create_with_relations(&child, &relations)
            .unwrap();
        host.cache_agent_identity(&child).unwrap();
        let mut state = AgentState::new(child_id.to_string());
        state.status = AgentStatus::AwakeIdle;
        host.runtime_db()
            .agent_states()
            .upsert_for_fixture(&state)
            .unwrap();
        child
    }

    async fn completed_retained_child(
        host: &RuntimeHost,
    ) -> (RuntimeHandle, crate::types::AgentInvocationReceipt) {
        let parent = host.default_runtime().await.unwrap();
        let created = parent
            .agent_invocation_service()
            .invoke(InvokeAgentRequest {
                target: InvokeAgentTarget::NewSubagent {
                    template: None,
                    workspace_mode: ChildAgentWorkspaceMode::Inherit,
                    model_resolution: Some(inherited_model_resolution("openai", "gpt-5.4")),
                },
                message: "retirement fixture".into(),
                authority_class: AuthorityClass::OperatorInstruction,
            })
            .await
            .unwrap();
        wait_for_terminal_task(&parent, &created.task_handle.task_id).await;
        (parent, created)
    }

    async fn observe_idle_candidate(host: &RuntimeHost, agent_id: &str) -> u64 {
        tokio::time::timeout(Duration::from_secs(5), async {
            loop {
                let mut cursor = None;
                let candidates = host
                    .scan_idle_runtime_candidates(&mut cursor, 16, Duration::ZERO, true)
                    .await
                    .unwrap();
                if let Some((_, generation)) = candidates.into_iter().find(|(id, _)| id == agent_id)
                {
                    break generation;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .unwrap_or_else(|error| {
            let state = host.runtime_db().agent_states().latest(agent_id).unwrap();
            let events = host
                .agent_storage_read_only(agent_id)
                .unwrap()
                .read_recent_events(100)
                .unwrap();
            panic!("idle candidate did not appear: {error:?}, state={state:?}, events={events:?}")
        })
    }

