    #[tokio::test]
    async fn parent_cleanup_exits_runtime_and_preserves_parent_result() {
        let (_home, host) = test_host();
        let parent = host.default_runtime().await.unwrap();
        let parent_id = parent
            .agent_summary()
            .await
            .unwrap()
            .identity
            .agent_id
            .clone();
        let created = parent
            .agent_invocation_service()
            .invoke(InvokeAgentRequest {
                target: InvokeAgentTarget::NewSubagent {
                    template: None,
                    workspace_mode: ChildAgentWorkspaceMode::Inherit,
                    model_resolution: Some(inherited_model_resolution("openai", "gpt-5.4")),
                },
                message: "produce durable result".into(),
                authority_class: AuthorityClass::OperatorInstruction,
            })
            .await
            .unwrap();
        let task = wait_for_terminal_task(&parent, &created.task_handle.task_id).await;
        let assert_parent_result = || {
            // This invocation predates the parent's first Turn. It has a
            // durable result, but cannot acquire a fabricated rejoin fence.
            assert_eq!(
                task.rejoin_fence().unwrap_err(),
                "task rejoin contract is missing parent turn identity"
            );
            let current = parent
                .storage()
                .latest_task_record(&task.id)
                .unwrap()
                .unwrap();
            assert_eq!(current.agent_id, parent_id);
            assert_eq!(current.parent_message_id, task.parent_message_id);
            assert_eq!(current.work_item_id, task.work_item_id);
            assert_eq!(
                current.rejoin_fence().unwrap_err(),
                "task rejoin contract is missing parent turn identity"
            );
            assert!(host
                .runtime_db()
                .task_result_settlements()
                .latest_for_message(task.parent_message_id.as_deref().unwrap())
                .unwrap()
                .is_none());
            assert_eq!(
                host.runtime_db()
                    .task_result_settlements()
                    .next_recheck_at(&parent_id)
                    .unwrap(),
                None
            );
        };
        let before = parent.task_output(&task.id, false, 0).await.unwrap();
        let old = host
            .try_get_loaded_runtime(&created.agent_id)
            .await
            .unwrap();
        let delivered_briefs = old.storage().read_recent_briefs(10).unwrap();
        // Use the runtime writers, not just an output_path database reference.
        let artifact = old
            .persist_tool_text_artifact("cleanup-result", "tool output")
            .await
            .unwrap();
        assert!(std::path::Path::new(&artifact).is_file());
        let command = old
            .schedule_command_task(
                "produce retained command output".into(),
                crate::types::CommandTaskSpec {
                    cmd: "printf 'retained command output'".into(),
                    workdir: None,
                    shell: None,
                    login: false,
                    tty: false,
                    yield_time_ms: 100,
                    max_output_tokens: None,
                    accepts_input: false,
                    terminal_reentry: true,
                },
                AuthorityClass::RuntimeInstruction,
            )
            .await
            .unwrap();
        let command = wait_for_terminal_task(&old, &command.id).await;
        assert_eq!(command.status, TaskStatus::Completed);
        assert!(host
            .agent_data_dir(&created.agent_id)
            .join("task-output")
            .join(format!("{}.log", command.id))
            .is_file());
        tokio::time::timeout(Duration::from_secs(5), async {
            loop {
                let settlement = host
                    .runtime_db()
                    .task_result_settlements()
                    .latest_for_message(command.parent_message_id.as_deref().unwrap())
                    .unwrap();
                let state = host
                    .runtime_db()
                    .agent_states()
                    .latest(&created.agent_id)
                    .unwrap()
                    .unwrap();
                if settlement.is_some_and(|record| {
                    record.state
                        == crate::runtime_db::task_result_settlement::TaskResultSettlementState::Settled
                }) && matches!(state.status, crate::types::AgentStatus::Asleep)
                    && state.current_run_id.is_none()
                    && state.pending == 0
                {
                    break;
                }
                tokio::time::sleep(Duration::from_millis(10)).await;
            }
        })
        .await
        .unwrap_or_else(|error| {
            panic!(
                "command result must settle and runtime must sleep before the final producer turn: \
                 {error}; settlement={:?}; state={:?}",
                host.runtime_db()
                    .task_result_settlements()
                    .latest_for_message(command.parent_message_id.as_deref().unwrap()),
                host.runtime_db().agent_states().latest(&created.agent_id).map(|state|
                    state.map(|state| (state.status, state.current_run_id, state.pending,
                        state.current_execution_binding, state.last_turn_terminal))),
            )
        });
        assert_eq!(
            old.storage().read_recent_briefs(10).unwrap(),
            delivered_briefs,
            "settling a delivered-parent result must not publish another brief"
        );
        assert_eq!(
            host.runtime_db()
                .task_result_settlements()
                .latest_for_message(command.parent_message_id.as_deref().unwrap())
                .unwrap()
                .unwrap()
                .disposition,
            Some(crate::runtime_db::TaskResultSettlementDisposition::InvalidOrStale),
            "a suppressed result must not be recorded as delivered to the model"
        );
        let state = old.agent_state().await.unwrap();
        assert_eq!(
            state.last_turn_terminal.unwrap().reason.as_deref(),
            Some("reducer_only/parent_turn_already_delivered")
        );
        assert!(matches!(
            state
                .current_execution_binding
                .unwrap()
                .admission_provenance,
            Some(crate::types::ExecutionAdmissionProvenance::Canonical { .. })
        ));
        assert_ne!(created.agent_id, parent_id);
        let settlement = host
            .runtime_db()
            .task_result_settlements()
            .latest_for_message(command.parent_message_id.as_deref().unwrap())
            .unwrap()
            .unwrap();
        assert_eq!(settlement.task_id, command.id);
        assert_eq!(
            settlement.rejoin_generation,
            command.rejoin_fence().unwrap().generation
        );
        assert_eq!(
            settlement.disposition,
            Some(crate::runtime_db::TaskResultSettlementDisposition::InvalidOrStale)
        );
        assert_ne!(created.agent_id, parent_id);
        assert_parent_result();
        assert_eq!(
            host.runtime_db()
                .task_result_settlements()
                .next_recheck_at(&created.agent_id)
                .unwrap(),
            None
        );
        let turn_before_final = host
            .runtime_db()
            .agent_states()
            .latest(&created.agent_id)
            .unwrap()
            .unwrap()
            .turn_index;
        // A lifecycle nudge is not a producer turn. Use normal prompt admission
        // after settlement to finish producing artifacts and become idle.
        old.enqueue(MessageEnvelope::new(
            &created.agent_id,
            MessageKind::OperatorPrompt,
            MessageOrigin::Operator {
                actor_id: None,
                actor_display_name: None,
            },
            AuthorityClass::OperatorInstruction,
            Priority::Normal,
            MessageBody::Text {
                text: "finish producing retained artifacts".into(),
            },
        ))
        .await
        .unwrap();
        let identity = host
            .agent_identity_record(&created.agent_id)
            .unwrap()
            .unwrap();
        let mut last_cleanup_rejection = None;
        let job = tokio::time::timeout(Duration::from_secs(5), async {
            loop {
                let state = host
                    .runtime_db()
                    .agent_states()
                    .latest(&created.agent_id)
                    .unwrap()
                    .unwrap();
                if state.turn_index <= turn_before_final
                    || state.status != crate::types::AgentStatus::Asleep
                    || state.current_run_id.is_some()
                    || state.pending != 0
                {
                    tokio::time::sleep(Duration::from_millis(10)).await;
                    continue;
                }
                assert_eq!(
                    state.sleeping_until, None,
                    "the child's final turn must not inherit its parent's result recheck"
                );
                assert_parent_result();
                match host
                    .begin_parent_agent_deletion(&parent, &identity.agent_id, identity.incarnation)
                    .await
                {
                    Ok(job) => break job,
                    Err(error)
                        if error.to_string().contains("live_execution")
                            || error.to_string().contains("runtime_execution_or_wake")
                            || error.to_string().contains("queued_or_claimed_input")
                            || error.to_string().contains("resource_refresh_exit_pending")
                            || error.to_string().contains("open_execution") =>
                    {
                        last_cleanup_rejection = Some(format!("{error:#}"));
                        tokio::time::sleep(Duration::from_millis(10)).await
                    }
                    Err(error) => panic!("unexpected cleanup rejection: {error:#}"),
                }
            }
        })
        .await
        .unwrap_or_else(|error| {
            let state = host
                .runtime_db()
                .agent_states()
                .latest(&identity.agent_id)
                .unwrap()
                .unwrap();
            panic!(
                "cleanup admission timed out: {error}; last_rejection={last_cleanup_rejection:?}; status={:?}; sleeping_until={:?}; pending={}; turns={}->{}; next_result_recheck={:?}; recent_events={:?}; result_settlements={:?}",
                state.status,
                state.sleeping_until,
                state.pending,
                turn_before_final,
                state.turn_index,
                host.runtime_db()
                    .task_result_settlements()
                    .next_recheck_at(&identity.agent_id),
                old.storage().read_recent_events(12),
                host.runtime_db()
                    .task_result_settlements()
                    .due_deferred(
                        &identity.agent_id,
                        Utc::now() + chrono::Duration::hours(1),
                        10,
                    )
            )
        });
        assert!(
            host.runtime_db()
                .agent_states()
                .latest(&created.agent_id)
                .unwrap()
                .unwrap()
                .turn_index
                > turn_before_final,
            "the final producer prompt must execute a real model turn"
        );
        host.execute_deletion_job(job.clone())
            .await
            .unwrap_or_else(|error| panic!("{error:#}; retained task detail={:?}", task.detail));
        assert!(host
            .try_get_loaded_runtime(&identity.agent_id)
            .await
            .is_none());
        assert!(!host.agent_data_dir(&identity.agent_id).exists());
        assert_eq!(
            host.agent_identity_record(&identity.agent_id)
                .unwrap()
                .unwrap()
                .status,
            AgentRegistryStatus::Deleted
        );
        let after = parent.task_output(&task.id, false, 0).await.unwrap();
        assert_parent_result();
        assert_eq!(after.task.output_preview, before.task.output_preview);
        assert_eq!(after.task.status, before.task.status);
        let message = MessageEnvelope::new(
            &identity.agent_id,
            MessageKind::InternalFollowup,
            MessageOrigin::System {
                subsystem: "test".into(),
            },
            AuthorityClass::RuntimeInstruction,
            Priority::Normal,
            MessageBody::Text {
                text: "late input".into(),
            },
        );
        assert!(old.enqueue(message).await.is_err());
        let repeated = host
            .begin_parent_agent_deletion(&parent, &identity.agent_id, identity.incarnation)
            .await
            .unwrap();
        assert_eq!(repeated.deletion_id, job.deletion_id);
        host.shutdown().await.unwrap();
    }

