    #[tokio::test]
    async fn deletion_coordinator_reentry_retires_canonical_work_and_attempts() {
        use crate::domain::execution_protocol::{WorkItemExecutionRecord, WorkItemExecutionState};
        use crate::types::{
            CompletionReportRequirement, CompletionReportState, WorkItemCompletionIntent,
            WorkItemContinuationFrame,
        };
        let (_home, host) = test_host();
        let agent_id = "delete-canonical-work";
        host.create_named_agent(agent_id, None).await.unwrap();
        host.unload_runtime(agent_id).await;
        let (focused_id, attempt_id) = seed_startup_consumed_result_attempt(&host, agent_id);
        let mut completing = WorkItemRecord::new(
            agent_id,
            "interrupted completion",
            WorkItemState::Completing,
        );
        let now = Utc::now();
        completing.completion_intent = Some(WorkItemCompletionIntent {
            work_item_id: completing.id.clone(),
            source_activation_id: None,
            source_message_id: None,
            source_turn_id: None,
            expected_work_revision: 1,
            report_requirement: CompletionReportRequirement::Required,
            report_state: CompletionReportState::Pending,
            result_brief_id: None,
            created_at: now,
            updated_at: now,
        });
        let open = WorkItemRecord::new(agent_id, "queued work", WorkItemState::Open);
        for work in [&completing, &open] {
            host.runtime_db().work_items().insert_new(work).unwrap();
        }
        let frame = WorkItemContinuationFrame::new_on_completed(
            agent_id,
            focused_id.clone(),
            open.id.clone(),
            None,
        );
        host.runtime_db()
            .work_item_continuations()
            .upsert(&frame)
            .unwrap();
        let mut execution = host
            .runtime_db()
            .transitions()
            .load_execution_protocol_state_if_initialized(agent_id)
            .unwrap()
            .unwrap();
        for work in [&completing, &open] {
            execution.work_items.insert(
                work.id.clone(),
                WorkItemExecutionRecord {
                    source_revision: work.revision,
                    state: WorkItemExecutionState::Runnable {
                        generation: 1,
                        recovery_ref: None,
                    },
                },
            );
        }
        host.runtime_db()
            .transaction(|tx| crate::runtime_db::transitions::persist_state_tx(tx, &execution))
            .unwrap();
        let (_, mut job, _) = host
            .begin_public_agent_deletion_with_archive(agent_id, false, "operator", true)
            .await
            .unwrap();
        // Reenter at Scheduler after a crash; Fence/unload alone did not settle
        // the persisted execution attempt.
        job.status = AgentDeletionStatus::Running;
        job.phase = AgentDeletionPhase::Scheduler;
        host.runtime_db().agent_deletions().update(&job).unwrap();
        assert_eq!(
            host.runtime_db()
                .agent_deletions()
                .recover_running_jobs(Utc::now())
                .unwrap(),
            1
        );
        pause_deletion_before_private_purge(&host, job.clone()).await;
        assert_eq!(
            host.agent_identity_record(agent_id)
                .unwrap()
                .unwrap()
                .status,
            AgentRegistryStatus::Deleting
        );
        let records = host
            .runtime_db()
            .work_items()
            .latest_for_agent(agent_id, 10)
            .unwrap();
        assert_eq!(records.len(), 3);
        for work in &records {
            assert_eq!(work.state, WorkItemState::Completed);
            assert!(work.result_brief_id.is_some());
            assert_eq!(
                work.completion_intent.as_ref().unwrap().report_state,
                CompletionReportState::Bound
            );
        }
        let retired = host
            .runtime_db()
            .transitions()
            .load_execution_protocol_state_if_initialized(agent_id)
            .unwrap()
            .unwrap();
        assert_eq!(
            retired.attempts[&attempt_id].state,
            ExecutionAttemptState::Interrupted
        );
        assert_eq!(retired.outcomes.len(), 1);
        for work in &records {
            assert_eq!(retired.work_items[&work.id].source_revision, work.revision);
            assert!(matches!(&retired.work_items[&work.id].state,
                WorkItemExecutionState::Terminal { completion, .. }
                    if Some(completion) == work.result_brief_id.as_ref()));
        }
        assert!(host
            .runtime_db()
            .work_item_continuations()
            .active_for_agent(agent_id)
            .unwrap()
            .is_empty());
        let state = host
            .runtime_db()
            .agent_states()
            .latest(agent_id)
            .unwrap()
            .unwrap();
        assert!(state.current_work_item_id.is_none());
        assert!(state.current_turn_work_item_id.is_none());
        assert!(state.current_execution_binding.is_none());
        let audits = host
            .runtime_db()
            .audit_events()
            .recent(Some(agent_id), 100)
            .unwrap();
        // A replay before the retry deadline cannot duplicate terminalization.
        host.execute_deletion_job(job).await.unwrap();
        assert_eq!(
            host.runtime_db()
                .work_items()
                .latest_for_agent(agent_id, 10)
                .unwrap(),
            records
        );
        assert_eq!(
            host.runtime_db()
                .transitions()
                .load_execution_protocol_state_if_initialized(agent_id)
                .unwrap(),
            Some(retired)
        );
        assert_eq!(
            host.runtime_db()
                .audit_events()
                .recent(Some(agent_id), 100)
                .unwrap(),
            audits
        );
        resume_deletion_after_archive_failure(&host, agent_id).await;
        assert!(host
            .runtime_db()
            .work_items()
            .latest_for_agent(agent_id, 10)
            .unwrap()
            .is_empty());
        assert!(host
            .runtime_db()
            .transitions()
            .load_execution_protocol_state_if_initialized(agent_id)
            .unwrap()
            .is_none());
    }

    #[tokio::test]
    async fn parent_cleanup_retires_work_without_reopening_admission_or_inventing_legacy_briefs() {
        use crate::domain::execution_protocol::{
            ExecutionProtocolState, WorkItemExecutionRecord, WorkItemExecutionState,
        };
        for with_open in [true, false] {
            let (_home, host) = test_host();
            let parent = host.default_runtime().await.unwrap();
            let child = retained_cleanup_fixture(&host, "cleanup-focused-work");
            let agent_id = &child.agent_id;
            let mut execution = ExecutionProtocolState::empty(agent_id);
            let open = WorkItemRecord::new(agent_id, "retained work", WorkItemState::Open);
            if with_open {
                host.runtime_db().work_items().insert_new(&open).unwrap();
                let mut state = AgentState::new(agent_id);
                state.status = AgentStatus::AwakeIdle;
                state.current_work_item_id = Some(open.id.clone());
                host.runtime_db()
                    .agent_states()
                    .upsert_for_fixture(&state)
                    .unwrap();
                execution.work_items.insert(
                    open.id.clone(),
                    WorkItemExecutionRecord {
                        source_revision: open.revision,
                        state: WorkItemExecutionState::Runnable {
                            generation: 1,
                            recovery_ref: None,
                        },
                    },
                );
            }
            let mut legacy = Vec::new();
            for terminal in [true, false] {
                let work =
                    WorkItemRecord::new(agent_id, "legacy completed", WorkItemState::Completed);
                execution.work_items.insert(
                    work.id.clone(),
                    WorkItemExecutionRecord {
                        source_revision: work.revision,
                        state: if terminal {
                            WorkItemExecutionState::Terminal {
                                generation: 1,
                                completion: "legacy_completion".into(),
                            }
                        } else {
                            WorkItemExecutionState::Runnable {
                                generation: 1,
                                recovery_ref: None,
                            }
                        },
                    },
                );
                legacy.push(work);
            }
            for work in &legacy {
                host.runtime_db().work_items().insert_new(work).unwrap();
            }
            host.runtime_db()
                .transaction(|tx| crate::runtime_db::transitions::persist_state_tx(tx, &execution))
                .unwrap();
            let job = host
                .begin_parent_agent_deletion(&parent, agent_id, child.incarnation)
                .await
                .unwrap();
            assert!(host
                .runtime_db()
                .transaction(|tx| {
                    crate::runtime_db::transitions::persist_state_tx(tx, &execution)
                })
                .unwrap_err()
                .to_string()
                .contains("cleanup_fenced"));
            pause_deletion_before_private_purge(&host, job).await;
            assert_eq!(
                host.agent_identity_record(agent_id)
                    .unwrap()
                    .unwrap()
                    .status,
                AgentRegistryStatus::Deleting
            );
            let retired = host
                .runtime_db()
                .transitions()
                .load_execution_protocol_state_if_initialized(agent_id)
                .unwrap()
                .unwrap();
            assert!(retired.work_items.values().all(|record| !matches!(
                record.state,
                WorkItemExecutionState::Runnable { .. } | WorkItemExecutionState::InFlight { .. }
            )));
            assert_eq!(
                retired.work_items[&legacy[0].id],
                execution.work_items[&legacy[0].id]
            );
            for work in &legacy {
                assert_eq!(
                    host.runtime_db().work_items().latest(&work.id).unwrap(),
                    Some(work.clone())
                );
            }
            assert!(host
                .runtime_db()
                .transaction(|tx| {
                    crate::runtime_db::transitions::persist_state_tx(tx, &retired)
                })
                .unwrap_err()
                .to_string()
                .contains("cleanup_fenced"));
            resume_deletion_after_archive_failure(&host, agent_id).await;
            assert!(host
                .runtime_db()
                .transitions()
                .load_execution_protocol_state_if_initialized(agent_id)
                .unwrap()
                .is_none());
            for work in legacy {
                assert!(host
                    .runtime_db()
                    .work_items()
                    .latest(&work.id)
                    .unwrap()
                    .is_none());
            }
            host.shutdown().await.unwrap();
        }
    }

    #[tokio::test]
    async fn deletion_coordinator_resumes_from_persisted_phase() {
        let (_home, host) = test_host();

        // Create a public self-owned agent.
        let agent = AgentIdentityRecord::new(
            "resume-me",
            AgentKind::Default,
            AgentVisibility::Public,
            AgentOwnership::SelfOwned,
            AgentProfilePreset::PublicNamed,
            None,
            None,
        );
        host.append_agent_identity(&agent).unwrap();
        host.runtime_db().agent_identities().upsert(&agent).unwrap();

        // Begin deletion.
        let (_, job, _) = host
            .begin_public_agent_deletion("resume-me", false, "operator")
            .await
            .unwrap();

        // Simulate a crash after Quiesce by manually advancing the job phase.
        let mut advanced_job = job.clone();
        advanced_job.status = AgentDeletionStatus::Running;
        advanced_job.phase = AgentDeletionPhase::Ingress;
        advanced_job.updated_at = Utc::now();
        host.runtime_db()
            .agent_deletions()
            .update(&advanced_job)
            .unwrap();

        // Startup recovery makes the persisted ownerless Running job due.
        let recovery_at = Utc::now();
        assert_eq!(
            host.runtime_db()
                .agent_deletions()
                .recover_running_jobs(recovery_at)
                .unwrap(),
            1
        );
        let recovered_job = host
            .runtime_db()
            .agent_deletions()
            .latest_for_agent("resume-me")
            .unwrap()
            .expect("recovered job should exist");
        assert_eq!(recovered_job.status, AgentDeletionStatus::RetryableFailed);
        assert_eq!(recovered_job.phase, AgentDeletionPhase::Ingress);
        assert_eq!(recovered_job.next_attempt_at, Some(recovery_at));

        // Execute should resume from Ingress after recovery.
        host.execute_deletion_job(recovered_job).await.unwrap();

        // Verify completion.
        let final_job = host
            .runtime_db()
            .agent_deletions()
            .latest_for_agent("resume-me")
            .unwrap()
            .expect("job should exist");
        assert_eq!(final_job.status, AgentDeletionStatus::Completed);
        assert_eq!(
            host.agent_identity_record("resume-me")
                .unwrap()
                .unwrap()
                .status,
            AgentRegistryStatus::Deleted
        );
    }

    #[tokio::test]
    async fn deletion_cascade_private_children() {
        let (_home, host) = test_host();
        let parent_id = "cascade-parent";

        // Create parent agent.
        let parent = AgentIdentityRecord::new(
            parent_id,
            AgentKind::Default,
            AgentVisibility::Public,
            AgentOwnership::SelfOwned,
            AgentProfilePreset::PublicNamed,
            None,
            None,
        );
        host.append_agent_identity(&parent).unwrap();
        host.runtime_db()
            .agent_identities()
            .upsert(&parent)
            .unwrap();

        // Create a private child.
        let child = AgentIdentityRecord::new(
            "cascade-child",
            AgentKind::Child,
            AgentVisibility::Private,
            AgentOwnership::ParentSupervised,
            AgentProfilePreset::PrivateChild,
            Some(parent_id.to_string()),
            Some("task-1".to_string()),
        );
        host.append_agent_identity(&child).unwrap();
        host.runtime_db().agent_identities().upsert(&child).unwrap();
        let mut archived_child = AgentIdentityRecord::new(
            "cascade-archived-child",
            AgentKind::Child,
            AgentVisibility::Private,
            AgentOwnership::ParentSupervised,
            AgentProfilePreset::PrivateChild,
            Some(parent_id.to_string()),
            Some("task-archived".to_string()),
        );
        archived_child.status = AgentRegistryStatus::Deleted;
        archived_child.deleted_at = Some(archived_child.updated_at);
        host.append_agent_identity(&archived_child).unwrap();
        host.runtime_db()
            .agent_identities()
            .upsert(&archived_child)
            .unwrap();

        // Begin deletion with cascade.
        let (_, job, _) = host
            .begin_public_agent_deletion(parent_id, true, "operator")
            .await
            .unwrap();

        match host.execute_deletion_job(job).await {
            Ok(_) => {}
            Err(e) => panic!("deletion failed: {e:#}"),
        }

        // Both parent and child should be Deleted.
        assert_eq!(
            host.agent_identity_record(parent_id)
                .unwrap()
                .unwrap()
                .status,
            AgentRegistryStatus::Deleted
        );
        assert_eq!(
            host.agent_identity_record("cascade-child")
                .unwrap()
                .unwrap()
                .status,
            AgentRegistryStatus::Deleted
        );
        let archived_job = host
            .runtime_db()
            .agent_deletions()
            .latest_for_agent("cascade-archived-child")
            .unwrap()
            .expect("archived child repair job");
        assert_eq!(archived_job.mode, AgentDeletionMode::CleanupRepair);
        assert_eq!(archived_job.status, AgentDeletionStatus::Completed);
    }

