    #[tokio::test]
    async fn startup_recovery_skips_stopped_timer_only_owner() {
        let (_home, mut host) = canonical_test_host();
        let agent_id = "startup-timer-stopped";
        host.create_named_agent(agent_id, None).await.unwrap();
        host.unload_runtime(agent_id).await;
        let storage = host.agent_storage(agent_id).unwrap();
        let mut state = storage.read_agent().unwrap().unwrap();
        state.status = AgentStatus::Stopped;
        storage.write_agent_for_fixture(&state).unwrap();
        let overdue = Utc::now() - chrono::Duration::minutes(15);
        host.runtime_db()
            .timers()
            .upsert(&startup_timer_fixture(
                "timer-startup-stopped-1",
                agent_id,
                TimerStatus::Active,
                None,
                Some(overdue),
            ))
            .unwrap();
        host.runtime_db()
            .queue_entries()
            .upsert(&QueueEntryRecord {
                message_id: "message-startup-stopped-queued-1".into(),
                agent_id: agent_id.into(),
                priority: Priority::Normal,
                status: QueueEntryStatus::Queued,
                created_at: Utc::now(),
                updated_at: Utc::now(),
            })
            .unwrap();
        state.pending = 1;
        storage.write_agent_for_fixture(&state).unwrap();

        // Startup recovery runs on a new Host before any runtime activation.
        host = restart_fixture_host(host).await;
        host.recover_orphaned_queue_claims_at_startup()
            .await
            .unwrap();

        assert!(host.try_get_loaded_runtime(agent_id).await.is_none());
        let timer = storage
            .latest_timer_record("timer-startup-stopped-1")
            .unwrap()
            .unwrap();
        assert_eq!(timer.status, TimerStatus::Cancelled);
        assert_eq!(timer.fire_count, 0);
        assert_startup_timer_tick_count(&storage, "timer-startup-stopped-1", 0);
        let queue_entry = host
            .runtime_db()
            .queue_entries()
            .latest_all()
            .unwrap()
            .into_iter()
            .find(|entry| entry.message_id == "message-startup-stopped-queued-1")
            .expect("stopped startup input should remain durable for reconciliation");
        assert_eq!(queue_entry.status, QueueEntryStatus::Aborted);
        let state = storage.read_agent().unwrap().unwrap();
        assert_eq!(state.status, AgentStatus::Stopped);
        assert_eq!(state.pending, 0);
    }

